#[test]
fn test_return_void() {
    let cxx = indoc! {"
        void do_nothing() {
        }
    "};
    let hdr = indoc! {"
        void do_nothing();
    "};
    let rs = quote! {
        ffi::do_nothing();
    };
    run_test(cxx, hdr, rs, &["do_nothing"], &[]);
}

#[test]
fn test_two_funcs() {
    let cxx = indoc! {"
        void do_nothing1() {
        }
        void do_nothing2() {
        }
    "};
    let hdr = indoc! {"
        void do_nothing1();
        void do_nothing2();
    "};
    let rs = quote! {
        ffi::do_nothing1();
        ffi::do_nothing2();
    };
    run_test(cxx, hdr, rs, &["do_nothing1", "do_nothing2"], &[]);
}

#[test]
fn test_two_funcs_with_definition() {
    // Test to ensure C++ header isn't included twice
    let cxx = indoc! {"
        void do_nothing1() {
        }
        void do_nothing2() {
        }
    "};
    let hdr = indoc! {"
        struct Bob {
            int a;
        };
        void do_nothing1();
        void do_nothing2();
    "};
    let rs = quote! {
        ffi::do_nothing1();
        ffi::do_nothing2();
    };
    run_test(cxx, hdr, rs, &["do_nothing1", "do_nothing2"], &[]);
}

#[test]
fn test_return_i32() {
    let cxx = indoc! {"
        uint32_t give_int() {
            return 5;
        }
    "};
    let hdr = indoc! {"
        #include <cstdint>
        uint32_t give_int();
    "};
    let rs = quote! {
        assert_eq!(ffi::give_int(), 5);
    };
    run_test(cxx, hdr, rs, &["give_int"], &[]);
}

#[test]
fn test_take_i32() {
    let cxx = indoc! {"
        uint32_t take_int(uint32_t a) {
            return a + 3;
        }
    "};
    let hdr = indoc! {"
        #include <cstdint>
        uint32_t take_int(uint32_t a);
    "};
    let rs = quote! {
        assert_eq!(ffi::take_int(3), 6);
    };
    run_test(cxx, hdr, rs, &["take_int"], &[]);
}

#[test]
fn test_nested_module() {
    let cxx = indoc! {"
        void do_nothing() {
        }
    "};
    let hdr = indoc! {"
        void do_nothing();
    "};
    let hexathorpe = Token![#](Span::call_site());
    let unexpanded_rust = quote! {
        mod a {
            use autocxx::prelude::*;

            include_cpp!(
                #hexathorpe include "input.h"
                generate!("do_nothing")
                safety!(unsafe)
            );

            pub use ffi::*;
        }

        fn main() {
            a::do_nothing();
        }
    };

    do_run_test_manual(cxx, hdr, unexpanded_rust, None, None).unwrap();
}

#[test]
#[cfg(target_pointer_width = "64")]
fn test_return_big_ints() {
    let cxx = indoc! {"
    "};
    let hdr = indoc! {"
        #include <cstdint>
        inline uint32_t give_u32() {
            return 5;
        }
        inline uint64_t give_u64() {
            return 5;
        }
        inline int32_t give_i32() {
            return 5;
        }
        inline int64_t give_i64() {
            return 5;
        }
    "};
    let rs = quote! {
        assert_eq!(ffi::give_u32(), 5);
        assert_eq!(ffi::give_u64(), 5);
        assert_eq!(ffi::give_i32(), 5);
        assert_eq!(ffi::give_i64(), 5);
    };
    run_test(
        cxx,
        hdr,
        rs,
        &["give_u32", "give_u64", "give_i32", "give_i64"],
        &[],
    );
}

/// `__int128`, which was the rest of `test_return_big_ints` while it was
/// ignored. cxx has no atom that wide, so it travels under a name of its own
/// exactly as `autocxx::c_int` does. Rust settled `i128`'s C ABI in 1.78,
/// which "completed the announced `u128`/`i128` ABI change for x86-32 and
/// x86-64 targets" and closed rust-lang/rust#54341 - the thing the upstream
/// report was waiting for.
///
/// Not compiled for MSVC, which has no `__int128` at all.
#[test]
#[cfg(all(target_pointer_width = "64", not(target_env = "msvc")))]
fn test_return_int128() {
    let hdr = indoc! {"
        inline __int128 give_i128() {
            return 5;
        }
        inline __int128 round_trip_i128(__int128 x) {
            return x;
        }
    "};
    let rs = quote! {
        assert_eq!(ffi::give_i128(), autocxx::c_i128(5));
        assert_eq!(ffi::round_trip_i128(autocxx::c_i128(i128::MIN + 7)).0, i128::MIN + 7);
    };
    run_test("", hdr, rs, &["give_i128", "round_trip_i128"], &[]);
}

/// `unsigned __int128`, the other half of `test_return_int128`. It travels as
/// `autocxx::c_u128`, and can only do so because it is now the one C++ type
/// which arrives as a bare `u128`: a 16-byte `long double` and a `__float128`
/// used to reach us as that same token, and each is marked and refused by name
/// of its own now. See the note beside the ctypes in
/// `engine/src/known_types.rs`.
///
/// Not compiled for MSVC, which has no `__int128` at all.
#[test]
#[cfg(all(target_pointer_width = "64", not(target_env = "msvc")))]
fn test_return_uint128() {
    let hdr = indoc! {"
        inline unsigned __int128 give_u128() {
            return 5;
        }
        inline unsigned __int128 round_trip_u128(unsigned __int128 x) {
            return x;
        }
    "};
    let rs = quote! {
        assert_eq!(ffi::give_u128(), autocxx::c_u128(5));
        assert_eq!(ffi::round_trip_u128(autocxx::c_u128(u128::MAX - 7)).0, u128::MAX - 7);
    };
    run_test("", hdr, rs, &["give_u128", "round_trip_u128"], &[]);
}

/// The type which used to share that token. bindgen renders a `__float128` as
/// `u128` because that is the right size and Rust has no 128-bit float, so
/// without the marker `34-float128-newtype-marker.patch` puts round it the
/// signature would be bound as the integer beside it and read as a different
/// kind of number on both sides. Refused by name instead.
///
/// `__float128` exists on x86 Linux and nowhere else clang will admit to - not
/// even x86 macOS - so bindgen is told to parse as that target and the build is
/// skipped, which is what lets this run everywhere rather than on one CI leg.
#[test]
fn test_float128_is_refused_by_name() {
    let hdr = indoc! {"
        inline __float128 give_f128() {
            return 5;
        }
    "};
    run_test_expect_fail_with_error_modified(
        "",
        hdr,
        quote! {},
        directives_from_lists(&["give_f128"], &[], None),
        float128_target(),
        // Not just the name: this used to be refused as "either an
        // `unsigned __int128` or a `__float128`", which mentions it too.
        "`__float128`, a 128-bit floating-point type",
    );
}

/// A `__float128` *field* is bytes the struct carries, which is fine - but the
/// struct cannot then cross by value, because a 16-byte float and the 16-byte
/// integer standing in for it are not passed the same way. So the type stays
/// opaque, and its accessor is refused by name rather than handing back the
/// integer.
#[test]
fn test_float128_field_makes_a_type_non_pod() {
    let hdr = indoc! {"
        struct HasF128 { __float128 f; };
    "};
    run_test_expect_fail_with_error_modified(
        "",
        hdr,
        quote! {},
        directives_from_lists(&[], &["HasF128"], None),
        float128_target(),
        "could not be POD because it has a `__float128` member",
    );
    run_test_ex(
        "",
        hdr,
        quote! {},
        directives_from_lists(&["HasF128"], &[], None),
        float128_target(),
        Some(make_checks_without_building(vec![make_string_finder(
            [
                // The type survives - an error stub for the whole of it would
                // satisfy the message on its own.
                "impl UniquePtr < HasF128 >",
                "`__float128`",
            ]
            .map(|s| s.to_string())
            .to_vec(),
        )])),
        None,
    );
}

/// A `__float128` *variable* is turned down by name too. It reaches us by a
/// route of its own - a variable is re-exported as bindgen declared it rather
/// than converted, so nothing on the conversion path sees it - and a silent
/// re-export would hand Rust the bytes of a float to do integer arithmetic on.
#[test]
fn test_float128_static() {
    let cxx = indoc! {"
        const __float128 F = 1.0;
    "};
    let hdr = indoc! {"
        extern const __float128 F;
    "};
    run_test_expect_fail_with_error_modified(
        cxx,
        hdr,
        quote! {},
        directives_from_lists(&["F"], &[], None),
        float128_target(),
        "`__float128`, a 128-bit floating-point type",
    );
}

/// A `__float128` as a template argument, which reaches the C++ by a route of
/// its own: a concrete instantiation is named by writing its arguments out
/// again, without converting them, so nothing else would catch the marker and
/// it would land in the generated header verbatim.
#[test]
fn test_float128_template_argument() {
    let hdr = indoc! {"
        template <typename T> struct Wrapper { T x; };
        inline int unbox(const Wrapper<__float128>& b) { return 1; }
    "};
    run_test_expect_fail_with_error_modified(
        "",
        hdr,
        quote! {},
        directives_from_lists(&["unbox"], &[], None),
        float128_target(),
        "`__float128`, a 128-bit floating-point type",
    );
}

/// The target the `__float128` tests ask bindgen to parse as. See
/// `make_bindgen_only_clang_arg_adder`.
fn float128_target() -> Option<BuilderModifier> {
    make_bindgen_only_clang_arg_adder(&["--target=x86_64-unknown-linux-gnu"])
}

/// A container of either 128-bit integer is refused: `autocxx::c_type_vectors`
/// is compiled on every target autocxx supports and MSVC has no `__int128`, so
/// there is no `UniquePtrTarget` for `c_i128` or `c_u128` to be had and letting
/// the signature through would buy a missing `cxxbridge1$unique_ptr$...` symbol
/// at link time.
#[test]
#[cfg(all(target_pointer_width = "64", not(target_env = "msvc")))]
fn test_int128_containers_are_refused() {
    let hdr = indoc! {"
        #include <memory>
        #include <vector>
        class Thing {
        public:
            Thing() {}
            std::unique_ptr<__int128> up() const { return nullptr; }
            const std::vector<__int128>& vec() const;
            std::unique_ptr<unsigned __int128> uup() const { return nullptr; }
            const std::vector<unsigned __int128>& uvec() const;
            __int128 plain() const { return 3; }
            unsigned __int128 uplain() const { return 4; }
        };
    "};
    let rs = quote! {
        let thing = ffi::Thing::new().within_unique_ptr();
        assert_eq!(thing.plain(), autocxx::c_i128(3));
        assert_eq!(thing.uplain(), autocxx::c_u128(4));
    };
    run_test("", hdr, rs, &["Thing"], &[]);
}

/// `cxx::UniquePtr<T>` needs `T: UniquePtrTarget`, and that trait's methods
/// bottom out in `extern "C"` shims named `cxxbridge1$unique_ptr$...` which
/// only the `#[cxx::bridge]` macro can emit. For a named type - `c_int`, say -
/// the macro emits them on request, which is how `test_give_up_ctype` below
/// works; for a `u32` there is no request to make, because
/// `check_type_unique_ptr` turns down any `unique_ptr` whose target is one of
/// cxx's own atoms.
///
/// `uint32_t` and `unsigned int` are the same C++ type here, though, and only
/// one of the two spellings is an atom - so name the payload the way the one
/// that works is named. `autocxx::c_u32` is a `uint32_t` under a name cxx
/// takes, and the wrapper is what Rust receives.
#[test]
fn test_give_up_int() {
    let cxx = indoc! {"
        std::unique_ptr<uint32_t> give_up() {
            return std::make_unique<uint32_t>(12);
        }
    "};
    let hdr = indoc! {"
        #include <cstdint>
        #include <memory>
        std::unique_ptr<uint32_t> give_up();
    "};
    let rs = quote! {
        assert_eq!(*ffi::give_up().as_ref().unwrap(), autocxx::c_u32(12));
    };
    run_test(cxx, hdr, rs, &["give_up"], &[]);
}

/// A character type inside a container is a named type to cxx exactly as
/// `c_int` is, so the same explicit shim trait impls in
/// `autocxx::c_type_vectors` make it a payload. It escapes the fixed-width
/// substitution on the way there: bindgen gives each character type a marker
/// of its own, so none arrives as the bare `u32` a `uint32_t` does, and each
/// travels as its own newtype throughout.
#[test]
fn test_give_up_char32_t() {
    let cxx = indoc! {"
        std::unique_ptr<char32_t> give_up() {
            return std::make_unique<char32_t>(U'x');
        }
    "};
    let hdr = indoc! {"
        #include <memory>
        std::unique_ptr<char32_t> give_up();
    "};
    let rs = quote! {
        assert_eq!(
            *ffi::give_up().as_ref().unwrap(),
            autocxx::c_char32_t('x' as u32)
        );
    };
    run_test(cxx, hdr, rs, &["give_up"], &[]);
}

/// The other three containers, over the other two character types autocxx
/// ships glue for. `wchar_t`'s width is the target's, which is why its
/// newtype's payload is a `cfg`-selected alias and why nothing here writes a
/// literal of that type.
#[test]
fn test_character_types_in_containers() {
    let hdr = indoc! {"
        #include <memory>
        #include <vector>
        inline std::unique_ptr<std::vector<char16_t>> chars() {
            return std::make_unique<std::vector<char16_t>>(
                std::vector<char16_t>{ u'a', u'b' });
        }
        inline std::shared_ptr<wchar_t> share_wide() {
            return std::make_shared<wchar_t>(L'z');
        }
        inline std::weak_ptr<wchar_t> weaken(std::shared_ptr<wchar_t> a) {
            return std::weak_ptr<wchar_t>(a);
        }
    "};
    let rs = quote! {
        let v = ffi::chars();
        assert_eq!(v.len(), 2);
        assert_eq!(*v.get(1).unwrap(), autocxx::c_char16_t('b' as u16));
        let w = ffi::share_wide();
        assert_eq!(
            *ffi::weaken(w.clone()).upgrade().as_ref().unwrap(),
            autocxx::c_wchar_t('z' as autocxx::wchar_t)
        );
    };
    run_test("", hdr, rs, &["chars", "share_wide", "weaken"], &[]);
}

/// `char8_t` is the one character type with no container glue. The typedef
/// naming it has to compile in `c_type_vectors.h`, which this crate builds at
/// the C++14 floor every autocxx consumer gets, and `char8_t` is a C++20
/// keyword: before C++20 the typedef names nothing. So the payload is refused,
/// and the refusal costs the one method rather than the bridge.
#[test]
fn test_char8_t_containers_are_refused() {
    let hdr = indoc! {"
        #include <cstdint>
        #include <memory>
        class Thing {
        public:
            Thing() {}
            std::unique_ptr<char8_t> up() const {
                return std::make_unique<char8_t>(u8'x');
            }
            uint32_t unrelated() const { return 7; }
        };
    "};
    let rs = quote! {
        assert_eq!(ffi::Thing::new().within_unique_ptr().unrelated(), 7);
    };
    run_test_ex(
        "",
        hdr,
        rs,
        directives_from_lists(&["Thing"], &[], None),
        make_cpp20_adder(),
        None,
        None,
    );
}

/// A payload reached through an alias keeps its atom, and the refusal that
/// goes with it.
///
/// `bindgen` drops the `const` off an alias's target - `using CU32 = const
/// uint32_t` arrives as `pub type CU32 = u32` - so by the time autocxx sees
/// this payload nothing anywhere says it is really a `const uint32_t`. Naming
/// it with the wrapper would declare a `unique_ptr` of a mutable one and the
/// shim would not bind, which costs the whole bridge instead of the one
/// function. Only a payload `bindgen` wrote as the atom itself is renamed.
///
/// The lost `const` is its own bug and an older one: the same header with a
/// class payload gets that same C++ error today, with no wrapper involved.
#[test]
fn test_const_alias_within_unique_ptr_is_still_refused() {
    let hdr = indoc! {"
        #include <cstdint>
        #include <memory>
        using CU32 = const uint32_t;
        class Thing {
        public:
            Thing() {}
            std::unique_ptr<CU32> up() const { return nullptr; }
            uint32_t unrelated() const { return 7; }
        };
    "};
    let rs = quote! {
        assert_eq!(ffi::Thing::new().within_unique_ptr().unrelated(), 7);
    };
    run_test("", hdr, rs, &["Thing"], &[]);
}

/// The rest of the fixed-width family, each one round-tripped so that the
/// wrapper is proved to carry the value rather than merely to compile.
/// `int8_t` and `uint64_t` are the interesting ends: the first is `signed
/// char`, which is not cxx's `c_char`, and the second is `unsigned long` on
/// some targets and `unsigned long long` on others - the wrapper mirrors what
/// C++ wrote either way. `u32` is covered by `test_give_up_int` above.
#[test]
fn test_cycle_fixed_width_ints_through_unique_ptr() {
    let hdr = indoc! {"
        #include <cstdint>
        #include <memory>
        inline std::unique_ptr<uint8_t> up_u8(uint8_t v) {
            return std::make_unique<uint8_t>(v);
        }
        inline std::unique_ptr<int8_t> up_i8(int8_t v) {
            return std::make_unique<int8_t>(v);
        }
        inline std::unique_ptr<uint16_t> up_u16(uint16_t v) {
            return std::make_unique<uint16_t>(v);
        }
        inline std::unique_ptr<int16_t> up_i16(int16_t v) {
            return std::make_unique<int16_t>(v);
        }
        inline std::unique_ptr<int32_t> up_i32(int32_t v) {
            return std::make_unique<int32_t>(v);
        }
        inline std::unique_ptr<uint64_t> up_u64(uint64_t v) {
            return std::make_unique<uint64_t>(v);
        }
        inline std::unique_ptr<int64_t> up_i64(int64_t v) {
            return std::make_unique<int64_t>(v);
        }
        inline uint64_t take_u64(std::unique_ptr<uint64_t> v) { return *v; }
        inline int8_t take_i8(std::unique_ptr<int8_t> v) { return *v; }
    "};
    let rs = quote! {
        assert_eq!(ffi::up_u8(255).as_ref().unwrap().0, 255u8);
        assert_eq!(ffi::up_i8(-5).as_ref().unwrap().0, -5i8);
        assert_eq!(ffi::up_u16(65535).as_ref().unwrap().0, 65535u16);
        assert_eq!(ffi::up_i16(i16::MIN).as_ref().unwrap().0, i16::MIN);
        assert_eq!(ffi::up_i32(i32::MIN).as_ref().unwrap().0, i32::MIN);
        assert_eq!(ffi::up_u64(u64::MAX).as_ref().unwrap().0, u64::MAX);
        assert_eq!(ffi::up_i64(i64::MIN).as_ref().unwrap().0, i64::MIN);
        assert_eq!(ffi::take_u64(ffi::up_u64(7)), 7);
        assert_eq!(ffi::take_i8(ffi::up_i8(-3)), -3);
    };
    run_test(
        "",
        hdr,
        rs,
        &[
            "up_u8", "up_i8", "up_u16", "up_i16", "up_i32", "up_u64", "up_i64", "take_u64",
            "take_i8",
        ],
        &[],
    );
}

/// A `std::unique_ptr<int>`, which is to say of `autocxx::c_int`. Unlike
/// `test_give_up_int` directly above, this one is ours to make work: `c_int`
/// is a named type rather than one of cxx's built-in atoms, so cxx's macro
/// will synthesize `UniquePtrTarget` for it given an explicit
/// `impl UniquePtr<c_int> {}` - which `autocxx::c_type_vectors` writes, in
/// this crate, once for everybody. See google/autocxx#422.
#[test]
fn test_give_up_ctype() {
    let cxx = indoc! {"
        std::unique_ptr<int> give_up() {
            return std::make_unique<int>(12);
        }
    "};
    let hdr = indoc! {"
        #include <memory>
        std::unique_ptr<int> give_up();
    "};
    let rs = quote! {
        assert_eq!(*ffi::give_up().as_ref().unwrap(), autocxx::c_int(12));
    };
    run_test(cxx, hdr, rs, &["give_up"], &[]);
}

/// The other two C++ smart pointers of a plain C integer. `autocxx::c_int` is
/// a named type to cxx, which all three containers accept, so all three need
/// the shim trait impls - letting `unique_ptr` through alone would turn a
/// clean rejection of these into a link error.
#[test]
fn test_share_ctype() {
    let hdr = indoc! {"
        #include <memory>
        inline std::shared_ptr<int> share_up() {
            return std::make_shared<int>(12);
        }
        inline int take_shared(std::shared_ptr<int> a) { return *a; }
        inline std::weak_ptr<int> shared_to_weak(std::shared_ptr<int> a) {
            return std::weak_ptr<int>(a);
        }
    "};
    let rs = quote! {
        let a = ffi::share_up();
        assert_eq!(ffi::take_shared(a.clone()), autocxx::c_int(12));
        assert_eq!(*ffi::shared_to_weak(a.clone()).upgrade().as_ref().unwrap(), autocxx::c_int(12));
    };
    run_test(
        "",
        hdr,
        rs,
        &["share_up", "take_shared", "shared_to_weak"],
        &[],
    );
}

/// cxx takes every numeric atom, and `bool`, inside a `shared_ptr` or a
/// `weak_ptr` - `check_type_shared_ptr` and `check_type_weak_ptr` in cxx-gen
/// 0.7.200 `src/syntax/check.rs`, lines 165 and 188 - and implements
/// `SharedPtrTarget`/`WeakPtrTarget` for each. Only `check_type_unique_ptr`
/// (line 147) turns them down, so asking the `unique_ptr` question of all
/// three refused these for no reason. `bool` is the one `std::vector` will
/// not take, and `double` the one nothing objects to anywhere.
#[test]
fn test_share_atoms() {
    let hdr = indoc! {"
        #include <cstdint>
        #include <memory>
        inline std::shared_ptr<uint32_t> share_up() {
            return std::make_shared<uint32_t>(12);
        }
        inline uint32_t take_shared(std::shared_ptr<uint32_t> a) { return *a; }
        inline std::weak_ptr<uint32_t> shared_to_weak(std::shared_ptr<uint32_t> a) {
            return std::weak_ptr<uint32_t>(a);
        }
        inline std::shared_ptr<bool> share_bool() { return std::make_shared<bool>(true); }
        inline std::shared_ptr<double> share_double() { return std::make_shared<double>(1.5); }
    "};
    let rs = quote! {
        let a = ffi::share_up();
        assert_eq!(ffi::take_shared(a.clone()), 12);
        assert_eq!(*ffi::shared_to_weak(a.clone()).upgrade().as_ref().unwrap(), 12);
        assert!(*ffi::share_bool().as_ref().unwrap());
        assert_eq!(*ffi::share_double().as_ref().unwrap(), 1.5);
    };
    run_test(
        "",
        hdr,
        rs,
        &[
            "share_up",
            "take_shared",
            "shared_to_weak",
            "share_bool",
            "share_double",
        ],
        &[],
    );
}

/// An atom reached through an alias is refused, because bindgen drops the
/// `const` off an alias's target - `using CU32 = const uint32_t` arrives as
/// `pub type CU32 = u32` - and the bridge would then declare a `shared_ptr` of
/// a mutable one, which the shim cannot bind. That costs the whole bridge
/// where a refusal costs the one function, and these payloads were refused
/// outright before the atoms were let in.
#[test]
fn test_const_alias_within_shared_ptr_is_refused() {
    let hdr = indoc! {"
        #include <cstdint>
        #include <memory>
        using CU32 = const uint32_t;
        class Thing {
        public:
            Thing() {}
            std::shared_ptr<CU32> sp() const { return nullptr; }
            std::weak_ptr<CU32> wp() const { return std::weak_ptr<CU32>(); }
            uint32_t unrelated() const { return 7; }
        };
    "};
    let rs = quote! {
        assert_eq!(ffi::Thing::new().within_unique_ptr().unrelated(), 7);
    };
    run_test("", hdr, rs, &["Thing"], &[]);
}

/// The other half of the same split. cxx turns down a `shared_ptr` of a
/// `vector` - "std::shared_ptr<std::vector> is not supported yet",
/// `check_type_shared_ptr` again - where it takes a `unique_ptr` of one. Ask
/// the `unique_ptr` question and the bridge is emitted and then rejected
/// whole, which costs every other binding in the same `include_cpp!`;
/// refusing it here costs only the function.
#[test]
fn test_shared_ptr_of_vector_refused_without_the_rest_of_the_bridge() {
    let hdr = indoc! {"
        #include <cstdint>
        #include <memory>
        #include <vector>
        class Thing {
        public:
            Thing() {}
            std::shared_ptr<std::vector<uint32_t>> share_vec() const {
                return std::make_shared<std::vector<uint32_t>>();
            }
            uint32_t unrelated() const { return 7; }
        };
    "};
    let rs = quote! {
        assert_eq!(ffi::Thing::new().within_unique_ptr().unrelated(), 7);
    };
    run_test("", hdr, rs, &["Thing"], &[]);
}

