/// A type whose move constructor is deleted, but which can still be copied,
/// must still be passable by value. C++ overload resolution prefers a deleted
/// move constructor to a perfectly good copy constructor, so the `std::move`
/// the generated wrapper used to apply to every value parameter refused to
/// compile for these. See <https://github.com/google/autocxx/issues/873>.
#[test]
fn test_pass_by_value_deleted_move_constructor() {
    let hdr = indoc! {"
    #include <string>
    struct A {
        A() {}
        A(const A&) {}
        A(A&&) = delete;
        std::string so_we_are_non_trivial;
    };
    inline void take_a(A) {}
    struct B {
        void take_a(A) const {}
        // Force autocxx to generate a wrapper for the method above.
        void take_a(A, int) const {}
    };
    "};
    let rs = quote! {
        moveit! {
            let stack_obj = ffi::A::new();
        }
        ffi::take_a(&*stack_obj);
        ffi::take_a(as_copy(stack_obj.as_ref()));

        let heap_obj = ffi::A::new().within_unique_ptr();
        ffi::take_a(&heap_obj);
        ffi::take_a(heap_obj); // consume

        let b = ffi::B::new().within_unique_ptr();
        b.take_a(&*stack_obj);
        b.take_a1(as_copy(stack_obj.as_ref()), autocxx::c_int(3));
    };
    run_test("", hdr, rs, &["A", "B", "take_a"], &[]);
}

/// Handing a value parameter to C++ should move it where C++ allows that - the
/// Rust side owns the storage it comes out of and destroys it straight
/// afterwards - and should fall back to a copy only where the move constructor
/// can't be called. See <https://github.com/google/autocxx/issues/873>.
#[test]
fn test_pass_by_value_moves_where_it_can() {
    let hdr = indoc! {"
    #include <cstdint>
    #include <string>
    inline int32_t& copies() { static int32_t c = 0; return c; }
    inline int32_t& moves() { static int32_t m = 0; return m; }
    struct Movable {
        Movable() {}
        Movable(const Movable&) { copies()++; }
        Movable(Movable&&) { moves()++; }
        std::string so_we_are_non_trivial;
    };
    struct Unmovable {
        Unmovable() {}
        Unmovable(const Unmovable&) { copies()++; }
        Unmovable(Unmovable&&) = delete;
        std::string so_we_are_non_trivial;
    };
    inline void take_movable(Movable) {}
    inline void take_unmovable(Unmovable) {}
    inline int32_t copy_count() { return copies(); }
    inline int32_t move_count() { return moves(); }
    inline void reset_counts() { copies() = 0; moves() = 0; }
    "};
    let rs = quote! {
        // Consuming a UniquePtr hands C++ the object Rust was about to
        // destroy, so it should be moved, not copied.
        let heap_obj = ffi::Movable::new().within_unique_ptr();
        ffi::reset_counts();
        ffi::take_movable(heap_obj);
        assert_eq!(ffi::copy_count(), 0);
        assert_eq!(ffi::move_count(), 1);

        // Borrowing one costs a copy into Rust-side storage, and then a move
        // out of that storage into the parameter.
        let heap_obj = ffi::Movable::new().within_unique_ptr();
        ffi::reset_counts();
        ffi::take_movable(&heap_obj);
        assert_eq!(ffi::copy_count(), 1);
        assert_eq!(ffi::move_count(), 1);

        // A type which can't be moved is copied instead of failing to build.
        let heap_obj = ffi::Unmovable::new().within_unique_ptr();
        ffi::reset_counts();
        ffi::take_unmovable(heap_obj);
        assert_eq!(ffi::copy_count(), 1);
        assert_eq!(ffi::move_count(), 0);
    };
    run_test(
        "",
        hdr,
        rs,
        &[
            "Movable",
            "Unmovable",
            "take_movable",
            "take_unmovable",
            "copy_count",
            "move_count",
            "reset_counts",
        ],
        &[],
    );
}

/// A value parameter out of the owning C++ reference wrappers. A `CppPin` or a
/// `CppUniquePtrPin` owns its object outright, so handing one to C++ consumes
/// it, and C++ moves out of it where the type allows a move, just as consuming
/// a `UniquePtr` does. Keeping the object instead means copying out of it, and
/// that is where the `unsafe` lives: these wrappers exist because C++ may hold
/// aliasing references to what they hold, so neither hands out a Rust
/// reference for free.
#[test]
fn test_pass_by_value_from_cpp_reference_wrappers() {
    let hdr = indoc! {"
    #include <cstdint>
    #include <string>
    inline int32_t& copies() { static int32_t c = 0; return c; }
    inline int32_t& moves() { static int32_t m = 0; return m; }
    struct A {
        A() : a(0) {}
        A(const A& other) : a(other.a) { copies()++; }
        A(A&& other) : a(other.a) { moves()++; }
        void set(uint32_t val) { a = val; }
        uint32_t a;
        std::string so_we_are_non_trivial;
    };
    inline uint32_t take_a(A a) { return a.a; }
    inline int32_t copy_count() { return copies(); }
    inline int32_t move_count() { return moves(); }
    inline void reset_counts() { copies() = 0; moves() = 0; }
    "};
    let rs = quote! {
        // A `CppPin` around storage which Rust allocated.
        let mut obj = ffi::A::new().within_box();
        obj.as_mut().set(42);
        let pin = CppPin::from_pinned_box(obj);
        // Copying out of it keeps the object: a copy into Rust-side storage,
        // then a move out of that storage into the parameter.
        ffi::reset_counts();
        assert_eq!(ffi::take_a(as_copy(unsafe { pin.as_ref() })), 42);
        assert_eq!(ffi::copy_count(), 1);
        assert_eq!(ffi::move_count(), 1);
        // Handing over the pin itself consumes it, and costs no copy.
        ffi::reset_counts();
        assert_eq!(ffi::take_a(pin), 42);
        assert_eq!(ffi::copy_count(), 0);
        assert_eq!(ffi::move_count(), 1);

        // And a `CppUniquePtrPin`, which owns a C++-side allocation.
        let mut obj = ffi::A::new().within_unique_ptr();
        obj.pin_mut().set(43);
        let pin = CppUniquePtrPin::new(obj);
        ffi::reset_counts();
        assert_eq!(ffi::take_a(pin), 43);
        assert_eq!(ffi::copy_count(), 0);
        assert_eq!(ffi::move_count(), 1);
    };
    run_test(
        "",
        hdr,
        rs,
        &["A", "take_a", "copy_count", "move_count", "reset_counts"],
        &[],
    );
}

/// A type whose only copy constructor takes `T&` rather than `const T&` can be
/// passed by value from an lvalue, which is exactly what the generated wrapper
/// has. Neither `std::move` nor a `const T&` will bind to that constructor, so
/// the wrapper has to hand the parameter over as a plain mutable lvalue.
/// See <https://github.com/google/autocxx/issues/873>.
#[test]
fn test_pass_by_value_non_const_copy_constructor() {
    let hdr = indoc! {"
    #include <cstdint>
    #include <string>
    inline int32_t& mutable_copies() { static int32_t c = 0; return c; }
    struct MutableCopyOnly {
        MutableCopyOnly() {}
        MutableCopyOnly(MutableCopyOnly&) { mutable_copies()++; }
        MutableCopyOnly(MutableCopyOnly&&) = delete;
        std::string so_we_are_non_trivial;
    };
    inline void take_it(MutableCopyOnly) {}
    inline int32_t mutable_copy_count() { return mutable_copies(); }
    "};
    let rs = quote! {
        let obj = ffi::MutableCopyOnly::new().within_unique_ptr();
        ffi::take_it(obj);
        assert_eq!(ffi::mutable_copy_count(), 1);
    };
    run_test(
        "",
        hdr,
        rs,
        &["MutableCopyOnly", "take_it", "mutable_copy_count"],
        &[],
    );
}

/// Which of the two shapes of copy constructor a class has is decided by
/// constness alone: `T(const T&)` and `T(const volatile T&)` both accept a
/// const source, so both are bridgeable as `CopyNew`, while `T(T&)` and
/// `T(volatile T&)` are neither. That distinction is what C++ consults when
/// deciding the shape of a *containing* class's implicit copy constructor,
/// so it has to stay exactly on the const axis.
#[test]
fn test_copy_constructor_qualifier_forms() {
    let hdr = indoc! {"
    #include <cstdint>
    #include <string>
    struct QConst { QConst() {} QConst(const QConst&) {} std::string s; };
    struct QConstVolatile {
        QConstVolatile() {}
        QConstVolatile(const volatile QConstVolatile&) {}
        std::string s;
    };
    struct QNonConst { QNonConst() {} QNonConst(QNonConst&) {} std::string s; };
    struct QVolatile { QVolatile() {} QVolatile(volatile QVolatile&) {} std::string s; };
    "};
    let rs = quote! {
        static_assertions::assert_impl_all!(ffi::QConst: moveit::CopyNew);
        static_assertions::assert_impl_all!(ffi::QConstVolatile: moveit::CopyNew);
        static_assertions::assert_not_impl_any!(ffi::QNonConst: moveit::CopyNew);
        static_assertions::assert_not_impl_any!(ffi::QVolatile: moveit::CopyNew);
        // The two non-const forms are still bound, as ordinary constructors.
        let _ = ffi::QNonConst::new().within_unique_ptr();
        let _ = ffi::QVolatile::new().within_unique_ptr();
    };
    run_test(
        "",
        hdr,
        rs,
        &["QConst", "QConstVolatile", "QNonConst", "QVolatile"],
        &[],
    );
}

/// A class is handed an implicit `T(T&)` rather than an implicit
/// `T(const T&)` when one of its fields has no copy constructor accepting a
/// const source. autocxx can't express that shape, so it must synthesize
/// nothing at all rather than a `T(const T&)` wrapper C++ would refuse - and
/// it should say so in the bindings.
#[test]
fn test_member_with_only_non_const_copy_constructor() {
    let hdr = indoc! {"
    #include <cstdint>
    #include <string>
    struct MutableCopyOnly {
        MutableCopyOnly() {}
        MutableCopyOnly(MutableCopyOnly&) {}
        std::string so_we_are_non_trivial;
    };
    struct Holder {
        Holder() {}
        MutableCopyOnly m;
    };
    "};
    let rs = quote! {
        static_assertions::assert_not_impl_any!(ffi::Holder: moveit::CopyNew);
        let _ = ffi::Holder::new().within_unique_ptr();
    };
    run_test_ex(
        "",
        hdr,
        rs,
        directives_from_lists(&["Holder", "MutableCopyOnly"], &[], None),
        None,
        Some(make_string_finder(
            [
                "but as `T(T&)` rather than `T(const T&)`",
                "its field `m` of type `MutableCopyOnly` has no copy constructor accepting a const source",
            ]
            .map(|s| s.to_string())
            .to_vec(),
        )),
        None,
    );
}

/// The same class without the `= delete`d move constructor. Declaring
/// `T(T&)` is enough on its own for C++ to declare neither an implicit
/// `T(const T&)` nor an implicit `T(T&&)`, so autocxx must not synthesize
/// wrappers which call either of them.
#[test]
fn test_only_non_const_copy_constructor() {
    let hdr = indoc! {"
    #include <cstdint>
    #include <string>
    inline int32_t& mutable_copies() { static int32_t c = 0; return c; }
    struct MutableCopyOnly {
        MutableCopyOnly() {}
        MutableCopyOnly(MutableCopyOnly&) { mutable_copies()++; }
        std::string so_we_are_non_trivial;
    };
    inline void take_it(MutableCopyOnly) {}
    inline int32_t mutable_copy_count() { return mutable_copies(); }
    "};
    let rs = quote! {
        let obj = ffi::MutableCopyOnly::new().within_unique_ptr();
        ffi::take_it(obj);
        assert_eq!(ffi::mutable_copy_count(), 1);
    };
    run_test(
        "",
        hdr,
        rs,
        &["MutableCopyOnly", "take_it", "mutable_copy_count"],
        &[],
    );
}

/// The helper which hands a value parameter over is called with an argument of
/// the parameter's own type, so C++ looks for it in that type's namespaces
/// too, where a function of the same name would be a better match than our
/// template. The generated call has to name ours from the global namespace.
/// See <https://github.com/google/autocxx/issues/873>.
#[test]
fn test_pass_by_value_helper_name_shadowed_in_namespace() {
    let hdr = indoc! {"
    #include <cstdint>
    #include <string>
    inline int32_t& hijacks() { static int32_t h = 0; return h; }
    namespace shady {
        struct A {
            A() {}
            A(const A&) {}
            A(A&&) {}
            std::string so_we_are_non_trivial;
        };
        // Argument-dependent lookup offers this to any unqualified call whose
        // argument is a `shady::A`, and being an exact match it wins.
        inline A autocxx_move_or_copy(A&) { hijacks()++; return A(); }
        inline void take_a(A) {}
    }
    inline int32_t hijack_count() { return hijacks(); }
    "};
    let rs = quote! {
        let obj = ffi::shady::A::new().within_unique_ptr();
        ffi::shady::take_a(obj);
        assert_eq!(ffi::hijack_count(), 0);
    };
    run_test(
        "",
        hdr,
        rs,
        &["shady::A", "shady::take_a", "hijack_count"],
        &[],
    );
}

/// A type with neither a copy nor a move constructor can't be passed by value
/// at all. The helper which hands value parameters over must leave that
/// refusal where it was - in the C++ compiler - rather than swallowing it or
/// turning it into an error inside the helper's own template.
///
/// The message has to be the compiler's own, about the user's own type, and
/// not something the helper template says about itself. Every compiler words
/// this differently - gcc "use of deleted function", clang "call to deleted
/// constructor", cl.exe "attempting to reference a deleted function" - so what
/// is pinned here is the part they agree on: the type's name, and that
/// something about it was deleted.
/// See <https://github.com/google/autocxx/issues/873>.
#[test]
fn test_pass_by_value_no_copy_or_move() {
    let hdr = indoc! {"
    #include <string>
    struct Neither {
        Neither() {}
        Neither(const Neither&) = delete;
        Neither(Neither&&) = delete;
        std::string so_we_are_non_trivial;
    };
    inline void take_it(Neither) {}
    "};
    let rs = quote! {
        let obj = ffi::Neither::new().within_unique_ptr();
        ffi::take_it(obj);
    };
    run_test_expect_fail_with_errors(
        "",
        hdr,
        rs,
        &["Neither", "take_it"],
        &[],
        &["CppBuild", "Neither", "delete"],
    );
}

fn destruction_test(ident: proc_macro2::Ident, extra_bit: Option<TokenStream>) {
    let hdr = indoc! {"
    #include <stdint.h>
    #include <string>
    extern bool gConstructed;
    struct A {
        A() { gConstructed = true; }
        virtual ~A() { gConstructed = false; }
        void set(uint32_t val) { a = val; }
        uint32_t get() const { return a; }
        uint32_t a;
        std::string so_we_are_non_trivial;
    };
    inline bool is_constructed() { return gConstructed; }
    struct B: public A {
        uint32_t b;
    };
    "};
    let cpp = indoc! {"
        bool gConstructed = false;
    "};
    let rs = quote! {
        assert!(!ffi::is_constructed());
        {
            moveit! {
                let mut _stack_obj = ffi::#ident::new();
            }
            assert!(ffi::is_constructed());
            #extra_bit
        }
        assert!(!ffi::is_constructed());
    };
    run_test(cpp, hdr, rs, &[&ident.to_string(), "is_constructed"], &[]);
}

#[test]
fn test_destructor_moveit() {
    destruction_test(
        parse_quote! { A },
        Some(quote! {
            _stack_obj.as_mut().set(42);
            assert_eq!(_stack_obj.get(), 42);
        }),
    );
}

#[test]
fn test_destructor_derived_moveit() {
    destruction_test(parse_quote! { B }, None);
}

#[test]
fn test_copy_and_move_constructor_moveit() {
    let hdr = indoc! {"
    #include <stdint.h>
    #include <string>
    struct A {
        A() {}
        A(const A& other) : a(other.a+1) {}
        A(A&& other) : a(other.a+2) { other.a = 666; }
        void set(uint32_t val) { a = val; }
        uint32_t get() const { return a; }
        uint32_t a;
        std::string so_we_are_non_trivial;
    };
    "};
    let rs = quote! {
        moveit! {
            let mut stack_obj = ffi::A::new();
        }
        stack_obj.as_mut().set(42);
        moveit! {
            let stack_obj2 = autocxx::moveit::new::copy(stack_obj.as_ref());
        }
        assert_eq!(stack_obj2.get(), 43);
        assert_eq!(stack_obj.get(), 42);
        moveit! {
            let stack_obj3 = autocxx::moveit::new::mov(stack_obj);
        }
        assert_eq!(stack_obj3.get(), 44);
        // Following line prevented by moveit, even though it would
        // be possible in C++.
        // assert_eq!(stack_obj.get(), 666);
    };
    run_test("", hdr, rs, &["A"], &[]);
}

#[test]
fn test_uniqueptr_moveit() {
    let hdr = indoc! {"
    #include <stdint.h>
    #include <string>
    struct A {
        A() {}
        void set(uint32_t val) { a = val; }
        uint32_t get() const { return a; }
        uint32_t a;
        std::string so_we_are_non_trivial;
    };
    "};
    let rs = quote! {
        use autocxx::moveit::Emplace;
        let mut up_obj = cxx::UniquePtr::emplace(ffi::A::new());
        up_obj.as_mut().unwrap().set(42);
        assert_eq!(up_obj.get(), 42);
    };
    run_test("", hdr, rs, &["A"], &[]);
}

#[test]
fn test_various_emplacement() {
    let hdr = indoc! {"
    #include <stdint.h>
    #include <string>
    struct A {
        A() {}
        void set(uint32_t val) { a = val; }
        uint32_t get() const { return a; }
        uint32_t a;
        std::string so_we_are_non_trivial;
    };
    "};
    let rs = quote! {
        use autocxx::moveit::Emplace;
        let mut up_obj = cxx::UniquePtr::emplace(ffi::A::new());
        up_obj.pin_mut().set(666);
        // Can't current move out of a UniquePtr
        let mut box_obj = Box::emplace(ffi::A::new());
        box_obj.as_mut().set(667);
        let box_obj2 = Box::emplace(autocxx::moveit::new::mov(box_obj));
        moveit! { let back_on_stack = autocxx::moveit::new::mov(box_obj2); }
        assert_eq!(back_on_stack.get(), 667);
    };
    run_test("", hdr, rs, &["A"], &[]);
}

#[test]
fn test_emplace_uses_overridden_new_and_delete() {
    let hdr = indoc! {"
    #include <stdint.h>
    #include <string>
    struct A {
        A() {}
        void* operator new(size_t count);
        void operator delete(void* ptr) noexcept;
        void* operator new(size_t count, void* ptr);
        std::string so_we_are_non_trivial;
    };
    void reset_flags();
    bool was_new_called();
    bool was_delete_called();
    "};
    let cxx = indoc! {"
        bool new_called;
        bool delete_called;
        void reset_flags() {
            new_called = false;
            delete_called = false;
        }
        void* A::operator new(size_t count) {
            new_called = true;
            return ::operator new(count);
        }
        void* A::operator new(size_t count, void* ptr) {
            return ::operator new(count, ptr);
        }
        void A::operator delete(void* ptr) noexcept {
            delete_called = true;
            ::operator delete(ptr);
        }
        bool was_new_called() {
            return new_called;
        }
        bool was_delete_called() {
            return delete_called;
        }
    "};
    let rs = quote! {
        ffi::reset_flags();
        {
            let _ = ffi::A::new().within_unique_ptr();
            assert!(ffi::was_new_called());
        }
        assert!(ffi::was_delete_called());
        ffi::reset_flags();
        {
            use autocxx::moveit::Emplace;
            let _ = cxx::UniquePtr::emplace(ffi::A::new());
        }
        assert!(ffi::was_delete_called());
    };
    run_test(
        cxx,
        hdr,
        rs,
        &["A", "reset_flags", "was_new_called", "was_delete_called"],
        &[],
    );
}

/// A type wanting more alignment than `operator new` promises must be
/// allocated by the aligned `operator new` C++17 added for it; the plain one
/// may hand back storage the object is not allowed to live in. Freeing has to
/// match, on both routes out: `delete` for an object which got constructed,
/// and the other half of the pair for storage whose constructor threw.
///
/// What makes this deterministic is the counts, not the address: the plain
/// global `operator new` and `operator delete` are replaced here so that
/// using either is visible, since a platform allocator may over-align by luck
/// and make an address check pass for the wrong reason. The address is
/// asserted too, as the thing the counts are a proxy for.
#[test]
fn test_emplace_of_over_aligned_type_uses_aligned_new() {
    let hdr = indoc! {"
        #include <cstddef>
        #include <cstdint>
        #include <new>
        #include <stdexcept>
        struct alignas(32) AlignedA {
            AlignedA(uint32_t x) {
                if (x == 0) throw std::runtime_error(\"aligned refuses\");
                a = x;
            }
            uint32_t a = 0;
            // Padded to a size nothing else in the process is likely to ask
            // the global operator new for, so that counting by size really
            // does count only this object.
            char pad[220] = {};
            uintptr_t address() const { return reinterpret_cast<uintptr_t>(this); }
        };
        uint32_t plain_news();
        uint32_t plain_deletes();
    "};
    let cxx = indoc! {"
        #include <cstdlib>
        // Counted by size, and only for this object's own: a standard library
        // allocates through the global operator new for reasons of its own -
        // throwing an exception carries a message - and those must not be
        // mistaken for the allocation under test.
        static uint32_t plain_new_count = 0;
        static uint32_t plain_delete_count = 0;
        static void* watched = nullptr;
        uint32_t plain_news() { return plain_new_count; }
        uint32_t plain_deletes() { return plain_delete_count; }
        void* operator new(std::size_t size) {
            void* p = std::malloc(size == 0 ? 1 : size);
            if (p == nullptr) throw std::bad_alloc();
            if (size == sizeof(AlignedA)) {
                plain_new_count++;
                watched = p;
            }
            return p;
        }
        void operator delete(void* p) noexcept {
            if (p != nullptr && p == watched) {
                plain_delete_count++;
                watched = nullptr;
            }
            std::free(p);
        }
        void operator delete(void* p, std::size_t) noexcept { operator delete(p); }
    "};
    let rs = quote! {
        {
            let a = ffi::AlignedA::new(4).try_within_unique_ptr().unwrap();
            assert_eq!(a.address() % 32, 0);
        }
        // Neither end of the pair went to the plain global.
        assert_eq!(ffi::plain_news(), 0);
        assert_eq!(ffi::plain_deletes(), 0);
        // And the route out for storage which was never constructed into.
        // The counts say nothing about this one - the exception which gets it
        // there allocates on some standard libraries - but the free still has
        // to be the one which matches, and under the sanitizer a mismatch is
        // not silent.
        assert!(ffi::AlignedA::new(0).try_within_unique_ptr().is_err());
        assert_eq!(ffi::plain_news(), 0);
    };
    run_test_ex(
        cxx,
        hdr,
        rs,
        quote! {
            generate!("AlignedA")
            generate!("plain_news")
            generate!("plain_deletes")
            throws!("AlignedA::AlignedA")
        },
        make_cpp17_adder(),
        None,
        None,
    );
}

/// A class with an allocator of its own is asked first, and both ends of the
/// pair reach it: the object is built with `AlignedB::operator new`, and
/// storage whose constructor threw - never constructed, so never freed by
/// `delete` - goes back through `AlignedB::operator delete`.
#[test]
fn test_emplace_of_over_aligned_type_uses_the_classes_own_allocator() {
    let hdr = indoc! {"
        #include <cstddef>
        #include <cstdint>
        #include <new>
        #include <stdexcept>
        struct alignas(32) AlignedB {
            AlignedB(uint32_t x) {
                if (x == 0) throw std::runtime_error(\"aligned refuses\");
                a = x;
            }
            static void* operator new(std::size_t count);
            static void operator delete(void* ptr) noexcept;
            uint32_t a = 0;
            // Filled out to the alignment rather than left to the compiler,
            // which would pad it there and say so - and MSVC's C4324 is an
            // error under the warning settings these tests build with.
            char pad[28] = {};
            uintptr_t address() const { return reinterpret_cast<uintptr_t>(this); }
        };
        uint32_t class_news();
        uint32_t class_deletes();
    "};
    let cxx = indoc! {"
        static uint32_t class_new_count = 0;
        static uint32_t class_delete_count = 0;
        uint32_t class_news() { return class_new_count; }
        uint32_t class_deletes() { return class_delete_count; }
        void* AlignedB::operator new(std::size_t count) {
            class_new_count++;
            return ::operator new(count, std::align_val_t(alignof(AlignedB)));
        }
        void AlignedB::operator delete(void* ptr) noexcept {
            class_delete_count++;
            ::operator delete(ptr, std::align_val_t(alignof(AlignedB)));
        }
    "};
    let rs = quote! {
        {
            let b = ffi::AlignedB::new(5).try_within_unique_ptr().unwrap();
            assert_eq!(ffi::class_news(), 1);
            assert_eq!(b.address() % 32, 0);
        }
        assert_eq!(ffi::class_deletes(), 1);
        // A constructor which throws leaves storage nobody constructed into,
        // which comes back through the other half of the pair.
        assert!(ffi::AlignedB::new(0).try_within_unique_ptr().is_err());
        assert_eq!(ffi::class_news(), 2);
        assert_eq!(ffi::class_deletes(), 2);
    };
    run_test_ex(
        cxx,
        hdr,
        rs,
        quote! {
            generate!("AlignedB")
            generate!("class_news")
            generate!("class_deletes")
            throws!("AlignedB::AlignedB")
        },
        make_cpp17_adder(),
        None,
        None,
    );
}

/// Before C++17 the language has no aligned `operator new`, so there is
/// nothing correct to allocate an over-aligned type with. Say so at compile
/// time rather than hand back storage the object may not live in.
#[test]
fn test_emplace_of_over_aligned_type_before_cpp17_is_refused() {
    let hdr = indoc! {"
        #include <cstdint>
        struct alignas(64) AlignedC {
            AlignedC() {}
            uint32_t a = 1;
            char pad[60] = {};
        };
    "};
    let rs = quote! {
        let _ = ffi::AlignedC::new().within_unique_ptr();
    };
    run_test_expect_fail_with_error(
        "",
        hdr,
        rs,
        &["AlignedC"],
        &[],
        "more alignment than operator new gives",
    );
}

/// A class whose only allocation function takes an alignment is refused.
/// Nothing here can tell which `operator delete` would match it - a probe for
/// one is answered by a placement overload as readily as by a usual one - so
/// the allocation goes unpaired, and saying so beats guessing.
#[test]
fn test_emplace_of_over_aligned_type_with_only_an_aligned_new_is_refused() {
    let hdr = indoc! {"
        #include <cstddef>
        #include <cstdint>
        #include <new>
        struct alignas(32) AlignedE {
            AlignedE() {}
            static void* operator new(std::size_t count, std::align_val_t al);
            static void operator delete(void* ptr, std::align_val_t al) noexcept;
            uint32_t a = 7;
            char pad[28] = {};
        };
    "};
    let rs = quote! {
        let _ = ffi::AlignedE::new().within_unique_ptr();
    };
    run_test_expect_fail_with_error_modified(
        "",
        hdr,
        rs,
        directives_from_lists(&["AlignedE"], &[], None),
        make_cpp17_adder(),
        "declares an operator new taking an alignment",
    );
}

// https://github.com/google/autocxx/issues/1342
// A class-specific operator new hides the global placement form, so the
// generated C++ must say `::new (ptr) T(...)` rather than `new (ptr) T(...)`.
#[test]
fn test_ctor_with_class_specific_operator_new() {
    let hdr = indoc! {"
    #include <stddef.h>
    #include <stdint.h>
    #include <string>
    struct A {
        A() : count(0) {}
        void set(uint32_t val) { count = val; }
        uint32_t get() const { return count; }
        void* operator new(size_t count);
        void operator delete(void* ptr) noexcept;
        uint32_t count;
        std::string so_we_are_non_trivial;
    };
    "};
    let cxx = indoc! {"
        void* A::operator new(size_t count) {
            return ::operator new(count);
        }
        void A::operator delete(void* ptr) noexcept {
            ::operator delete(ptr);
        }
    "};
    let rs = quote! {
        let mut up_obj = ffi::A::new().within_unique_ptr();
        up_obj.pin_mut().set(42);
        assert_eq!(up_obj.get(), 42);
        moveit! { let mut stack_obj = ffi::A::new(); }
        stack_obj.as_mut().set(43);
        assert_eq!(stack_obj.get(), 43);
    };
    run_test(cxx, hdr, rs, &["A"], &[]);
}

