#[test]
fn test_doc_comments_survive() {
    let hdr = indoc! {"
        #include <cstdint>
        /// Struct line A
        /// Struct line B
        struct A { int b; };

        /// POD struct line A
        /// POD struct line B
        struct B {
            /// Field line A
            /// Field line B
            uint32_t b;

            /// Method line A
            /// Method line B
            void foo() {}
        };

        /// Enum line A
        /// Enum line B
        enum C {
            /// Variant line A
            /// Variant line B
            VARIANT,
        };

        /// Function line A
        /// Function line B
        inline void D() {}
    "};

    let expected_messages = [
        "Struct",
        "POD struct",
        "Field",
        "Method",
        "Enum",
        "Variant",
        "Function",
    ]
    .into_iter()
    .flat_map(|l| [format!("{l} line A"), format!("{l} line B")])
    .collect_vec();

    run_test_ex(
        "",
        hdr,
        quote! {},
        directives_from_lists(&["A", "C", "D"], &["B"], None),
        None,
        Some(make_string_finder(expected_messages)),
        None,
    );
}

