/// A type of the user's whose name is one cxx keeps for itself. Addresses the
/// bug reported upstream as google/autocxx#1371.
#[test]
fn test_class_named_string() {
    let hdr = indoc! {"
        namespace a {
            class String {};
        } // namespace a
    "};
    run_test("", hdr, quote! {}, &["a::String"], &[]);
}

/// The same property for the rest of cxx's vocabulary. `CxxString` is the
/// load-bearing case: it is one of cxx's atoms, which cxx recognises by
/// spelling wherever the identifier appears, so the `impl UniquePtr<CxxString>
/// {}` autocxx emits for the type is turned down as "unsupported Self type of
/// explicit impl". `Vec` and `Box` bite nothing today - autocxx declares this
/// type as a bridge alias (`type Vec = super::a::Vec;`), which
/// `check_reserved_name` does not visit, and cxx reads either name as its own
/// only where it carries generic arguments - and are here so that the whole
/// vocabulary stays covered if either of those changes.
///
/// A class called `u32` would be a fourth, and does not get this far:
/// `bindgen` renames it `u32_` to keep clear of the Rust primitive, so
/// `generate!("a::u32")` finds nothing under the name the header wrote. That
/// is a directive-matching bug rather than a cxx-vocabulary one, and is left
/// where it is - the property under test here is settled by the three below.
#[test]
fn test_class_named_after_other_cxx_vocabulary() {
    let hdr = indoc! {"
        #include <cstdint>
        namespace a {
            class Vec { public: uint32_t len() const { return 3; } };
            class Box { public: uint32_t len() const { return 4; } };
            class CxxString { public: uint32_t len() const { return 5; } };
        } // namespace a
    "};
    let rs = quote! {
        assert_eq!(ffi::a::Vec::new().within_unique_ptr().len(), 3);
        assert_eq!(ffi::a::Box::new().within_unique_ptr().len(), 4);
        assert_eq!(ffi::a::CxxString::new().within_unique_ptr().len(), 5);
    };
    run_test("", hdr, rs, &["a::Vec", "a::Box", "a::CxxString"], &[]);
}

/// google/autocxx#1371 in anger: two types called `String`, in a
/// `unique_ptr`, as a parameter and as a return. A name cxx has taken cannot
/// be told apart from a name another namespace has taken, so the fix is the
/// one the latter already gets - but only if the reserved names are known to
/// be taken before any type asks for one.
#[test]
fn test_class_named_string_in_anger() {
    let hdr = indoc! {"
        #include <cstdint>
        #include <memory>
        namespace a {
            struct String { uint32_t len; };
        } // namespace a
        namespace b {
            struct String { uint32_t len; };
        } // namespace b
        class Indirect {
        public:
            Indirect() { data.len = 7; }
            std::unique_ptr<a::String> datum() const {
                return std::make_unique<a::String>(data);
            }
            uint32_t take(const a::String& s) const { return s.len; }
            b::String other() const { b::String s; s.len = 9; return s; }
        private:
            a::String data;
        };
    "};
    let rs = quote! {
        let i = ffi::Indirect::new().within_unique_ptr();
        let s = ffi::a::String { len: 4 };
        assert_eq!(i.take(&s), 4);
        assert_eq!(i.datum().as_ref().unwrap().len, 7);
        assert_eq!(i.other().len, 9);
    };
    run_test("", hdr, rs, &["Indirect"], &["a::String", "b::String"]);
}

#[test]
fn test_opaque_directive() {
    let hdr = indoc! {"
        #include <memory>
        class Foo {
        public:
            int a;
        };
        Foo global_foo;
        class Bar {
        public:
            const Foo& get_foo() const { return global_foo; }
        };
    "};
    let rs = quote! {
        use autocxx::prelude::*;
        let _ = ffi::Bar::new().within_unique_ptr().get_foo();
    };
    run_test_ex(
        "",
        hdr,
        rs,
        quote! {
            generate!("Bar")
            opaque!("Foo")
        },
        None,
        None,
        None,
    );
}

#[test]
/// A class member typedef to a template instantiation, used as a
/// const-reference parameter. The typedef becomes `B_F` in the bridge with a
/// `#[namespace = "B"]` attribute, where `B` names a class rather than a
/// namespace; the generated C++ used to declare `namespace B` alongside
/// `class B` and fail to compile. See google/autocxx#1479.
fn test_nested_typedef_to_template_instantiation() {
    let hdr = indoc! {"
        template <class T>
        class X;

        class B {
        public:
            typedef X<void> F;
            void foo(const F&) {}
        };
    "};
    let rs = quote! {
        let _b = ffi::B::new().within_unique_ptr();
    };
    run_test_ex(
        "",
        hdr,
        rs,
        quote! {
            generate!("B")
        },
        None,
        None,
        None,
    );
}

#[test]
/// Asking bindgen to derive `Default` must never turn into a zero-filled
/// `Default` for a type whose all-bits-zero form isn't a valid value.
///
/// When a type can't derive `Default`, bindgen writes an `impl Default`
/// by hand which zeroes the bytes. For a struct holding a Rust `enum` whose
/// discriminants don't include 0 - the shape `enum_style!(RustifiedEnum)`
/// exists to produce - that hands out an enum value which is not any of its
/// variants, which is instant undefined behaviour. So no `Default` at all for
/// such a struct; `test_take_bitfield` pins the other side, that a struct
/// whose fields are all default-able still gets one.
fn test_no_zero_filled_default_for_enum_field() {
    let hdr = indoc! {"
        #include <cstdint>
        enum Fruit : int {
            APPLE = 1,
            PEAR = 2,
        };
        struct Basket {
            Fruit fruit;
            uint32_t count;
        };
        inline uint32_t count_of(Basket b) { return b.count; }
    "};
    let rs = quote! {
        static_assertions::assert_not_impl_any!(ffi::Basket: Default);
        // ...and the type is otherwise perfectly usable.
        let basket = ffi::Basket { fruit: ffi::Fruit::APPLE, count: 3 };
        assert_eq!(ffi::count_of(basket), 3);
    };
    run_test_ex(
        "",
        hdr,
        rs,
        quote! {
            enum_style!(RustifiedEnum, "Fruit")
            generate_pod!("Fruit")
            generate_pod!("Basket")
            generate!("count_of")
        },
        None,
        None,
        None,
    );
}

#[test]
/// Turning on bindgen's `derive_default` must not put `Default` into an
/// enum's derive list, which rustc rejects outright: E0665, because bindgen
/// marks no variant `#[default]`.
///
/// It happens because bindgen's `lookup_can_derive_default` treats an item its
/// derive analysis never visited as derivable, and an enum nested inside a
/// class autocxx makes opaque - as it does the standard library's internals -
/// is exactly such an item. This fixture stands in for the libstdc++ shape
/// that broke CI (an anonymous enum inside `std::_Rb_tree`) without depending
/// on any particular standard library being installed.
fn test_no_default_derive_on_enum_in_opaqued_class() {
    let hdr = indoc! {"
        #include <cstdint>
        namespace __gnu_cxx {
        class Detail {
        public:
            enum { AS_LVALUE = 0 };
            uint32_t v;
        };
        }
        struct Wrapper {
            __gnu_cxx::Detail detail;
            uint32_t n;
        };
        inline uint32_t read_wrapper(const Wrapper& w) { return w.n; }
    "};
    // Nothing to call - the generated bindings simply have to compile.
    run_test("", hdr, quote! {}, &["Wrapper", "read_wrapper"], &[]);
}

/// A struct mixing bitfields with an ordinary field, for the tests below.
fn bitfield_header() -> &'static str {
    indoc! {"
        #include <cstdint>
        struct Bitfieldy {
            uint8_t unsigned3 : 3;
            int8_t signed3 : 3;
            bool bool1 : 1;

            uint32_t separator;

            uint32_t unsigned12 : 12;
            int32_t signed4 : 4;
        };
    "}
}

#[test]
/// A bitfield is laid out by C++ inside an allocation unit which bindgen
/// represents as `__BindgenBitfieldUnit<[u8; N]>`. That's a plain byte array
/// with accessors, so a struct containing one is as movable as any other POD
/// struct; autocxx used to refuse to make such a struct POD at all.
fn test_take_bitfield() {
    let cxx = indoc! {"
        bool take_bitfield(Bitfieldy x) {
            return (
                x.unsigned3 == 2 &&
                x.signed3 == -3 &&
                x.bool1 == false &&
                x.separator == 424242 &&
                x.unsigned12 == 3000 &&
                x.signed4 == -1
            );
        }
    "};
    let hdr = format!("{}bool take_bitfield(Bitfieldy);\n", bitfield_header());
    let rs = quote! {
        // Every field of this struct is default-able, so bindgen derives
        // `Default` for it - see `test_no_zero_filled_default_for_enum_field`
        // for the types that must *not* get one.
        static_assertions::assert_impl_all!(ffi::Bitfieldy: Default);

        // `Default` gives us the bitfield allocation units and the padding
        // bindgen inserted, none of which can be written by hand. The
        // functional-record-update form (`..Default::default()`) would be
        // tidier, but autocxx gives every type with a destructor a `Drop`
        // impl, and Rust won't move fields out of one of those.
        let mut bitfield = ffi::Bitfieldy::default();
        bitfield._bitfield_1 = ffi::Bitfieldy::new_bitfield_1(2, -3, false);
        bitfield.separator = 424242;
        bitfield.set_unsigned12(3000);
        bitfield.set_signed4(-1);

        assert_eq!(ffi::take_bitfield(bitfield), true);
    };
    run_test(cxx, &hdr, rs, &["take_bitfield"], &["Bitfieldy"]);
}

#[test]
/// The other direction: C++ fills in the bitfields and Rust reads them back.
/// The signed fields of the same struct are
/// [`test_give_bitfield_signed_fields`]'s.
fn test_give_bitfield() {
    let cxx = indoc! {"
        Bitfieldy give_bitfield() {
            Bitfieldy result{};
            result.unsigned3 = 2;
            result.signed3 = -3;
            result.bool1 = false;
            result.separator = 424242;
            result.unsigned12 = 3000;
            result.signed4 = -1;
            return result;
        }
    "};
    let hdr = format!("{}Bitfieldy give_bitfield();\n", bitfield_header());
    let rs = quote! {
        let bitfield = ffi::give_bitfield();

        assert_eq!(bitfield.unsigned3(), 2);
        assert_eq!(bitfield.bool1(), false);
        assert_eq!(bitfield.separator, 424242);
        assert_eq!(bitfield.unsigned12(), 3000);
    };
    run_test(cxx, &hdr, rs, &["give_bitfield"], &["Bitfieldy"]);
}

#[test]
/// The signed half of [`test_give_bitfield`]. `__BindgenBitfieldUnit::get`
/// hands back the raw bits in a `u64`, and bindgen's getter used to cast them
/// straight to the field's signed type, so `signed3` holding -3 read back as 5
/// ([rust-bindgen#1160](https://github.com/rust-lang/rust-bindgen/issues/1160),
/// open since 2018). The vendored bindgen's signed-bitfield patch extends
/// before the cast; this is what pins it.
fn test_give_bitfield_signed_fields() {
    let cxx = indoc! {"
        Bitfieldy give_bitfield() {
            Bitfieldy result{};
            result.signed3 = -3;
            result.signed4 = -1;
            return result;
        }
    "};
    let hdr = format!("{}Bitfieldy give_bitfield();\n", bitfield_header());
    let rs = quote! {
        let bitfield = ffi::give_bitfield();
        assert_eq!(bitfield.signed3(), -3);
        assert_eq!(bitfield.signed4(), -1);
    };
    run_test(cxx, &hdr, rs, &["give_bitfield"], &["Bitfieldy"]);
}

#[test]
/// The shapes the sign extension has to cope with: the narrowest signed field
/// there is, a field as wide as its own declared type (which has no bits above
/// its sign bit and must come back untouched), a field of a 1-, 2-, 4- and
/// 8-byte declared type apiece, a signed field reached through a `typedef`, a
/// plain `int` rather than a fixed-width type, positive values in signed fields
/// as well as negative ones, and unsigned neighbours which must still arrive
/// zero-extended. The 16-byte case bindgen can reach is `__int128`, which MSVC
/// does not have, so it is not here.
///
/// Each struct holds bitfields of one declared type size, and no more of them
/// than fit in one allocation unit of that size. A run which crosses either
/// boundary is laid out differently on the two Windows targets - that is
/// `test_bitfield_mixing_declared_type_sizes`'s subject, and reproducing it
/// here would only make this test fail for the other reason.
fn test_bitfield_signed_getters_sign_extend() {
    let hdr = indoc! {"
        #include <cstdint>
        typedef int32_t Count;
        struct OneByte {
            int8_t narrowest : 1;
            int8_t negative : 3;
            uint8_t unsigned_three : 3;
        };
        struct TwoBytes {
            int16_t negative : 9;
            int16_t positive : 5;
            uint16_t unsigned_two : 2;
        };
        struct FourBytes {
            Count via_typedef : 6;
            int positive : 5;
            uint32_t unsigned_five : 5;
        };
        struct FullWidth {
            int32_t whole : 32;
        };
        struct EightBytes {
            int64_t negative : 40;
        };
        OneByte make_one_byte();
        TwoBytes make_two_bytes();
        FourBytes make_four_bytes();
        FullWidth make_full_width();
        EightBytes make_eight_bytes();
        uint32_t check_one_byte(OneByte);
        uint32_t check_two_bytes(TwoBytes);
        uint32_t check_four_bytes(FourBytes);
        uint32_t check_full_width(FullWidth);
        uint32_t check_eight_bytes(EightBytes);
    "};
    // Each checker returns a bit per field it disagrees with, so that a failure
    // names the field rather than the struct.
    let cxx = indoc! {"
        OneByte make_one_byte() {
            OneByte result{};
            result.narrowest = -1;
            result.negative = -3;
            result.unsigned_three = 5;
            return result;
        }
        uint32_t check_one_byte(OneByte x) {
            uint32_t wrong = 0;
            if (x.narrowest != 0) wrong |= 1u << 0;
            if (x.negative != 3) wrong |= 1u << 1;
            if (x.unsigned_three != 2) wrong |= 1u << 2;
            return wrong;
        }
        TwoBytes make_two_bytes() {
            TwoBytes result{};
            result.negative = -256;
            result.positive = 5;
            result.unsigned_two = 3;
            return result;
        }
        uint32_t check_two_bytes(TwoBytes x) {
            uint32_t wrong = 0;
            if (x.negative != 255) wrong |= 1u << 0;
            if (x.positive != -6) wrong |= 1u << 1;
            if (x.unsigned_two != 1) wrong |= 1u << 2;
            return wrong;
        }
        FourBytes make_four_bytes() {
            FourBytes result{};
            result.via_typedef = -32;
            result.positive = 11;
            result.unsigned_five = 31;
            return result;
        }
        uint32_t check_four_bytes(FourBytes x) {
            uint32_t wrong = 0;
            if (x.via_typedef != 31) wrong |= 1u << 0;
            if (x.positive != -16) wrong |= 1u << 1;
            if (x.unsigned_five != 1) wrong |= 1u << 2;
            return wrong;
        }
        FullWidth make_full_width() {
            FullWidth result{};
            result.whole = -2000000000;
            return result;
        }
        uint32_t check_full_width(FullWidth x) {
            return x.whole == 2000000001 ? 0 : 1;
        }
        EightBytes make_eight_bytes() {
            EightBytes result{};
            result.negative = -549755813888;
            return result;
        }
        uint32_t check_eight_bytes(EightBytes x) {
            return x.negative == 549755813887 ? 0 : 1;
        }
    "};
    let rs = quote! {
        let mut one_byte = ffi::make_one_byte();
        assert_eq!(one_byte.narrowest(), -1);
        assert_eq!(one_byte.negative(), -3);
        assert_eq!(one_byte.unsigned_three(), 5);
        one_byte.set_narrowest(0);
        one_byte.set_negative(3);
        one_byte.set_unsigned_three(2);
        assert_eq!(ffi::check_one_byte(one_byte), 0);

        let mut two_bytes = ffi::make_two_bytes();
        assert_eq!(two_bytes.negative(), -256);
        assert_eq!(two_bytes.positive(), 5);
        assert_eq!(two_bytes.unsigned_two(), 3);
        two_bytes.set_negative(255);
        two_bytes.set_positive(-6);
        two_bytes.set_unsigned_two(1);
        assert_eq!(ffi::check_two_bytes(two_bytes), 0);

        let mut four_bytes = ffi::make_four_bytes();
        assert_eq!(four_bytes.via_typedef(), -32);
        assert_eq!(four_bytes.positive(), 11);
        assert_eq!(four_bytes.unsigned_five(), 31);
        four_bytes.set_via_typedef(31);
        four_bytes.set_positive(-16);
        four_bytes.set_unsigned_five(1);
        assert_eq!(ffi::check_four_bytes(four_bytes), 0);

        let mut full_width = ffi::make_full_width();
        assert_eq!(full_width.whole(), -2000000000);
        full_width.set_whole(2000000001);
        assert_eq!(ffi::check_full_width(full_width), 0);

        let mut eight_bytes = ffi::make_eight_bytes();
        assert_eq!(eight_bytes.negative(), -549755813888);
        eight_bytes.set_negative(549755813887);
        assert_eq!(ffi::check_eight_bytes(eight_bytes), 0);
    };
    run_test(
        cxx,
        hdr,
        rs,
        &[
            "make_one_byte",
            "make_two_bytes",
            "make_four_bytes",
            "make_full_width",
            "make_eight_bytes",
            "check_one_byte",
            "check_two_bytes",
            "check_four_bytes",
            "check_full_width",
            "check_eight_bytes",
        ],
        &[
            "OneByte",
            "TwoBytes",
            "FourBytes",
            "FullWidth",
            "EightBytes",
        ],
    );
}

#[test]
/// A struct with bitfields which nobody asked to be POD stays non-POD, and
/// keeps working as an opaque type.
fn test_bitfield_non_pod() {
    let cxx = indoc! {"
        uint32_t read_separator(const Bitfieldy& x) { return x.separator; }
        Bitfieldy make_bitfield() {
            Bitfieldy result{};
            result.separator = 42;
            return result;
        }
    "};
    let hdr = format!(
        "{}uint32_t read_separator(const Bitfieldy&);\nBitfieldy make_bitfield();\n",
        bitfield_header()
    );
    let rs = quote! {
        let bitfield = ffi::make_bitfield().within_unique_ptr();
        assert_eq!(ffi::read_separator(&bitfield), 42);
    };
    run_test(
        cxx,
        &hdr,
        rs,
        &["Bitfieldy", "read_separator", "make_bitfield"],
        &[],
    );
}

#[test]
/// bindgen reaches a bitfield's bits through `mem::transmute`, converting
/// between the field's declared Rust type and the same-sized unsigned integer
/// its allocation unit deals in. Where that conversion has a safe equivalent -
/// `bool` to `u8`, `i32` to `u32` - rustc's `unnecessary_transmutes` lint says
/// so, and it warns by default, so any caller building with `-D warnings`
/// cannot compile a struct with bitfields at all. That is how it reached us:
/// the `examples/llvm` build broke on `llvm::ErrorOr`.
///
/// The field types here are chosen to cover each shape autocxx's sanitizer
/// distinguishes: a plain C type (which arrives as `::std::os::raw::c_int`,
/// not as `i32`), signed and unsigned, fixed-width, `bool`, `size_t` (which
/// arrives as `usize`, a type of its own however wide it turns out to be), a
/// `typedef` which has to be followed to the type rustc will lint, and an
/// `enum`, whose transmute has no cast equivalent and must survive untouched.
/// Every field is read back and written through, so that the conversion in
/// each direction is checked against what C++ makes of the same bits, and not
/// only against the lint.
///
/// They are spread over three structs, grouped so that every bitfield within
/// one has a declared type of the same size. That grouping is load-bearing on
/// both Windows targets and free everywhere else - see
/// `test_bitfield_mixing_declared_type_sizes` for the layout divergence it
/// avoids - and it costs this test nothing, because what is under test is the
/// code an accessor is made of, which is the same wherever the bits sit.
///
/// `Packed` is here because a bitfield of a `union` reaches its allocation
/// unit through `__BindgenUnionField::as_ref`, an `unsafe fn`, so its accessors
/// are the ones which must keep the `unsafe` block the others lose. It is
/// opaque to Rust, so nothing calls those; they only have to compile.
///
/// `unused_unsafe` is denied alongside, because taking a transmute out of a
/// getter empties the `unsafe` block around it: that block has to go too, or
/// we have swapped one warning for another.
///
/// `Shade` names its underlying type because a bitfield of an enum which does
/// not is signed on one compiler and unsigned on another: MSVC gives an
/// unscoped enum the underlying type `int`, gcc and clang give this one
/// `unsigned int`, and `Shade shade : 2` is then a two-bit field which holds
/// -2 to 1 on the one and 0 to 3 on the other. `LIGHT` is 2, and fits only in
/// the second.
fn test_bitfield_accessors_do_not_transmute_unnecessarily() {
    let hdr = indoc! {"
        #include <cstdint>
        #include <cstddef>
        enum Shade : unsigned { DARK = 0, MID = 1, LIGHT = 2 };
        typedef int Handle;
        struct Words {
            unsigned plain_unsigned : 4;
            int plain_int : 4;
            uint32_t fixed_unsigned : 3;
            int32_t fixed_signed : 3;
            Shade shade : 2;
            Handle handle : 4;
        };
        struct Bytes {
            bool flag : 1;
            uint8_t byte_unsigned : 3;
            int8_t byte_signed : 3;
        };
        struct Wide {
            size_t counted : 5;
        };
        union Packed {
            int part : 3;
            bool set : 1;
            uint32_t whole;
        };
        Words make_words();
        uint32_t check_words(Words);
        Bytes make_bytes();
        uint32_t check_bytes(Bytes);
        Wide make_wide();
        uint32_t check_wide(Wide);
    "};
    // Each checker returns a bit per field it disagrees with, rather than one
    // bool for the lot, so that a failure names the field. A bitfield read
    // from the wrong place is a platform's business and not this test's, and
    // the difference is only visible if the test says which field went wrong.
    let cxx = indoc! {"
        Words make_words() {
            Words result{};
            result.plain_unsigned = 5;
            result.plain_int = -7;
            result.fixed_unsigned = 6;
            result.fixed_signed = -2;
            result.shade = MID;
            result.handle = -5;
            return result;
        }
        uint32_t check_words(Words x) {
            uint32_t wrong = 0;
            if (x.plain_unsigned != 9) wrong |= 1u << 0;
            if (x.plain_int != 6) wrong |= 1u << 1;
            if (x.fixed_unsigned != 3) wrong |= 1u << 2;
            if (x.fixed_signed != 2) wrong |= 1u << 3;
            if (x.shade != LIGHT) wrong |= 1u << 4;
            if (x.handle != 3) wrong |= 1u << 5;
            return wrong;
        }
        Bytes make_bytes() {
            Bytes result{};
            result.flag = true;
            result.byte_unsigned = 6;
            result.byte_signed = -2;
            return result;
        }
        uint32_t check_bytes(Bytes x) {
            uint32_t wrong = 0;
            if (x.flag) wrong |= 1u << 0;
            if (x.byte_unsigned != 3) wrong |= 1u << 1;
            if (x.byte_signed != 2) wrong |= 1u << 2;
            return wrong;
        }
        Wide make_wide() {
            Wide result{};
            result.counted = 17;
            return result;
        }
        uint32_t check_wide(Wide x) { return x.counted == 20 ? 0 : 1; }
    "};
    let rs = quote! {
        let mut words = ffi::make_words();
        // Every getter reads back what C++ wrote, negative values included:
        // the conversion has to keep the sign bits the sign extension put
        // there, which `test_bitfield_signed_getters_sign_extend` pins.
        assert_eq!(words.plain_unsigned(), 5, "{}", object_bytes(&words));
        assert_eq!(words.plain_int(), -7, "{}", object_bytes(&words));
        assert_eq!(words.fixed_unsigned(), 6, "{}", object_bytes(&words));
        assert_eq!(words.fixed_signed(), -2, "{}", object_bytes(&words));
        assert!(matches!(words.shade(), ffi::Shade::MID), "{}", object_bytes(&words));
        assert_eq!(words.handle(), -5, "{}", object_bytes(&words));
        // ...and every setter puts back something C++ agrees with.
        words.set_plain_unsigned(9);
        words.set_plain_int(6);
        words.set_fixed_unsigned(3);
        words.set_fixed_signed(2);
        words.set_shade(ffi::Shade::LIGHT);
        words.set_handle(3);
        let written = object_bytes(&words);
        let wrong = ffi::check_words(words);
        assert_eq!(wrong, 0, "C++ disagrees about fields {wrong:#08b}; {written}");

        let mut bytes = ffi::make_bytes();
        assert_eq!(bytes.flag(), true, "{}", object_bytes(&bytes));
        assert_eq!(bytes.byte_unsigned(), 6, "{}", object_bytes(&bytes));
        assert_eq!(bytes.byte_signed(), -2, "{}", object_bytes(&bytes));
        bytes.set_flag(false);
        bytes.set_byte_unsigned(3);
        bytes.set_byte_signed(2);
        let written = object_bytes(&bytes);
        let wrong = ffi::check_bytes(bytes);
        assert_eq!(wrong, 0, "C++ disagrees about fields {wrong:#05b}; {written}");

        let mut wide = ffi::make_wide();
        assert_eq!(wide.counted(), 17, "{}", object_bytes(&wide));
        wide.set_counted(20);
        let written = object_bytes(&wide);
        let wrong = ffi::check_wide(wide);
        assert_eq!(wrong, 0, "C++ disagrees about counted; {written}");
    };
    let extra = quote! {
        /// The bytes of a POD struct, for the assertion messages above. If one
        /// of them ever fails on one platform and passes on the rest, the
        /// question is whether C++ wrote the bits somewhere else, and these
        /// are the bytes that answer it.
        fn object_bytes<T>(value: &T) -> String {
            let bytes = unsafe {
                std::slice::from_raw_parts(
                    (value as *const T).cast::<u8>(),
                    std::mem::size_of::<T>(),
                )
            };
            format!("object representation: {bytes:02x?}")
        }
    };
    do_run_test(
        cxx,
        hdr,
        rs,
        directives_from_lists(
            &[
                "make_words",
                "check_words",
                "make_bytes",
                "check_bytes",
                "make_wide",
                "check_wide",
                "Shade",
                "Packed",
            ],
            &["Words", "Bytes", "Wide"],
            None,
        ),
        None,
        None,
        Some(extra),
        "unsafe_ffi",
        Some(quote! {
            #![deny(unnecessary_transmutes)]
            #![deny(unused_unsafe)]
        }),
    )
    .unwrap()
}

#[test]
#[cfg_attr(
    windows,
    ignore = "the offsets bindgen writes into these accessors are not \
              libclang's. libclang, asked for either Windows triple, reports \
              Microsoft layout for this struct - `plain_unsigned` and \
              `plain_int` at bits 0 and 4, then fresh allocation units at bits \
              32, 64 and 128 as the declared type size changes from `unsigned` \
              to `uint8_t` to `Shade` to `size_t` - which is exactly what \
              cl.exe and mingw g++ produce, and `clang_Cursor_getOffsetOfField` \
              hands those numbers straight to bindgen. bindgen throws them away \
              for bitfields: `bitfields_to_allocation_units` in its `ir/comp.rs` \
              groups bitfields into units by running its own packing algorithm, \
              and that algorithm is Itanium's, hardcoded - `const is_ms_struct: \
              bool = false`, under a comment wondering whether it ought to \
              check whether the target is MSVC. So every field here lands in \
              one four-byte unit at bits 0, 4, 8, 11, 14, 15, 17 and 21, the \
              layout a Linux compiler would give it, and `fixed_unsigned` \
              onwards are read from bytes Microsoft layout never writes. The \
              struct still comes out 24 bytes, because the tail is padded to \
              the size libclang reports, so nothing fails to compile and the \
              fields before the first change of type size agree. Fixing it \
              means either teaching bindgen the Microsoft rule - a new \
              allocation unit whenever the declared type's size changes - or, \
              better, making it honour the offsets libclang already gives it, \
              which would be right for every ABI rather than one more. Either \
              changes every Windows binding that mixes bitfield type sizes, and \
              wants its own change and its own testing."
)]
/// A bitfield struct which mixes declared type sizes, pinning the layout the
/// C++ compiler and libclang have to agree about. This is the shape
/// `test_bitfield_accessors_do_not_transmute_unnecessarily` deliberately
/// avoids: the conversions it exercises are the same ones, so nothing about
/// the lint fix rests on this test, and it is here to keep the platform
/// divergence visible rather than forgotten.
///
/// The fix belongs in autocxx-bindgen, not in the flags autocxx passes: no
/// clang flag changes the answer, because clang is already right. `-mms-bitfields`
/// is what makes the mingw triple use Microsoft bitfields (its C++ ABI is
/// Itanium, so bindgen's existing `ABIKind`, which keys off `msvc` in the
/// triple, is the wrong predicate to reuse). Two routes, in preference order:
/// make `bitfields_to_allocation_units` group units from the per-field offsets
/// clang already put in `RawField::offset`, and teach
/// `codegen/struct_layout.rs::saw_bitfield_unit` to pad up to a unit's offset
/// the way `saw_field` does for data members - that is ABI-agnostic and also
/// covers `#pragma pack` and `__attribute__((ms_struct))`; or set
/// `is_ms_struct` from the target and rewrite bindgen's existing (and also
/// wrong) MS branch, which flushes a unit only when a field will not fit and
/// has no notion of the declared type's size changing. Whichever is done,
/// re-enabling layout tests would not have caught this: bindgen's layout tests
/// skip `Field::Bitfields` entirely, and the tail padding hides the size.
/// Whoever does it should be able to delete the `cfg_attr` above and find this
/// passing.
fn test_bitfield_mixing_declared_type_sizes() {
    let hdr = indoc! {"
        #include <cstdint>
        #include <cstddef>
        enum Shade : unsigned { DARK = 0, MID = 1, LIGHT = 2 };
        typedef int Handle;
        struct Lots {
            unsigned plain_unsigned : 4;
            int plain_int : 4;
            uint8_t fixed_unsigned : 3;
            int8_t fixed_signed : 3;
            bool flag : 1;
            Shade shade : 2;
            Handle handle : 4;
            size_t counted : 5;
        };
        Lots make_lots();
        bool check_lots(Lots);
    "};
    let cxx = indoc! {"
        Lots make_lots() {
            Lots result{};
            result.plain_unsigned = 5;
            result.plain_int = 6;
            result.fixed_unsigned = 6;
            result.fixed_signed = 2;
            result.flag = true;
            result.shade = MID;
            result.handle = 5;
            result.counted = 17;
            return result;
        }
        bool check_lots(Lots x) {
            return x.plain_unsigned == 9 && x.plain_int == -7 &&
                x.fixed_unsigned == 3 && x.fixed_signed == -2 &&
                !x.flag && x.shade == LIGHT && x.handle == 3 &&
                x.counted == 20;
        }
    "};
    let rs = quote! {
        let mut lots = ffi::make_lots();
        assert_eq!(lots.plain_unsigned(), 5);
        assert_eq!(lots.plain_int(), 6);
        assert_eq!(lots.fixed_unsigned(), 6);
        assert_eq!(lots.fixed_signed(), 2);
        assert_eq!(lots.flag(), true);
        assert!(matches!(lots.shade(), ffi::Shade::MID));
        assert_eq!(lots.handle(), 5);
        assert_eq!(lots.counted(), 17);
        lots.set_plain_unsigned(9);
        lots.set_plain_int(-7);
        lots.set_fixed_unsigned(3);
        lots.set_fixed_signed(-2);
        lots.set_flag(false);
        lots.set_shade(ffi::Shade::LIGHT);
        lots.set_handle(3);
        lots.set_counted(20);
        assert_eq!(ffi::check_lots(lots), true);
    };
    run_test_ex(
        cxx,
        hdr,
        rs,
        directives_from_lists(&["make_lots", "check_lots", "Shade"], &["Lots"], None),
        None,
        None,
        None,
    );
}

