/// C++ diagnoses writing `= default` on a member it then deletes
/// (-Wdefaulted-function-deleted), and it is right to: the declaration says
/// nothing the class doesn't already say. That's exactly the shape
/// google/autocxx#815 is about, though, so these fixtures check what autocxx
/// generates for it and stop before the harness compiles them, rather than
/// telling the compiler to keep quiet about an accurate warning.
#[test]
fn test_defaulted_copy_constructor_which_is_deleted() {
    let hdr = indoc! {"
        #include <cstdint>
        struct NonCopyable {
            NonCopyable() = default;
            NonCopyable(const NonCopyable&) = delete;
            uint32_t a;
        };
        struct DefaultedButDeletedCopy {
            DefaultedButDeletedCopy() = default;
            DefaultedButDeletedCopy(const DefaultedButDeletedCopy&) = default;
            NonCopyable m;
        };
    "};
    run_test_ex(
        "",
        hdr,
        quote! {},
        directives_from_lists(&["NonCopyable", "DefaultedButDeletedCopy"], &[], None),
        None,
        Some(make_checks_without_building(vec![Box::new(
            CppMatcher::new(
                // The default constructor is fine and stays...
                &["::new (autocxx_gen_this) DefaultedButDeletedCopy()"],
                // ...whereas the copy constructor C++ deleted must not be called.
                &["::new (autocxx_gen_this) DefaultedButDeletedCopy(arg1)"],
            ),
        )])),
        None,
    );
}

/// The `T(T&)` form of the same thing: a non-const copy constructor written
/// `= default` on a class whose members make it deleted. Same rules, same
/// answer - we must not generate a call to it.
#[test]
fn test_defaulted_non_const_copy_constructor_which_is_deleted() {
    let hdr = indoc! {"
        #include <cstdint>
        struct NonCopyable {
            NonCopyable() = default;
            NonCopyable(const NonCopyable&) = delete;
            uint32_t a;
        };
        struct DefaultedButDeletedCopy {
            DefaultedButDeletedCopy() = default;
            DefaultedButDeletedCopy(DefaultedButDeletedCopy&) = default;
            NonCopyable m;
        };
    "};
    run_test_ex(
        "",
        hdr,
        quote! {},
        directives_from_lists(&["NonCopyable", "DefaultedButDeletedCopy"], &[], None),
        None,
        Some(make_checks_without_building(vec![Box::new(
            CppMatcher::new(
                // The default constructor is fine and stays...
                &["DefaultedButDeletedCopy_new_autocxx"],
                // ...whereas the copy constructor C++ deleted must not be
                // bound, under the name an ordinary constructor would get.
                &["DefaultedButDeletedCopy_new1"],
            ),
        )])),
        None,
    );
}

#[test]
fn test_defaulted_default_constructor_which_is_deleted() {
    let hdr = indoc! {"
        #include <cstdint>
        struct NoDefaultConstructor {
            NoDefaultConstructor(uint32_t x) : a(x) {}
            uint32_t a;
        };
        struct DefaultedButDeletedDefault {
            DefaultedButDeletedDefault() = default;
            NoDefaultConstructor m;
        };
    "};
    run_test_ex(
        "",
        hdr,
        quote! {},
        directives_from_lists(
            &["NoDefaultConstructor", "DefaultedButDeletedDefault"],
            &[],
            None,
        ),
        None,
        Some(make_checks_without_building(vec![
            Box::new(CppMatcher::new(
                &[],
                &["::new (autocxx_gen_this) DefaultedButDeletedDefault()"],
            )),
            // `new()` is a name the user would have reached for, so it leaves
            // a documented stub rather than vanishing.
            make_string_finder(vec![
                "This special member function was declared =default".to_string()
            ]),
        ])),
        None,
    );
}

#[test]
fn test_defaulted_destructor_which_is_deleted() {
    // A destructor C++ deletes takes the whole ownership surface with it, by
    // the route google/autocxx#829 established: the member's destructor is
    // inaccessible, so this class's `= default`ed one is deleted, so nothing
    // may allocate, construct or drop one of these.
    let hdr = indoc! {"
        class PrivateDtor {
        public:
            PrivateDtor() {}
        private:
            ~PrivateDtor() {}
        };
        struct DefaultedButDeletedDtor {
            ~DefaultedButDeletedDtor() = default;
            PrivateDtor m;
        };
    "};
    run_test_ex(
        "",
        hdr,
        quote! {},
        directives_from_lists(&["PrivateDtor", "DefaultedButDeletedDtor"], &[], None),
        None,
        Some(make_checks_without_building(vec![
            Box::new(CppMatcher::new(
                &[],
                &[
                    "arg0->DefaultedButDeletedDtor::~DefaultedButDeletedDtor()",
                    "new_appropriately<DefaultedButDeletedDtor>()",
                ],
            )),
            make_string_finder(vec![
                "autocxx has not generated any way for Rust to own one of these".to_string(),
            ]),
        ])),
        None,
    );
}

/// A type which turns up with no constructors is a mystery unless the
/// bindings say which member or base took them away, so say it.
/// See <https://github.com/google/autocxx/issues/1034>.
#[test]
fn test_absent_constructors_explain_themselves() {
    let hdr = indoc! {"
        #include <cstdint>
        struct NoDefault {
            NoDefault() = delete;
            NoDefault(const NoDefault&) {}
            uint32_t a;
        };
        struct HasUnconstructibleMember { NoDefault m; };
        struct HasReferenceMember { uint32_t& r; };
        struct HasConstMember { const uint32_t c; };
        class PrivateCopy {
        public:
            PrivateCopy() {}
            uint32_t a;
        private:
            PrivateCopy(const PrivateCopy&) {}
        };
        struct DerivesPrivateCopy : public PrivateCopy { uint32_t b; };
        struct DeclaresMove {
            DeclaresMove() {}
            DeclaresMove(DeclaresMove&&) {}
            uint32_t a;
        };
    "};
    run_test_ex(
        "",
        hdr,
        quote! {},
        directives_from_lists(
            &[
                "HasUnconstructibleMember",
                "HasReferenceMember",
                "HasConstMember",
                "DerivesPrivateCopy",
                "DeclaresMove",
            ],
            &[],
            None,
        ),
        None,
        Some(make_string_finder(vec![
            "C++ gives this type no default constructor, because its field `m` of type \
             `NoDefault` has no accessible default constructor."
                .to_string(),
            "C++ gives this type no default constructor, because its field `r` is a reference \
             with no default member initializer, leaving an implicitly declared constructor \
             nothing to bind it to. A constructor written out in the C++ source can bind it in \
             its member initializer list."
                .to_string(),
            "autocxx has not given this type a default constructor, because its field `c` is \
             `const`, has no default member initializer, and so an implicitly declared \
             constructor would have no way to give it its one and only value."
                .to_string(),
            "C++ gives this type no copy constructor, because its base class `PrivateCopy` has \
             no accessible copy constructor."
                .to_string(),
            "C++ gives this type no copy constructor, because it declares a move constructor, \
             which withdraws the copy constructor C++ would otherwise have declared implicitly."
                .to_string(),
        ])),
        None,
    );
}

/// The case google/autocxx#1034 was reported for: autocxx doesn't understand
/// one of the class's members, so it declines to work out any of the class's
/// constructors, and until now said nothing about it outside the logs.
#[test]
fn test_absent_constructors_name_the_members_we_dont_understand() {
    let hdr = indoc! {"
        #include <cstdint>
        template <typename T> struct Tmpl { T t; };
        struct HasTemplatedMember { Tmpl<uint32_t> t; };
    "};
    run_test_ex(
        "",
        hdr,
        quote! {},
        directives_from_lists(&["HasTemplatedMember"], &[], None),
        None,
        Some(make_string_finder(vec![
            "autocxx has not given this type a default constructor: it does not understand"
                .to_string(),
            "which this class has as a base or a field, and so cannot tell which special member \
             functions C++ declares for it."
                .to_string(),
        ])),
        None,
    );
}

/// A type whose destructor Rust can't reach has no constructors either, but
/// the note google/autocxx#829 added already says why - so don't say it again
/// once per constructor.
#[test]
fn test_inaccessible_destructor_explains_itself_only_once() {
    let hdr = indoc! {"
        class PrivateDtor {
        public:
            PrivateDtor() {}
        private:
            ~PrivateDtor() {}
        };
    "};
    run_test_ex(
        "",
        hdr,
        quote! {},
        directives_from_lists(&["PrivateDtor"], &[], None),
        None,
        Some(make_checks_without_building(vec![
            make_string_finder(vec![
                "autocxx has not generated any way for Rust to own one of these".to_string(),
            ]),
            make_string_absence_finder(vec!["C++ gives this type no".to_string()]),
        ])),
        None,
    );
}

#[test]
fn test_defaulted_special_members_which_survive() {
    // The other half of the rule: `= default` on members C++ keeps must go on
    // meaning exactly what it did before.
    let hdr = indoc! {"
        #include <cstdint>
        struct AllDefaulted {
            AllDefaulted() = default;
            AllDefaulted(const AllDefaulted&) = default;
            AllDefaulted(AllDefaulted&&) = default;
            ~AllDefaulted() = default;
            uint32_t a;
        };
    "};
    let rs = quote! {
        static_assertions::assert_impl_all!(ffi::AllDefaulted: moveit::CopyNew);
        static_assertions::assert_impl_all!(ffi::AllDefaulted: moveit::MoveNew);
        let obj = ffi::AllDefaulted::new().within_unique_ptr();
        let copy = autocxx::moveit::new::copy(obj.as_ref().unwrap()).within_unique_ptr();
        assert_eq!(copy.a, obj.a);
    };
    run_test("", hdr, rs, &[], &["AllDefaulted"]);
}

#[test]
fn test_defaulted_copy_constructor_survives_user_move_constructor() {
    // A user-declared move constructor deletes the implicitly declared copy
    // constructor, but not one the user asked for with `= default`.
    let hdr = indoc! {"
        #include <cstdint>
        struct MoveAndDefaultedCopy {
            MoveAndDefaultedCopy() : a(1) {}
            MoveAndDefaultedCopy(MoveAndDefaultedCopy&& other) : a(other.a) {}
            MoveAndDefaultedCopy(const MoveAndDefaultedCopy&) = default;
            uint32_t get() const { return a; }
            uint32_t a;
        };
    "};
    let rs = quote! {
        static_assertions::assert_impl_all!(ffi::MoveAndDefaultedCopy: moveit::CopyNew);
        let obj = ffi::MoveAndDefaultedCopy::new().within_unique_ptr();
        let copy = autocxx::moveit::new::copy(obj.as_ref().unwrap()).within_unique_ptr();
        assert_eq!(copy.get(), 1);
    };
    run_test("", hdr, rs, &["MoveAndDefaultedCopy"], &[]);
}

#[test]
fn test_defaulted_special_members_keep_their_visibility() {
    // `= default` says which members exist; it doesn't say who may call them.
    let hdr = indoc! {"
        #include <cstdint>
        class PrivateDefaultedCopy {
        public:
            PrivateDefaultedCopy() = default;
            uint32_t get() const { return 1; }
        private:
            PrivateDefaultedCopy(const PrivateDefaultedCopy&) = default;
        };
    "};
    let rs = quote! {
        static_assertions::assert_not_impl_any!(ffi::PrivateDefaultedCopy: moveit::CopyNew);
        let obj = ffi::PrivateDefaultedCopy::new().within_unique_ptr();
        assert_eq!(obj.get(), 1);
    };
    run_test("", hdr, rs, &["PrivateDefaultedCopy"], &[]);
}

#[test]
fn test_impl_new_returns_are_must_use() {
    // Anything which hands back an `impl New` - a constructor, or a function
    // returning a non-POD type by value - constructs nothing until the caller
    // emplaces it. moveit's `New` is itself `#[must_use]`, so the mistake is
    // already caught, but its message says only that the value does nothing;
    // ours has to say what to do about it. See google/autocxx#1090.
    struct MustUseOnNewReturns;
    impl CodeCheckerFns for MustUseOnNewReturns {
        fn check_rust(&self, rs: syn::File) -> Result<(), TestError> {
            let mut checked = 0usize;
            for (name, sig, attrs) in collect_fns(&rs) {
                let returns_new = quote!(#sig).to_string().contains(":: New <");
                let must_use = attrs.iter().any(|attr| attr.path.is_ident("must_use"));
                if returns_new {
                    checked += 1;
                }
                if returns_new != must_use {
                    return Err(TestError::RsCodeExaminationFail(format!(
                        "fn {name} returns an impl New: {returns_new}, but is #[must_use]: \
                         {must_use}"
                    )));
                }
            }
            // Guard against the checks above passing vacuously.
            if checked < 2 {
                return Err(TestError::RsCodeExaminationFail(format!(
                    "expected both the constructor and the by-value return to hand back an \
                     impl New, but found {checked} of them"
                )));
            }
            Ok(())
        }
    }
    /// Every free function and inherent method in the generated code, other
    /// than those in trait impls - rustc rejects `#[must_use]` on those.
    fn collect_fns(rs: &syn::File) -> Vec<(String, syn::Signature, Vec<syn::Attribute>)> {
        fn walk(items: &[syn::Item], out: &mut Vec<(String, syn::Signature, Vec<syn::Attribute>)>) {
            for item in items {
                match item {
                    syn::Item::Mod(m) => {
                        if let Some((_, items)) = &m.content {
                            walk(items, out);
                        }
                    }
                    syn::Item::Fn(f) => {
                        out.push((f.sig.ident.to_string(), f.sig.clone(), f.attrs.clone()))
                    }
                    syn::Item::Impl(i) if i.trait_.is_none() => {
                        for item in &i.items {
                            if let syn::ImplItem::Method(f) = item {
                                out.push((f.sig.ident.to_string(), f.sig.clone(), f.attrs.clone()));
                            }
                        }
                    }
                    _ => {}
                }
            }
        }
        let mut out = Vec::new();
        walk(&rs.items, &mut out);
        out
    }
    let hdr = indoc! {"
        #include <cstdint>
        struct Bob {
            Bob() : a(3) {}
            uint32_t plain() const { return a; }
            uint32_t a;
        };
        inline Bob make_bob() { return Bob(); }
    "};
    // A `throws!` function returning a non-POD type by value hands back an
    // `impl TryNew` rather than an `impl New`, and gets a `#[must_use]` naming
    // the fallible finishers. That shape is covered by
    // `test_designated_ctor_generates_a_try_new` and the unit tests beside
    // `must_use_attr_if_impl_new` in `fun_codegen.rs`; this test is about the
    // infallible one.
    run_test_ex(
        "",
        hdr,
        quote! {
            assert_eq!(ffi::make_bob().within_unique_ptr().plain(), 3);
        },
        directives_from_lists(&["Bob", "make_bob"], &[], None),
        None,
        Some(Box::new(MustUseOnNewReturns)),
        None,
    );
}

#[test]
fn test_dropping_an_impl_new_is_diagnosed_with_instructions() {
    // The user-visible half of google/autocxx#1090: dropping the `impl New`
    // rather than emplacing it silently constructs nothing, so the diagnostic
    // has to name the ways of emplacing it.
    let hdr = indoc! {"
        #include <cstdint>
        struct Bob {
            Bob() : a(3) {}
            uint32_t a;
        };
    "};
    let rs = quote! {
        #[deny(unused_must_use)]
        fn drops_it() {
            ffi::Bob::new();
        }
        drops_it();
    };
    run_test_expect_fail_with_error("", hdr, rs, &["Bob"], &[], ".within_unique_ptr()");
}

#[test]
fn test_std_function_parameter_says_what_went_wrong() {
    // What autocxx used to report was whichever of bindgen's limits the type
    // happened to trip over, which told the user nothing about their own code.
    // See google/autocxx#1279.
    //
    // The two standard libraries trip over different limits, so this pins the
    // wording rather than the classification. libstdc++ and libc++ hide
    // std::function behind reserved implementation-detail names, so bindgen
    // erases it to an opaque blob (`InvalidIdentError::BindgenOpaqueType`);
    // MSVC's spells it as a partial specialization over a function type, which
    // bindgen keeps as a named class with a discarded template parameter
    // (`ConvertErrorFromCpp::UnsupportedStdFunction`). Both end at the same
    // advice, which is the part a user acts on.
    let hdr = indoc! {"
        #include <functional>
        inline void takes_callback(std::function<void(int)> f) { (void) f; }
    "};
    run_test_expect_fail_with_error(
        "",
        hdr,
        quote! {},
        &["takes_callback"],
        &[],
        "std::function is not supported by bindgen or cxx",
    );
}

#[test]
fn test_std_function_method_costs_only_that_method() {
    // The rest of a class whose method takes a std::function must survive.
    let hdr = indoc! {"
        #include <cstdint>
        #include <functional>
        class Requester {
        public:
            Requester() {}
            using RespHandler = std::function<void(int)>;
            void sendRequest(RespHandler handler) { (void) handler; }
            uint32_t answer() const { return 42; }
        };
    "};
    let rs = quote! {
        let requester = ffi::Requester::new().within_unique_ptr();
        assert_eq!(requester.answer(), 42);
    };
    // The explanation reaches the user through the doc comment of the stub
    // standing in for the method autocxx could not generate. It gets there by
    // two different routes: with libstdc++ and libc++ the typedef itself is
    // what fails, while on MSVC the typedef is left standing in for a
    // `std::function` which failed, and the reason travels across that hop -
    // see `test_class_scoped_alias_reports_the_targets_own_problem`. Either
    // way the wording is the same, which is the part a user acts on.
    run_test_ex(
        "",
        hdr,
        rs,
        directives_from_lists(&["Requester"], &[], None),
        None,
        Some(make_string_finder(vec![
            "std::function is not supported by bindgen or cxx".to_string(),
        ])),
        None,
    );
}

/// A class-scoped `using` alias of a type autocxx has a precise complaint
/// about. autocxx can't generate the method taking that alias, and what it
/// tells the user has to be the complaint about the target - not the generic
/// "you used a forward declaration inside a UniquePtr" left behind by the hop
/// through the alias, whose advice (try `instantiable!`) cannot help here.
///
/// This is the shape MSVC produces for `using F = std::function<...>` inside a
/// class, which no other standard library can be made to produce: they hide
/// std::function behind reserved names and bindgen erases it entirely. What
/// matters is not std::function but that the alias names something which
/// failed for a reason worth repeating, so this reaches the same shape with a
/// private nested class, and runs everywhere.
#[test]
fn test_class_scoped_alias_reports_the_targets_own_problem() {
    let hdr = indoc! {"
        #include <cstdint>
        class Requester {
            class Impl {};
        public:
            Requester() {}
            using Handler = Impl;
            void sendRequest(Handler h) { (void) h; }
            uint32_t answer() const { return 42; }
        };
    "};
    let rs = quote! {
        let requester = ffi::Requester::new().within_unique_ptr();
        assert_eq!(requester.answer(), 42);
    };
    run_test_ex(
        "",
        hdr,
        rs,
        directives_from_lists(&["Requester"], &[], None),
        None,
        Some(make_string_finder(vec![
            "This type is nested within another struct/class with protected or private visibility"
                .to_string(),
        ])),
        None,
    );
}

/// A class nested inside the class which holds it by value. bindgen hoists
/// the nested definition out into the module its enclosing class is in, and
/// can emit it after that class - at which point the POD check, which used to
/// take the structs in the order they arrived, had no record of the nested
/// type yet and ruled the enclosing one out of being POD for good.
#[test]
fn test_pod_holding_nested_struct() {
    let hdr = indoc! {"
        struct fx_Outer {
            struct fx_Inner { int a; };
            fx_Inner inner;
        };
    "};
    let rs = quote! {
        let outer = ffi::fx_Outer { inner: ffi::fx_Outer_fx_Inner { a: 42 } };
        assert_eq!(outer.inner.a, 42);
    };
    run_test("", hdr, rs, &[], &["fx_Outer", "fx_Outer_fx_Inner"]);
}

/// C++ deletes the default constructor of a class with a const data member
/// and no initializer for it, so nothing may synthesize a `new()` for one.
#[test]
fn test_const_field_deletes_default_constructor() {
    let hdr = indoc! {"
        struct fx_HasConstField {
            const int m;
        };
        inline int read_it(const fx_HasConstField& h) { return h.m; }
    "};
    run_test("", hdr, quote! {}, &["fx_HasConstField", "read_it"], &[]);
}

/// The two things `const` can qualify in a pointer field are different facts,
/// and only one of them touches the constructors. `T* const` is a const
/// field, so C++ deletes the default constructor; `const T*` is an ordinary
/// pointer at something the pointee's owner won't let you write to, and the
/// class is default-constructible as usual. bindgen renders both as
/// `*const T`/`*mut T` without help, which is why the marker has to
/// distinguish them.
#[test]
fn test_const_pointee_does_not_delete_default_constructor() {
    let hdr = indoc! {"
        struct fx_Pointee { int a; };
        struct fx_HasPointerToConst {
            const fx_Pointee* p;
        };
        inline int fx_count_it(const fx_HasPointerToConst& h) { return h.p ? h.p->a : 0; }
    "};
    let rs = quote! {
        let h = ffi::fx_HasPointerToConst::new().within_unique_ptr();
        assert_eq!(ffi::fx_count_it(&h), autocxx::c_int(0));
    };
    run_test("", hdr, rs, &["fx_HasPointerToConst", "fx_count_it"], &[]);
}

/// C++ folds a `const` element type into the array: `const int a[3]` is an
/// array of const ints, and the member is as unassignable as a plain `const
/// int` is. So it deletes the default constructor the same way, and the
/// marker has to survive the array.
#[test]
fn test_const_array_field_deletes_default_constructor() {
    let hdr = indoc! {"
        struct fx_HasConstArray {
            const int a[3];
        };
        inline int fx_read_first(const fx_HasConstArray& h) { return h.a[0]; }
    "};
    run_test(
        "",
        hdr,
        quote! {},
        &["fx_HasConstArray", "fx_read_first"],
        &[],
    );
}

/// A `const` bitfield is `const` like any other member, so it deletes the
/// default constructor too - and it is the shape which decides how bindgen's
/// const marker has to be declared. bindgen renders a bitfield's accessors
/// with the member's own type and casts between it and the allocation unit's
/// integer (`self.a() as u32`), so a marker declared as a newtype makes the
/// generated bindgen module fail to compile with `error[E0605]:
/// non-primitive cast`. It is declared as a transparent alias instead - see
/// `make_bindgen_builder`.
#[test]
fn test_const_bitfield_field() {
    let hdr = indoc! {"
        struct fx_ConstBitfield {
            fx_ConstBitfield() : a(1), b(2) {}
            const int a : 3;
            int b : 3;
        };
        inline int fx_read_bf(const fx_ConstBitfield& h) { return h.b; }
    "};
    run_test("", hdr, quote! {}, &["fx_ConstBitfield", "fx_read_bf"], &[]);
}

/// `typedef const int ci` is `const` at the alias, not at each use of it, so
/// a field of that type is only known to be unassignable if the typedef's
/// analysis carried the fact forward. It converts to a plain `c_int`, which
/// cannot say it - the same reason the analysis already remembers whether the
/// target was an rvalue reference.
#[test]
fn test_const_field_through_typedef_deletes_default_constructor() {
    let hdr = indoc! {"
        typedef const int fx_ci;
        struct fx_HasTypedefConst { fx_ci m; };
        inline int fx_read_tc(const fx_HasTypedefConst& h) { return h.m; }
    "};
    run_test(
        "",
        hdr,
        quote! {},
        &["fx_HasTypedefConst", "fx_read_tc"],
        &[],
    );
}

/// A `const` alias for another alias. bindgen resolves an alias's target
/// through the wrapper which held the constness before rendering it, so
/// `typedef int I; typedef const I CI;` comes out as `pub type CI = root::I;`
/// with no marker anywhere. The per-member report is the other channel: it
/// reads the member's type in bindgen's own IR, where the qualifier is still
/// on whichever link of the chain C++ put it.
#[test]
fn test_const_field_through_typedef_chain_deletes_default_constructor() {
    let hdr = indoc! {"
        typedef int fx_I;
        typedef const fx_I fx_CI;
        struct fx_HasChain { fx_CI m; };
        inline int fx_read_chain(const fx_HasChain& h) { return h.m; }
    "};
    run_test("", hdr, quote! {}, &["fx_HasChain", "fx_read_chain"], &[]);
}

/// A second alias for one which was already `const` still deletes the default
/// constructor: `A` carries the marker because its own target is a builtin,
/// and `B` picks it up when its target is resolved.
#[test]
fn test_const_field_through_alias_of_const_alias() {
    let hdr = indoc! {"
        typedef const int fx_A;
        typedef fx_A fx_B;
        struct fx_HasB { fx_B m; };
        inline int fx_read_b(const fx_HasB& h) { return h.m; }
    "};
    run_test("", hdr, quote! {}, &["fx_HasB", "fx_read_b"], &[]);
}

/// A `const` alias for an enum. bindgen resolves an alias's target through the
/// wrapper which held the constness before rendering it, so the marker never
/// reaches the `pub use` it emits for an enum alias - which is just as well,
/// because `pub use path::Marker<E> as CE;` would not be a legal `use`.
///
/// What this pins is that the alias compiles and the field is refused, not
/// which rule refused it: autocxx credits no enum with a default constructor,
/// so the field is turned down as `DependencyLacksIt` before its constness is
/// consulted at all. The const channel for an alias chain is pinned by
/// `test_const_field_through_typedef_chain_deletes_default_constructor`,
/// which puts an `int` behind the alias so that nothing coarser declines
/// first.
#[test]
fn test_const_enum_typedef() {
    let hdr = indoc! {"
        enum fx_E { fx_A = 1, fx_B = 2 };
        typedef const fx_E fx_CE;
        struct fx_HasConstEnum { fx_CE m; };
        inline int fx_take_ce(fx_CE e) { return (int)e; }
    "};
    run_test(
        "",
        hdr,
        quote! {},
        &["fx_take_ce", "fx_E", "fx_HasConstEnum"],
        &[],
    );
}

/// A `const` bitfield deletes the default constructor like any other `const`
/// member. bindgen emits no field of the member's own type for a bitfield -
/// the struct gets one allocation unit for the whole run, and the member
/// survives only as accessors - so the const marker has nowhere to land that
/// `find_constructors_present` reads. The per-member report is where the
/// constness arrives instead.
#[test]
fn test_const_bitfield_deletes_default_constructor() {
    let hdr = indoc! {"
        struct fx_ConstBf { const int a : 3; };
        inline int fx_read_bf_only(const fx_ConstBf& h) { return h.a; }
    "};
    run_test("", hdr, quote! {}, &["fx_ConstBf", "fx_read_bf_only"], &[]);
}

/// `typedef const int ci;` puts the qualifier on the alias's target, so a
/// bitfield declared with it is `const` without its own type saying so. The
/// per-member report has to follow the alias, since a bitfield reaches the
/// analysis through nothing else.
#[test]
fn test_const_bitfield_through_typedef_deletes_default_constructor() {
    let hdr = indoc! {"
        typedef const int fx_pci;
        struct fx_TdConstBf { fx_pci a : 3; };
        inline int fx_read_tdbf(const fx_TdConstBf& h) { return h.a; }
    "};
    run_test("", hdr, quote! {}, &["fx_TdConstBf", "fx_read_tdbf"], &[]);
}

/// A bitfield and an ordinary field whose bindgen names collide: C++ `type` is
/// a Rust keyword, so bindgen calls the bitfield's accessors `type_`, which is
/// also the name of the field next to it. The initializer belongs to the
/// bitfield alone, and crediting the `const` field with it would offer a
/// `new()` C++ deletes.
#[test]
fn test_bitfield_name_collision_keeps_const_field_blocking() {
    let hdr = indoc! {"
        struct fx_Collide { int type : 3 = 1; const int type_; };
        inline int fx_read_collide(const fx_Collide& h) { return h.type_; }
    "};
    run_test_ex(
        "",
        hdr,
        quote! {},
        directives_from_lists(&["fx_Collide", "fx_read_collide"], &[], None),
        make_cpp20_adder(),
        None,
        None,
    );
}

/// google/autocxx#816: a member whose own type has no default constructor
/// does not stop C++ declaring one for the class, so long as the member has a
/// default member initializer to construct it with.
#[test]
fn test_member_initializer_supplies_default_constructor() {
    let hdr = indoc! {"
        struct fx_NoDefault {
            fx_NoDefault(int v) : v(v) {}
            int v;
        };
        struct fx_HasInitializer { fx_NoDefault m = fx_NoDefault(3); };
        inline int fx_read_init(const fx_HasInitializer& h) { return h.m.v; }
    "};
    let rs = quote! {
        let h = ffi::fx_HasInitializer::new().within_unique_ptr();
        assert_eq!(ffi::fx_read_init(&h), autocxx::c_int(3));
    };
    run_test(
        "",
        hdr,
        rs,
        &["fx_HasInitializer", "fx_read_init", "fx_NoDefault"],
        &[],
    );
}

/// The initializer excuses the member's own default constructor and nothing
/// else. C++ still has to be able to destroy the member, so a class holding an
/// initialized member with an inaccessible destructor keeps no default
/// constructor of its own.
#[test]
fn test_member_initializer_does_not_excuse_a_missing_destructor() {
    let hdr = indoc! {"
        struct fx_Undestroyable {
            fx_Undestroyable(int v) : v(v) {}
            int v;
          private:
            ~fx_Undestroyable() {}
        };
        struct fx_HoldsUndestroyable { fx_Undestroyable m{1}; };
        inline int fx_read_hu(const fx_HoldsUndestroyable& h) { return h.m.v; }
    "};
    run_test_ex(
        "",
        hdr,
        quote! {},
        directives_from_lists(
            &["fx_HoldsUndestroyable", "fx_read_hu", "fx_Undestroyable"],
            &[],
            None,
        ),
        // C4624 says `fx_HoldsUndestroyable`'s destructor is implicitly
        // deleted, which is this fixture's premise rather than a defect in
        // it: a class holding a member it cannot destroy is exactly what has
        // to be put to the analysis here, and no version of this header both
        // says that and avoids the warning. Scoped to this one fixture, the
        // way the note beside `/WX` in `configure_builder` describes for the
        // other C4624 test.
        make_clang_optional_arg_adder(&[], &["/wd4624"]),
        None,
        None,
    );
}

/// An initializer speaks for the member it initializes and for nothing else,
/// so a base class which has no default constructor still withdraws the
/// derived class's - including an empty base, which contributes no field and
/// so reaches this analysis only through bindgen's base-class report.
#[test]
fn test_member_initializer_does_not_excuse_a_base() {
    let hdr = indoc! {"
        struct fx_NoDefaultBase { fx_NoDefaultBase() = delete; };
        struct fx_InitMemberOnBase : public fx_NoDefaultBase { int m = 4; };
        inline int fx_read_imb(const fx_InitMemberOnBase& h) { return h.m; }
    "};
    run_test(
        "",
        hdr,
        quote! {},
        &["fx_InitMemberOnBase", "fx_read_imb", "fx_NoDefaultBase"],
        &[],
    );
}

/// A `const` member with a default member initializer has its one and only
/// value already, so C++ keeps the default constructor it would otherwise
/// have deleted.
#[test]
fn test_const_field_with_initializer_keeps_default_constructor() {
    let hdr = indoc! {"
        struct fx_ConstInit { const int m = 5; };
        inline int fx_read_ci(const fx_ConstInit& h) { return h.m; }
    "};
    let rs = quote! {
        let h = ffi::fx_ConstInit::new().within_unique_ptr();
        assert_eq!(ffi::fx_read_ci(&h), autocxx::c_int(5));
    };
    run_test("", hdr, rs, &["fx_ConstInit", "fx_read_ci"], &[]);
}

/// The same for a reference member: the initializer is what an implicitly
/// declared constructor binds it to, so there is one.
#[test]
fn test_reference_field_with_initializer_keeps_default_constructor() {
    let hdr = indoc! {"
        struct fx_RefInit { int x; int& r = x; };
        inline int fx_read_ri(const fx_RefInit& h) { return h.r; }
    "};
    let rs = quote! {
        let h = ffi::fx_RefInit::new().within_unique_ptr();
        ffi::fx_read_ri(&h);
    };
    run_test("", hdr, rs, &["fx_RefInit", "fx_read_ri"], &[]);
}

/// A bitfield may carry a default member initializer too, since C++20. clang
/// exposes no cursor for one - its visitor stops at the width expression -
/// so this is the case which decides that the fact has to be read off the
/// declaration's tokens rather than its child cursors.
#[test]
fn test_const_bitfield_with_initializer_keeps_default_constructor() {
    let hdr = indoc! {"
        struct fx_ConstBfInit { const int a : 3 = 2; };
        inline int fx_read_bfi(const fx_ConstBfInit& h) { return h.a; }
    "};
    let rs = quote! {
        let h = ffi::fx_ConstBfInit::new().within_unique_ptr();
        assert_eq!(ffi::fx_read_bfi(&h), autocxx::c_int(2));
    };
    run_test_ex(
        "",
        hdr,
        rs,
        directives_from_lists(&["fx_ConstBfInit", "fx_read_bfi"], &[], None),
        make_cpp20_adder(),
        None,
        None,
    );
}

/// A `const` member of class type deletes the copy *and* the move constructor
/// when its class has no constructor taking a const source: moving from a
/// `const fx_M` yields a `const fx_M&&`, which `fx_M(fx_M&&)` cannot take, and
/// the copy it falls back to is deleted. Asking what the field's *type* can do
/// said "movable".
#[test]
fn test_const_class_member_deletes_copy() {
    let hdr = indoc! {"
        struct fx_M {
            fx_M();
            fx_M(fx_M&&);
            fx_M(const fx_M&) = delete;
            int x;
        };
        struct fx_S { const fx_M m; };
        inline int fx_read_s(const fx_S& s) { return s.m.x; }
    "};
    run_test("", hdr, quote! {}, &["fx_S", "fx_read_s", "fx_M"], &[]);
}

/// The other half of the same rule, which must not withdraw what C++ keeps.
/// `fx_CM` declares a copy constructor, so C++ gives it no move constructor at
/// all - but the copy it does have takes a const source, which is the one C++
/// uses to move a `const` member. So `fx_S2` has both a copy and a move
/// constructor, and returning one by value has to work. Asking `fx_CM` what it
/// can do would say "no move constructor" and cost `fx_S2` its own.
#[test]
fn test_const_class_member_copyable_from_const_keeps_move() {
    let hdr = indoc! {"
        struct fx_CM {
            fx_CM() : x(3) {}
            fx_CM(const fx_CM& other) : x(other.x) {}
            int x;
        };
        struct fx_S2 { const fx_CM m; };
        inline fx_S2 fx_make_s2() { return fx_S2{fx_CM()}; }
        inline int fx_read_s2(const fx_S2& s) { return s.m.x; }
    "};
    let rs = quote! {
        let s = ffi::fx_make_s2().within_unique_ptr();
        moveit! {
            let moved = autocxx::moveit::new::mov(s);
        }
        assert_eq!(ffi::fx_read_s2(&moved), autocxx::c_int(3));
    };
    run_test(
        "",
        hdr,
        rs,
        &["fx_S2", "fx_CM", "fx_make_s2", "fx_read_s2"],
        &[],
    );
}

/// A declared `fx_DRM(const fx_DRM&&) = delete` is what a `const` member's
/// xvalue selects, so C++ defines `fx_S5`'s move constructor as deleted -
/// however copyable the member is on its own. That has to be the answer for
/// the field rather than "copyable, so near enough": `fx_S5` also holds an
/// `fx_N` which cannot be copied, so its copy constructor is deleted too and
/// `fx_S5(std::move(s))` has nothing left to call. Treating the member as
/// movable-because-copyable synthesized a move wrapper both compilers refuse.
#[test]
fn test_const_class_member_with_deleted_const_rvalue_constructor_deletes_move() {
    let hdr = indoc! {"
        struct fx_DRM {
            fx_DRM();
            fx_DRM(const fx_DRM&);
            fx_DRM(const fx_DRM&&) = delete;
        };
        struct fx_N {
            fx_N();
            fx_N(const fx_N&) = delete;
            fx_N(fx_N&&);
        };
        struct fx_S5 { const fx_DRM m; fx_N n; };
    "};
    run_test("", hdr, quote! {}, &["fx_S5", "fx_DRM", "fx_N"], &[]);
}

/// The marker and the array layers alternate all the way down for a
/// multidimensional array, because bindgen folds a const element type into the
/// array's own constness as well as leaving it on the element. A walk which
/// stops at the first of either finds a marker where it wanted a type name.
#[test]
fn test_const_multidimensional_array_field() {
    let hdr = indoc! {"
        struct fx_Cell { int v; };
        struct fx_HasConstGrid {
            const fx_Cell grid[2][3];
        };
        inline int fx_read_grid(const fx_HasConstGrid& h) { return h.grid[1][2].v; }
    "};
    run_test(
        "",
        hdr,
        quote! {},
        &["fx_HasConstGrid", "fx_read_grid", "fx_Cell"],
        &[],
    );
}

/// `Holder<const Thing>` and `Holder<Thing>` are two C++ types, and autocxx
/// used to make one type of them: the argument's `const` was resolved away
/// before bindgen rendered it, so both instantiations reached the same
/// synthesized concrete name and the C++ autocxx wrote for one was used for
/// the other. The smart-pointer lowering never saw this shape - a plain
/// template class goes straight to the concrete-type machinery.
#[test]
fn test_template_class_with_const_record_argument_is_its_own_type() {
    let hdr = indoc! {"
        struct fx_Thing { int v; };
        template <typename T> class fx_Holder { public: T t; };
        using fx_MutableHolder = fx_Holder<fx_Thing>;
        using fx_ConstHolder = fx_Holder<const fx_Thing>;
        inline int fx_read_mutable(const fx_MutableHolder& h) { return h.t.v; }
        inline int fx_read_const(const fx_ConstHolder& h) { return h.t.v; }
        inline int fx_read_both() {
            fx_MutableHolder m{{3}};
            fx_ConstHolder c{{4}};
            return fx_read_mutable(m) * 10 + fx_read_const(c);
        }
    "};
    // Rust has no instance of either holder to pass - autocxx invents no
    // constructors for a concrete template instantiation - so the two
    // signatures are what the test is about: cxx checks each against the real
    // C++ function, and before this they were both checked against
    // `fx_Holder<fx_Thing>`.
    run_test_ex(
        "",
        hdr,
        quote! {
            assert_eq!(ffi::fx_read_both(), autocxx::c_int(34));
        },
        directives_from_lists(
            &[
                "fx_Thing",
                "fx_MutableHolder",
                "fx_ConstHolder",
                "fx_read_mutable",
                "fx_read_const",
                "fx_read_both",
            ],
            &[],
            None,
        ),
        None,
        // The two concrete types autocxx invents, which is where the collision
        // showed: one name for both meant one C++ typedef for both.
        Some(make_string_finder(vec![
            "fx_Holder_fx_Thing_AutocxxConcrete".into(),
            "fx_Holder_const_fx_Thing_AutocxxConcrete".into(),
        ])),
        None,
    );
}

/// The same for a builtin argument, where bindgen already kept the `const` and
/// autocxx then wrote bindgen's marker into the C++ verbatim - a typedef
/// naming `__bindgen_marker_Const<int>`, which is not a C++ type at all. The
/// smart-pointer lowering taught `type_to_cpp` to write the qualifier instead;
/// this is the other route to the same function.
#[test]
fn test_template_class_with_const_builtin_argument() {
    let hdr = indoc! {"
        template <typename T> class fx_Box { public: T t; };
        using fx_ConstIntBox = fx_Box<const int>;
        inline int fx_read_const_int(const fx_ConstIntBox& b) { return b.t; }
        inline int fx_read_boxed_five() { fx_ConstIntBox b{5}; return fx_read_const_int(b); }
    "};
    run_test(
        "",
        hdr,
        quote! {
            assert_eq!(ffi::fx_read_boxed_five(), autocxx::c_int(5));
        },
        &["fx_ConstIntBox", "fx_read_const_int", "fx_read_boxed_five"],
        &[],
    );
}

/// `const` *pointer* arguments, which are why the qualifier is written to the
/// right of what it qualifies. `Ptr* const` is a constant pointer and the
/// left-hand spelling `const Ptr*` is a pointer to a constant, so which side
/// it goes on decides which of the two the generated C++ names - and for
/// `Ptr* const*`, where the qualifier is one declarator deep, there is no
/// left-hand spelling at all.
#[test]
fn test_template_class_with_const_pointer_argument() {
    let hdr = indoc! {"
        struct fx_Pointee { int v; };
        template <typename T> class fx_Slot { public: T t; };
        using fx_ConstPtrSlot = fx_Slot<fx_Pointee* const>;
        using fx_PtrToConstSlot = fx_Slot<const fx_Pointee*>;
        using fx_PtrToConstPtrSlot = fx_Slot<fx_Pointee* const*>;
        using fx_PtrToConstPtrToConstSlot = fx_Slot<const fx_Pointee* const*>;
        inline int fx_read_const_ptr(const fx_ConstPtrSlot& s) { return s.t->v; }
        inline int fx_read_ptr_to_const(const fx_PtrToConstSlot& s) { return s.t->v; }
        inline int fx_read_ptr_to_const_ptr(const fx_PtrToConstPtrSlot& s) { return (*s.t)->v; }
        inline int fx_read_both_consts(const fx_PtrToConstPtrToConstSlot& s) { return (*s.t)->v; }
        inline int fx_read_through_all() {
            static fx_Pointee p{7};
            static fx_Pointee* const pp = &p;
            static const fx_Pointee* const cpp = &p;
            fx_ConstPtrSlot a{&p};
            fx_PtrToConstSlot b{&p};
            fx_PtrToConstPtrSlot c{&pp};
            fx_PtrToConstPtrToConstSlot d{&cpp};
            return fx_read_const_ptr(a) + fx_read_ptr_to_const(b) +
                fx_read_ptr_to_const_ptr(c) + fx_read_both_consts(d);
        }
    "};
    run_test(
        "",
        hdr,
        quote! {
            assert_eq!(ffi::fx_read_through_all(), autocxx::c_int(28));
        },
        &[
            "fx_Pointee",
            "fx_ConstPtrSlot",
            "fx_PtrToConstSlot",
            "fx_PtrToConstPtrSlot",
            "fx_PtrToConstPtrToConstSlot",
            "fx_read_const_ptr",
            "fx_read_ptr_to_const",
            "fx_read_ptr_to_const_ptr",
            "fx_read_both_consts",
            "fx_read_through_all",
        ],
        &[],
    );
}

/// `std::unique_ptr<const T>` is lowered to the same opaque holder the shared
/// pointer gets, without the accessors - so a class payload, which used to be
/// invisible, now round-trips through Rust and back into C++.
#[test]
fn test_unique_ptr_of_const_record_round_trips() {
    let hdr = indoc! {"
        #include <memory>
        struct fx_Owned { int v; };
        inline std::unique_ptr<const fx_Owned> fx_make_owned() {
            return std::unique_ptr<const fx_Owned>(new fx_Owned { 9 });
        }
        inline int fx_read_owned(const std::unique_ptr<const fx_Owned>& p) {
            return p->v;
        }
    "};
    run_test_ex(
        "",
        hdr,
        quote! {
            let owned = ffi::fx_make_owned();
            assert_eq!(ffi::fx_read_owned(&owned), autocxx::c_int(9));
        },
        directives_from_lists(&["fx_Owned", "fx_make_owned", "fx_read_owned"], &[], None),
        None,
        Some(make_checks(vec![Box::new(CppMatcher::new(
            &["typedef std::unique_ptr<const fx_Owned>"],
            &["typedef std::unique_ptr<fx_Owned>"],
        ))])),
        None,
    );
}

/// A `std::vector` of `const` elements gets no lowering, where a
/// `std::vector<T*>` does: cxx needs an opaque holder to be a complete type,
/// and completing a `std::vector<const T>` is ill-formed. So the payload is
/// turned down here instead, which is the difference between a diagnostic
/// naming the container and a C++ compiler complaining about a specialization
/// nobody wrote.
#[test]
fn test_vector_of_const_record_is_refused() {
    let hdr = indoc! {"
        #include <vector>
        struct fx_Element { int v; };
        using fx_ConstElements = std::vector<const fx_Element>;
        inline int fx_count_const_elements(const fx_ConstElements& v) { return 0; }
    "};
    run_test_expect_fail_with_error(
        "",
        hdr,
        quote! {},
        &["fx_Element", "fx_ConstElements", "fx_count_const_elements"],
        &[],
        "A C++ std::vector was found whose payload C++ qualified `const`",
    );
}

/// `rust::Box` takes the same refusal by the same route, which is a different
/// `CxxGenericType` arm from the vector's and so worth its own test: nothing
/// else would notice if the check moved somewhere only the C++ containers
/// reach.
#[test]
fn test_rust_box_of_const_is_refused() {
    let hdr = indoc! {"
        #include <cstdint>
        #include <cxx.h>

        struct fx_BoxedRust;
        inline uint32_t fx_take_const_box(rust::Box<const fx_BoxedRust>) {
            return 4;
        }
    "};
    run_test_expect_fail_with_error_ex(
        "",
        hdr,
        quote! {},
        directives_from_lists(&["fx_take_const_box"], &[], None),
        "whose payload C++ qualified `const`",
    );
}

/// A `std::unique_ptr<const T>` *member* is lowered like any other use, and the
/// class keeps the facts its member gives it: a unique pointer is not
/// copyable, so neither is anything holding one.
#[test]
fn test_const_container_member_still_deletes_copy() {
    let hdr = indoc! {"
        #include <memory>
        struct fx_Held2 { int v; };
        struct fx_HoldsConst { std::unique_ptr<const fx_Held2> p; };
        inline int fx_read_held2(const fx_HoldsConst& h) { return h.p->v; }
    "};
    run_test_ex(
        "",
        hdr,
        quote! {},
        directives_from_lists(&["fx_Held2", "fx_HoldsConst", "fx_read_held2"], &[], None),
        None,
        Some(make_string_absence_finder(vec![
            "CopyNew for output :: fx_HoldsConst".into(),
        ])),
        None,
    );
}

/// bindgen finds an empty base zero-sized and emits no field for it, so the
/// derived class used to look like it had no bases at all - and its
/// constructors were then synthesized as if the base had none of its own
/// requirements. google/autocxx#832.
#[test]
fn test_empty_base_deletes_default_constructor() {
    let hdr = indoc! {"
        struct fx_EmptyBase {
            fx_EmptyBase() = delete;
        };
        struct fx_DerivedFromEmpty : public fx_EmptyBase {
            int x;
        };
        inline int read_x(const fx_DerivedFromEmpty& d) { return d.x; }
    "};
    run_test("", hdr, quote! {}, &["fx_DerivedFromEmpty", "read_x"], &[]);
}

/// The layout claim, checked against the compiler rather than assumed. Whether
/// an empty base takes up space in its derived class is the ABI's business,
/// not the language's, so the test compares what Rust believes the type is
/// with what C++ says it is, on whichever ABI it is running.
#[test]
fn test_pod_over_an_empty_base_has_the_layout_cpp_gives_it() {
    let hdr = indoc! {"
        #include <cstddef>
        struct fx_EmptyLayoutBase { int describe() const { return 3; } };
        struct fx_PodOverEmpty : public fx_EmptyLayoutBase { int x; };
        inline size_t fx_sizeof_pod_over_empty() { return sizeof(fx_PodOverEmpty); }
        inline size_t fx_alignof_pod_over_empty() { return alignof(fx_PodOverEmpty); }
    "};
    run_test(
        "",
        hdr,
        quote! {
            assert_eq!(
                std::mem::size_of::<ffi::fx_PodOverEmpty>(),
                ffi::fx_sizeof_pod_over_empty()
            );
            assert_eq!(
                std::mem::align_of::<ffi::fx_PodOverEmpty>(),
                ffi::fx_alignof_pod_over_empty()
            );
            let p = ffi::fx_PodOverEmpty { x: 1 };
            assert_eq!(p.x, 1);
        },
        &["fx_sizeof_pod_over_empty", "fx_alignof_pod_over_empty"],
        &["fx_PodOverEmpty"],
    );
}

/// The upcast half of google/autocxx#832: a public empty base is a base you
/// can convert to, and autocxx generates the `AsRef` for it only if it knows
/// the base is there. Before `denote_base_class` there was no `as_ref` to
/// call, and the method on the base was unreachable from the derived class.
#[test]
fn test_empty_base_is_upcastable() {
    let hdr = indoc! {"
        struct fx_EmptyGreeter {
            int greet() const { return 42; }
        };
        struct fx_DerivedGreeter : public fx_EmptyGreeter {
            int x;
            fx_DerivedGreeter() : x(1) {}
        };
    "};
    run_test(
        "",
        hdr,
        quote! {
            let d = ffi::fx_DerivedGreeter::new().within_unique_ptr();
            let base: &ffi::fx_EmptyGreeter = d.as_ref().unwrap().as_ref();
            assert_eq!(base.greet(), autocxx::c_int(42));
        },
        &["fx_DerivedGreeter", "fx_EmptyGreeter"],
        &[],
    );
}

/// google/autocxx#1466: a class with a virtual base is not laid out as its
/// fields are - the base sits at an offset the object carries at runtime - so
/// holding one by value in Rust would copy something else. Nothing in
/// bindgen's output says so for this shape: the virtual base gets no field,
/// and because the vtable pointer comes from the base rather than from this
/// class, all that is written for it is anonymous padding. A class which needs
/// its own vtable pointer gets a `vtable_` field, which autocxx already
/// refuses on - so that shape was never the one at risk.
///
/// The `static_assert` is what makes this a layout claim rather than a
/// preference: it pins that this class is bigger than the field it declares,
/// so its own fields are not the whole story, and the refusal below is the
/// answer that does not require autocxx to have understood the rest.
#[test]
fn test_virtual_base_is_refused_as_pod() {
    let hdr = indoc! {"
        struct fx_VirtualBase { virtual int f() const { return 1; } };
        struct fx_DerivedVirtually : public virtual fx_VirtualBase { int b; };
        static_assert(sizeof(fx_DerivedVirtually) > sizeof(int),
                      \"a virtual base costs more than the derived class's own fields\");
    "};
    run_test_expect_fail_with_error(
        "",
        hdr,
        quote! {},
        &[],
        &["fx_DerivedVirtually"],
        "inherits a base class virtually",
    );
}

/// The same class is fine as a non-POD type: autocxx reaches it through a
/// pointer, where C++ does the offset arithmetic itself.
#[test]
fn test_virtual_base_is_allowed_as_non_pod() {
    let hdr = indoc! {"
        struct fx_VBase2 { int a; fx_VBase2() : a(3) {} };
        struct fx_DerivedVirtually2 : public virtual fx_VBase2 { int b; fx_DerivedVirtually2() : b(4) {} };
        inline int fx_sum(const fx_DerivedVirtually2& d) { return d.a + d.b; }
    "};
    run_test(
        "",
        hdr,
        quote! {
            let d = ffi::fx_DerivedVirtually2::new().within_unique_ptr();
            assert_eq!(ffi::fx_sum(d.as_ref().unwrap()), autocxx::c_int(7));
        },
        &["fx_DerivedVirtually2", "fx_sum"],
        &[],
    );
}

/// A pure virtual reached through a virtual base, this time overridden. The
/// google/autocxx#1326 fix must not answer "abstract" to everything which inherits
/// virtually: this class is concrete and has to stay constructible.
#[test]
fn test_pure_virtual_overridden_through_virtual_base() {
    let hdr = indoc! {"
        struct fx_VAbstract {
            virtual int f() const = 0;
            virtual ~fx_VAbstract() {}
        };
        struct fx_VConcrete : public virtual fx_VAbstract {
            int f() const override { return 7; }
        };
    "};
    run_test(
        "",
        hdr,
        quote! {
            let c = ffi::fx_VConcrete::new().within_unique_ptr();
            assert_eq!(c.f(), autocxx::c_int(7));
        },
        &["fx_VConcrete", "fx_VAbstract"],
        &[],
    );
}

/// A virtual diamond, which is the shape virtual inheritance exists for.
/// `fx_DiaLeft` overrides the pure virtual and `fx_DiaRight` does not, but they
/// share one `fx_DiaBase` subobject, so `fx_DiaLeft::f` is its final overrider
/// and `fx_DiaDiamond` is concrete. Cancelling an inherited pure virtual only
/// against the derived class's own overrides would call it abstract and
/// withdraw its constructors.
#[test]
fn test_virtual_diamond_is_concrete() {
    let hdr = indoc! {"
        struct fx_DiaBase {
            virtual int f() const = 0;
            virtual ~fx_DiaBase() {}
        };
        struct fx_DiaLeft : public virtual fx_DiaBase {
            int f() const override { return 5; }
        };
        struct fx_DiaRight : public virtual fx_DiaBase {};
        struct fx_DiaDiamond : public fx_DiaLeft, public fx_DiaRight {};
    "};
    run_test_ex(
        "",
        hdr,
        quote! {
            let d = ffi::fx_DiaDiamond::new().within_unique_ptr();
            let left: &ffi::fx_DiaLeft = d.as_ref().unwrap().as_ref();
            assert_eq!(left.f(), autocxx::c_int(5));
        },
        directives_from_lists(
            &["fx_DiaDiamond", "fx_DiaLeft", "fx_DiaRight", "fx_DiaBase"],
            &[],
            None,
        ),
        // cl reports `C4250: 'fx_DiaDiamond': inherits 'fx_DiaLeft::f' via
        // dominance`, which is word for word the proposition this test exists
        // to assert. It is emitted against the fixture's own header, not
        // against anything autocxx wrote, so no change to the generator could
        // remove it, and no shape which does not draw it would exercise the
        // dominance rule. Scoped off here rather than answered.
        make_clang_optional_arg_adder(&[], &["/wd4250"]),
        None,
        None,
    );
}

/// Half of that diamond on its own: a class which inherits a pure virtual
/// through a virtual base and overrides nothing is abstract, so nothing may
/// construct it. The `new()` in the diamond above is only meaningful while
/// this holds - which is what google/autocxx#1326 reported, with a virtual
/// destructor so that the fixture needs no warning scoped off.
#[test]
fn test_virtual_base_leaves_class_abstract() {
    let hdr = indoc! {"
        struct fx_AbsBase {
            virtual int f() const = 0;
            virtual ~fx_AbsBase() {}
        };
        struct fx_AbsDerived : public virtual fx_AbsBase {};
        inline int fx_call_abs(const fx_AbsBase& b) { return b.f(); }
    "};
    run_test("", hdr, quote! {}, &["fx_AbsDerived", "fx_call_abs"], &[]);
}

/// The virtual diamond again, with the shared base named through a typedef.
/// Which class's pure virtuals those are is a question for the class the
/// typedef names; whether the inheritance is virtual is recorded against the
/// name it was written under.
#[test]
fn test_virtual_diamond_through_a_typedef_is_concrete() {
    let hdr = indoc! {"
        struct fx_TdBase {
            virtual int f() const = 0;
            virtual ~fx_TdBase() {}
        };
        typedef fx_TdBase fx_TdAlias;
        struct fx_TdLeft : public virtual fx_TdAlias {
            int f() const override { return 9; }
        };
        struct fx_TdRight : public virtual fx_TdAlias {};
        struct fx_TdDiamond : public fx_TdLeft, public fx_TdRight {};
    "};
    run_test_ex(
        "",
        hdr,
        quote! {
            let d = ffi::fx_TdDiamond::new().within_unique_ptr();
            let left: &ffi::fx_TdLeft = d.as_ref().unwrap().as_ref();
            assert_eq!(left.f(), autocxx::c_int(9));
        },
        directives_from_lists(
            &["fx_TdDiamond", "fx_TdLeft", "fx_TdRight", "fx_TdBase"],
            &[],
            None,
        ),
        // As above: cl's dominance report is this fixture's subject too.
        make_clang_optional_arg_adder(&[], &["/wd4250"]),
        None,
        None,
    );
}

/// A C++ class whose name ends in the suffix autocxx renames *functions* with.
/// The name bindgen reports a base under is the identity autocxx looks the base
/// up by, so filing this class under `fx_SuffixB` would make `fx_SuffixA` a
/// base of `fx_SuffixB` as well as the other way round - a cycle in a hierarchy
/// which has none, and a panic rather than a diagnostic. Empty base, so the
/// report is the only channel.
///
/// The class is not itself named in the `generate!` list, and cannot usefully
/// be: the name index cannot tell such a class from the renamed function, so
/// the C++ name recorded for it is the shortened one and the `#[cxx_name]`
/// built from it names a class C++ does not have. That is a naming defect of
/// its own, and this fixture is about the inheritance the name is used for.
#[test]
fn test_class_named_like_a_renamed_function_is_not_confused_with_another() {
    let hdr = indoc! {"
        struct fx_SuffixB_bindgen_original {};
        struct fx_SuffixA : public fx_SuffixB_bindgen_original { int a; fx_SuffixA() : a(3) {} };
        struct fx_SuffixB : public fx_SuffixA { int b; fx_SuffixB() : b(4) {} };
        inline int fx_read_suffix_b(const fx_SuffixB& s) { return s.a + s.b; }
    "};
    run_test(
        "",
        hdr,
        quote! {
            let b = ffi::fx_SuffixB::new().within_unique_ptr();
            assert_eq!(ffi::fx_read_suffix_b(b.as_ref().unwrap()), autocxx::c_int(7));
        },
        &["fx_SuffixB", "fx_SuffixA", "fx_read_suffix_b"],
        &[],
    );
}

/// Two unrelated abstract classes declaring the same signature, both inherited
/// virtually into one class. `fx_UnrelLeft` overrides `fx_UnrelA::f`, which is
/// no override of `fx_UnrelB::f`, so `fx_UnrelDiamond` is still abstract. An
/// overrider recorded by signature alone would settle both.
#[test]
fn test_same_signature_in_unrelated_virtual_bases_stays_abstract() {
    let hdr = indoc! {"
        struct fx_UnrelA {
            virtual int f() const = 0;
            virtual ~fx_UnrelA() {}
        };
        struct fx_UnrelB {
            virtual int f() const = 0;
            virtual ~fx_UnrelB() {}
        };
        struct fx_UnrelLeft : public virtual fx_UnrelA {
            int f() const override { return 1; }
        };
        struct fx_UnrelRight : public virtual fx_UnrelB {};
        struct fx_UnrelDiamond : public fx_UnrelLeft, public fx_UnrelRight {};
    "};
    run_test(
        "",
        hdr,
        quote! {},
        &[
            "fx_UnrelDiamond",
            "fx_UnrelLeft",
            "fx_UnrelRight",
            "fx_UnrelA",
            "fx_UnrelB",
        ],
        &[],
    );
}

/// A class which makes a function pure again after a base had already
/// overridden it through a virtual base. `fx_StaleAgain::f` is the final
/// overrider and it is pure, so `fx_StaleAgain` and anything inheriting it
/// virtually are abstract - the earlier override does not settle the new
/// obligation, which belongs to a different class.
#[test]
fn test_pure_redeclaration_outlives_an_earlier_shared_override() {
    let hdr = indoc! {"
        struct fx_StaleBase {
            virtual int f() const = 0;
            virtual ~fx_StaleBase() {}
        };
        struct fx_StaleMid : public virtual fx_StaleBase {
            int f() const override { return 2; }
        };
        struct fx_StaleAgain : public fx_StaleMid {
            int f() const override = 0;
        };
        struct fx_FromStaleAgain : public virtual fx_StaleAgain {};
    "};
    run_test(
        "",
        hdr,
        quote! {},
        &[
            "fx_FromStaleAgain",
            "fx_StaleAgain",
            "fx_StaleMid",
            "fx_StaleBase",
        ],
        &[],
    );
}

/// The same diamond with one branch inheriting `fx_MixBase` normally. C++
/// gives `fx_MixDiamond` two `fx_MixBase` subobjects: the one inside
/// `fx_MixLeft`, which `fx_MixLeft::f` overrides, and the shared one reached
/// through `fx_MixRight`, which nothing overrides. So it is abstract, and an
/// override reached through a non-virtual base must not be allowed to settle
/// a pure virtual reached through a virtual one.
#[test]
fn test_mixed_diamond_stays_abstract() {
    let hdr = indoc! {"
        struct fx_MixBase {
            virtual int f() const = 0;
            virtual ~fx_MixBase() {}
        };
        struct fx_MixLeft : public fx_MixBase {
            int f() const override { return 5; }
        };
        struct fx_MixRight : public virtual fx_MixBase {};
        struct fx_MixDiamond : public fx_MixLeft, public fx_MixRight {};
    "};
    run_test(
        "",
        hdr,
        quote! {},
        &["fx_MixDiamond", "fx_MixLeft", "fx_MixRight", "fx_MixBase"],
        &[],
    );
}

/// A class which makes an inherited virtual function pure again. The
/// definition it overrides is in the hierarchy, so accumulating definitions
/// across the hierarchy without asking which one is the final overrider would
/// cancel `fx_PureAgain::f` with the `fx_HasImpl::f` it replaced.
#[test]
fn test_pure_virtual_redeclared_through_virtual_base() {
    let hdr = indoc! {"
        struct fx_HasImpl {
            virtual int f() const { return 1; }
            virtual ~fx_HasImpl() {}
        };
        struct fx_PureAgain : public fx_HasImpl {
            int f() const override = 0;
        };
        struct fx_FromPureAgain : public virtual fx_PureAgain {};
    "};
    run_test(
        "",
        hdr,
        quote! {},
        &["fx_FromPureAgain", "fx_PureAgain", "fx_HasImpl"],
        &[],
    );
}

/// An abstract base named through a typedef. The base arrives under the
/// typedef's name, and the pure virtuals which make a class abstract belong to
/// the class the typedef names.
#[test]
fn test_abstract_base_named_through_a_typedef() {
    let hdr = indoc! {"
        struct fx_AbstractOriginal {
            virtual int f() const = 0;
            virtual ~fx_AbstractOriginal() {}
        };
        typedef fx_AbstractOriginal fx_AbstractAlias;
        struct fx_FromAbstractAlias : public virtual fx_AbstractAlias {};
    "};
    run_test(
        "",
        hdr,
        quote! {},
        &["fx_FromAbstractAlias", "fx_AbstractOriginal"],
        &[],
    );
}

/// An empty base named through a typedef whose own constructors are all
/// usable. Naming the base is not enough - the name is the typedef's, and the
/// C++ rules have to run over the class it names - so the derived class keeps
/// the default constructor C++ gives it.
#[test]
fn test_empty_base_through_a_typedef_keeps_its_constructor() {
    let hdr = indoc! {"
        struct fx_PlainEmpty {};
        typedef fx_PlainEmpty fx_PlainEmptyAlias;
        struct fx_DerivedUsable : public fx_PlainEmptyAlias {
            int x;
        };
        inline int fx_read_usable(const fx_DerivedUsable& d) { return d.x; }
    "};
    run_test(
        "",
        hdr,
        quote! {
            let d = ffi::fx_DerivedUsable::new().within_unique_ptr();
            assert_eq!(ffi::fx_read_usable(d.as_ref().unwrap()), autocxx::c_int(0));
        },
        &["fx_DerivedUsable", "fx_read_usable"],
        &[],
    );
}

/// A virtual base which is a template instantiation. bindgen announces no item
/// for an instantiation, so the base it reports has no name autocxx can look
/// up - but it is still reported as virtual, which is the fact `pod!` has to
/// refuse on. Nothing else sees this base at all: it contributes no field, and
/// the vtable pointer comes from the base rather than from this class.
#[test]
fn test_virtual_template_base_is_refused_as_pod() {
    let hdr = indoc! {"
        template <typename T> struct fx_TBase {
            virtual int f() const { return 1; }
            virtual ~fx_TBase() {}
            T v;
        };
        struct fx_DerivedFromTemplate : public virtual fx_TBase<int> { int b; };
    "};
    run_test_expect_fail_with_error(
        "",
        hdr,
        quote! {},
        &[],
        &["fx_DerivedFromTemplate"],
        "inherits a base class virtually",
    );
}

/// An *empty* base named through a typedef. bindgen resolves such a base to
/// the typedef rather than to the class behind it - which is exactly what it
/// names in the `_base` field it generates for a non-empty one, so the two
/// channels agree and the class is seen to have one base, not two.
///
/// The constructor analysis follows the typedef to the class it names and
/// finds a deleted default constructor, so it offers none. Before the base was
/// reported it offered a `new()` which C++ refuses, because
/// `fx_RealEmptyBase` has no default constructor to run.
#[test]
fn test_empty_base_named_through_a_typedef() {
    let hdr = indoc! {"
        struct fx_RealEmptyBase { fx_RealEmptyBase() = delete; };
        typedef fx_RealEmptyBase fx_AliasedEmptyBase;
        struct fx_DerivedFromAliasedEmpty : public fx_AliasedEmptyBase {
            int x;
        };
        inline int fx_read_aliased_x(const fx_DerivedFromAliasedEmpty& d) { return d.x; }
    "};
    run_test(
        "",
        hdr,
        quote! {},
        &["fx_DerivedFromAliasedEmpty", "fx_read_aliased_x"],
        &[],
    );
}

/// A type only reachable through `using outer::Alias;` used to reach autocxx
/// as an opaque blob of the right size and alignment, because bindgen could
/// not name the declaration such a type is written through. For a four-byte
/// type that blob was plain `u32`, which autocxx once unwrapped and handed to
/// cxx - `void fx_take_bu(fx_BU)`, taking a struct by value, became
/// `fn fx_take_bu(b: u32)`, which nothing in either language complains about -
/// and later refused outright. bindgen now resolves the name, so the struct
/// crosses as itself.
#[test]
fn test_type_named_through_a_using_declaration_by_value() {
    let hdr = indoc! {"
        #include <cstdint>
        namespace fx_outer {
            template<typename T> struct fx_Box { T contents; };
            typedef fx_Box<uint32_t> fx_BU;
        }
        using fx_outer::fx_BU;
        inline fx_BU fx_give_bu() { fx_BU b; b.contents = 3; return b; }
        inline uint32_t fx_take_bu(fx_BU b) { return b.contents; }
    "};
    let rs = quote! {
        // Named, so that a binding which flattened the struct back to its
        // four bytes would not type-check.
        let b: cxx::UniquePtr<ffi::fx_outer::fx_BU> = ffi::fx_give_bu();
        assert_eq!(ffi::fx_take_bu(b), 3);
    };
    run_test("", hdr, rs, &["fx_give_bu", "fx_take_bu"], &[]);
}

/// The same type spelt through the namespace which declares it, which bound
/// even while the using-declared spelling did not.
#[test]
fn test_type_named_through_its_own_namespace_is_not_hidden() {
    let hdr = indoc! {"
        #include <cstdint>
        namespace fx_outer {
            template<typename T> struct fx_Box { T contents; };
            typedef fx_Box<uint32_t> fx_BU;
        }
        inline uint32_t fx_take_bu_ns(fx_outer::fx_BU b) { return b.contents; }
    "};
    run_test("", hdr, quote! {}, &["fx_take_bu_ns"], &[]);
}

/// As above, where the type is what the function returns. The old bindings
/// said `fn fx_give_bu() -> u32`.
#[test]
fn test_type_named_through_a_using_declaration_as_return_value() {
    let hdr = indoc! {"
        #include <cstdint>
        namespace fx_outer {
            template<typename T> struct fx_Box { T contents; fx_Box() : contents(0) {} };
            typedef fx_Box<uint32_t> fx_BU;
        }
        using fx_outer::fx_BU;
        inline fx_BU fx_give_bu() { fx_BU b; b.contents = 7; return b; }
        inline uint32_t fx_read_bu(const fx_BU& b) { return b.contents; }
    "};
    let rs = quote! {
        let b = ffi::fx_give_bu();
        assert_eq!(ffi::fx_read_bu(b.as_ref().unwrap()), 7);
    };
    run_test("", hdr, rs, &["fx_give_bu", "fx_read_bu"], &[]);
}

/// The name is resolved behind a reference too, where the old bindings said
/// `&u32` for a reference to a struct. The `const` written in front of the
/// name is part of the elaborated type's spelling, so the name has to be read
/// off the type that one names rather than off the type itself.
#[test]
fn test_type_named_through_a_using_declaration_behind_a_reference() {
    let hdr = indoc! {"
        #include <cstdint>
        namespace fx_outer {
            template<typename T> struct fx_Box { T contents; };
            typedef fx_Box<uint32_t> fx_BU;
        }
        using fx_outer::fx_BU;
        inline fx_BU fx_give_bu() { fx_BU b; b.contents = 9; return b; }
        inline uint32_t fx_take_bu_ref(const fx_BU& b) { return b.contents; }
    "};
    let rs = quote! {
        let b = ffi::fx_give_bu();
        assert_eq!(ffi::fx_take_bu_ref(b.as_ref().unwrap()), 9);
    };
    run_test("", hdr, rs, &["fx_give_bu", "fx_take_bu_ref"], &[]);
}

/// And inside a cxx container, which names its payload type in the bridge, so
/// a blob was no more use there than in a bare parameter. The payload reaches
/// bindgen as a template argument, whose location cursor is the declaration
/// the type does not have - which is why the resolution is by name rather than
/// by a walk out through the scopes the name is visible in.
#[test]
fn test_type_named_through_a_using_declaration_inside_a_container() {
    let hdr = indoc! {"
        #include <cstdint>
        #include <memory>
        #include <vector>
        namespace fx_outer {
            template<typename T> struct fx_Box { T contents; };
            typedef fx_Box<uint32_t> fx_BU;
        }
        using fx_outer::fx_BU;
        inline std::unique_ptr<fx_BU> fx_give_uptr() {
            auto b = std::make_unique<fx_BU>();
            b->contents = 4;
            return b;
        }
        inline uint32_t fx_take_uptr(std::unique_ptr<fx_BU> b) { return b->contents; }
        inline std::unique_ptr<std::vector<fx_BU>> fx_give_vec() {
            auto v = std::make_unique<std::vector<fx_BU>>();
            v->push_back(fx_BU{5});
            return v;
        }
        inline uint32_t fx_take_vec(const std::vector<fx_BU>& b) { return b[0].contents; }
    "};
    let rs = quote! {
        assert_eq!(ffi::fx_take_uptr(ffi::fx_give_uptr()), 4);
        assert_eq!(ffi::fx_take_vec(ffi::fx_give_vec().as_ref().unwrap()), 5);
    };
    run_test(
        "",
        hdr,
        rs,
        &["fx_give_uptr", "fx_take_uptr", "fx_give_vec", "fx_take_vec"],
        &[],
    );
}

/// A using-declared type as an array element in a struct field. This used to
/// hold an array of the blob, and pinned that the refusal did not follow the
/// element into the field; now the element is named, and what it pins is that
/// naming it leaves the field alone.
#[test]
fn test_array_of_using_declared_type_is_allowed_in_a_struct_field() {
    let hdr = indoc! {"
        #include <cstdint>
        namespace fx_outer {
            struct fx_Plain { uint32_t contents; };
        }
        using fx_outer::fx_Plain;
        struct fx_HoldsArray { fx_Plain arr[4]; uint32_t tail; };
    "};
    let rs = quote! {
        let h = ffi::fx_HoldsArray::default();
        assert_eq!(h.tail, 0);
        assert_eq!(h.arr[2].contents, 0);
    };
    run_test("", hdr, rs, &[], &["fx_HoldsArray", "fx_outer::fx_Plain"]);
}

/// The same field where the element is a typedef to a template instantiation.
/// This used to be allowed without the question being asked: the element was a
/// blob, and an array of a blob has always been let through
/// (`ByValueChecker::ingest_struct`). Now that the element is named, POD
/// analysis has to decide whether the instantiation is safe to hold by value,
/// and it cannot - the concrete type autocxx synthesizes for an instantiation
/// carries no members for the analysis to look at. The refusal says so. This is
/// the cost of naming the element, and the test is here to show it changing if
/// that analysis ever learns to see through a synthesized concrete type.
#[test]
fn test_pod_array_of_concrete_instantiation_is_refused() {
    let hdr = indoc! {"
        #include <cstdint>
        namespace fx_outer {
            template<typename T> struct fx_Box { T contents; };
            typedef fx_Box<uint32_t> fx_BU;
        }
        using fx_outer::fx_BU;
        struct fx_HoldsArray { fx_BU arr[4]; uint32_t tail; };
    "};
    run_test_expect_fail_with_error(
        "",
        hdr,
        quote! {},
        &[],
        &["fx_HoldsArray"],
        "which we know nothing about",
    );
}

/// Where bindgen gives us a *typedef* to a blob, the alias has a name of its
/// own, so it becomes an opaque type rather than an alias for an integer. What
/// then uses it in a position an opaque type cannot fill has to be refused -
/// and the refusal must carry the blob explanation, not the generic
/// forward-declaration message, whose advice (`instantiable!`) would send the
/// reader somewhere unhelpful.
#[test]
fn test_typedef_to_a_blob_explains_itself_when_used() {
    let hdr = indoc! {"
        #include <cstdint>
        #include <memory>
        template <typename T, T N> struct fx_seq { int x[N ? N : 1]; };
        template <typename T, T N> using fx_A = fx_seq<T, N>;
        template <int N> using fx_B = fx_A<int, N>;
        typedef fx_B<3> fx_Concrete;
        inline void fx_take_conc(std::unique_ptr<fx_Concrete> c) { (void)c; }
    "};
    run_test_expect_fail_with_errors(
        "",
        hdr,
        quote! {},
        &["fx_take_conc"],
        &[],
        &[
            // The alias is named once, not twice: the blob is what the alias
            // names, so there is no second type to blame.
            "using fx_Concrete, which autocxx replaced with an opaque type:",
            "replaced it with an opaque blob of bytes",
        ],
    );
}

/// The other side of the same rule: a type autocxx was *asked* to treat as
/// opaque keeps its name, so it still crosses the bridge by reference and by
/// pointer even though bindgen describes its innards as nothing but a blob.
/// Refusing bindgen's blobs elsewhere must not cost that.
#[test]
fn test_opaque_type_still_works_by_reference_and_pointer() {
    let hdr = indoc! {"
        #include <cstdint>
        struct fx_Opaque { uint32_t a; uint32_t b; };
        inline const fx_Opaque* fx_the_opaque() {
            static fx_Opaque o{3, 4};
            return &o;
        }
        inline uint32_t fx_read_ref(const fx_Opaque& o) { return o.a; }
        inline uint32_t fx_read_ptr(const fx_Opaque* o) { return o->b; }
    "};
    let rs = quote! {
        let o = unsafe { ffi::fx_the_opaque() };
        assert_eq!(unsafe { ffi::fx_read_ptr(o) }, 4);
        assert_eq!(ffi::fx_read_ref(unsafe { &*o }), 3);
    };
    run_test_ex(
        "",
        hdr,
        rs,
        quote! {
            opaque!("fx_Opaque")
            generate!("fx_Opaque")
            generate!("fx_the_opaque")
            generate!("fx_read_ref")
            generate!("fx_read_ptr")
        },
        None,
        None,
        None,
    );
}

/// Opacity says nothing about ownership: C++ can still hand one of these over
/// in a `std::unique_ptr`, and the signature autocxx generates says so, so the
/// smart pointer has to work rather than naming a type cxx never learned to
/// hold.
#[test]
fn test_opaque_type_works_in_a_unique_ptr() {
    let hdr = indoc! {"
        #include <cstdint>
        #include <memory>
        struct fx_Opaque { uint32_t a; };
        inline std::unique_ptr<fx_Opaque> fx_make_opaque() {
            return std::unique_ptr<fx_Opaque>(new fx_Opaque{7});
        }
        inline uint32_t fx_read_opaque(const fx_Opaque& o) { return o.a; }
    "};
    let rs = quote! {
        let o = ffi::fx_make_opaque();
        assert_eq!(ffi::fx_read_opaque(o.as_ref().unwrap()), 7);
    };
    run_test_ex(
        "",
        hdr,
        rs,
        quote! {
            opaque!("fx_Opaque")
            generate!("fx_Opaque")
            generate!("fx_make_opaque")
            generate!("fx_read_opaque")
        },
        None,
        None,
        None,
    );
}

/// The other half of the same rule: presuming an opaque type is destructible
/// is a presumption, and C++ gets to overrule it. A `private` destructor
/// survives opacity - it is a declaration, not a member - so a type declared
/// opaque may still be one nobody outside it can destroy, and none of the
/// ownership machinery may be generated for it.
#[test]
fn test_opaque_type_with_inaccessible_destructor_is_not_owned() {
    let hdr = indoc! {"
        #include <cstdint>
        class fx_Undestroyable {
        public:
            fx_Undestroyable() {}
            uint32_t get() const { return 42; }
        private:
            ~fx_Undestroyable() {}
        };
        inline fx_Undestroyable* fx_get_undestroyable() {
            static fx_Undestroyable* p = new fx_Undestroyable();
            return p;
        }
    "};
    let directives = quote! {
        opaque!("fx_Undestroyable")
        generate!("fx_Undestroyable")
        generate!("fx_get_undestroyable")
    };
    // Borrowing one still works, and the generated C++ contains neither half
    // of the allocate/free pair, whose free side would `operator delete` one
    // without ever running `~fx_Undestroyable()`.
    run_test_ex(
        "",
        hdr,
        quote! {
            let a = unsafe { &*ffi::fx_get_undestroyable() };
            assert_eq!(a.get(), 42);
        },
        directives.clone(),
        None,
        Some(Box::new(CppMatcher::new(
            &[],
            &["_autocxx_alloc", "_autocxx_free"],
        ))),
        None,
    );
    // Owning one does not.
    run_test_expect_fail_ex(
        "",
        hdr,
        quote! {
            let _ = ffi::fx_Undestroyable::new().within_unique_ptr();
        },
        directives,
        None,
        None,
        None,
    );
}

/// Every generated type used to get an `impl Drop` calling a C++ destructor,
/// including types whose destructor does nothing at all. For a type Rust holds
/// by value that is not free: a type which implements `Drop` may not have a
/// field moved out of it, may not be built with `..other` update syntax, and
/// may never be `Copy`. C++ elides the call to a trivial destructor, and so
/// should we.
#[test]
fn test_trivially_destructible_pod_has_no_drop_impl() {
    let hdr = indoc! {"
        #include <cstdint>
        struct fx_Inner { uint32_t a; };
        struct fx_Outer { fx_Inner inner; uint32_t b; };
    "};
    let rs = quote! {
        let outer = ffi::fx_Outer {
            inner: ffi::fx_Inner { a: 3 },
            b: 4,
        };
        // Update syntax, then moving a field out. Both are refused with E0509
        // on a type which implements `Drop`.
        let updated = ffi::fx_Outer { b: 7, ..outer };
        let inner = updated.inner;
        assert_eq!(inner.a, 3);
    };
    run_test_ex(
        "",
        hdr,
        rs,
        directives_from_lists(&[], &["fx_Inner", "fx_Outer"], None),
        None,
        Some(make_string_absence_finder(vec![
            "impl Drop for output :: fx_Outer".to_string(),
            "impl Drop for output :: fx_Inner".to_string(),
        ])),
        None,
    );
}

/// The other half of that rule. A class which declares no destructor of its
/// own still has a non-trivial one if any of its fields does, and C++ really
/// does call it, so the `impl Drop` has to stay.
///
/// autocxx would never let this program run: `generate_pod!` emits a
/// `static_assert(::rust::IsRelocatable<T>::value)` - see
/// `codegen_cpp::generate_pod_assertion`, which exists for exactly this
/// hazard - and a field with a destructor fails it. That assertion is what
/// makes leaving the `Drop` impl out of a POD safe in the first place, since
/// C++ has already promised the destructor does nothing. This test is the
/// belt to that pair of braces: it pins the analysis rather than the program,
/// so it inspects the generated code and stops before the C++ compiler.
#[test]
fn test_pod_whose_field_has_a_destructor_keeps_drop_impl() {
    struct FindDropImpl;
    impl CodeCheckerFns for FindDropImpl {
        fn check_rust(&self, rs: syn::File) -> Result<(), TestError> {
            if quote::quote!(#rs)
                .to_string()
                .contains("impl Drop for output :: fx_HoldsNoisy")
            {
                Ok(())
            } else {
                Err(TestError::RsCodeExaminationFail(
                    "fx_HoldsNoisy lost its Drop impl".into(),
                ))
            }
        }
        fn skip_build(&self) -> bool {
            true
        }
    }
    let hdr = indoc! {"
        #include <cstdint>
        inline uint32_t& fx_dtor_count() { static uint32_t n = 0; return n; }
        struct fx_Noisy { uint32_t a; ~fx_Noisy() { fx_dtor_count()++; } };
        struct fx_HoldsNoisy { fx_Noisy inner; };
    "};
    run_test_ex(
        "",
        hdr,
        quote! {},
        directives_from_lists(&[], &["fx_HoldsNoisy"], None),
        None,
        Some(Box::new(FindDropImpl)),
        None,
    );
}

/// The analysis above used to have a blind spot here: bindgen emitted no field
/// for an *empty* base class, so a class deriving from one which has a
/// destructor looked trivially destructible, and autocxx left the `Drop` impl
/// out and never ran that destructor. Its own
/// `std::is_trivially_destructible` assertion existed to catch that.
///
/// The base is reported now, so the destructor is kept and that assertion is
/// no longer written. What the generated C++ says instead is cxx's
/// `IsRelocatable`, which for a type nobody has claimed the trait for by hand
/// asks for trivial move construction and trivial destruction - the accurate
/// complaint about this header. autocxx's assertion stays as the backstop for
/// the case it still cannot see: a field whose type bindgen replaced with a
/// blob of bytes.
///
/// The build is not attempted, because that C++ is meant not to compile; what
/// autocxx wrote is the whole answer.
#[test]
fn test_pod_whose_empty_base_has_a_destructor_says_why() {
    let hdr = indoc! {"
        #include <cstdint>
        inline uint32_t& fx_dtor_count() { static uint32_t n = 0; return n; }
        struct fx_EmptyNoisy { ~fx_EmptyNoisy() { fx_dtor_count()++; } };
        struct fx_DerivedPod : public fx_EmptyNoisy { uint32_t x; };
    "};
    run_test_ex(
        "",
        hdr,
        quote! {},
        directives_from_lists(&[], &["fx_DerivedPod"], None),
        None,
        Some(make_checks_without_building(vec![Box::new(
            CppMatcher::new(
                &["::rust::IsRelocatable<fx_DerivedPod>::value"],
                &["autocxx generated no destructor call for fx_DerivedPod"],
            ),
        )])),
        None,
    );
}

/// The other half: a non-POD class deriving from an empty base with a
/// destructor keeps its `Drop`, and that destructor runs.
#[test]
fn test_destructor_of_empty_base_runs() {
    let hdr = indoc! {"
        #include <cstdint>
        inline uint32_t& fx_dtor_count2() { static uint32_t n = 0; return n; }
        struct fx_EmptyNoisy2 { ~fx_EmptyNoisy2() { fx_dtor_count2()++; } };
        struct fx_DerivedNonPod : public fx_EmptyNoisy2 { uint32_t x; };
        inline uint32_t fx_read_dtor_count2() { return fx_dtor_count2(); }
    "};
    run_test(
        "",
        hdr,
        quote! {
            assert_eq!(ffi::fx_read_dtor_count2(), 0);
            {
                let _d = ffi::fx_DerivedNonPod::new().within_unique_ptr();
            }
            assert_eq!(ffi::fx_read_dtor_count2(), 1);
        },
        &["fx_read_dtor_count2", "fx_DerivedNonPod"],
        &[],
    );
}

/// A non-POD type keeps its `impl Drop` whether or not its destructor does
/// anything: it is only ever reached through a pointer or a smart pointer,
/// where implementing `Drop` costs nothing, and `moveit!` on the stack wants
/// something to call.
#[test]
fn test_trivially_destructible_non_pod_keeps_drop_impl() {
    let hdr = indoc! {"
        #include <cstdint>
        class fx_Plain {
        public:
            fx_Plain() {}
            uint32_t get() const { return a; }
        private:
            uint32_t a = 1;
        };
    "};
    run_test_ex(
        "",
        hdr,
        quote! {
            let p = ffi::fx_Plain::new().within_unique_ptr();
            assert_eq!(p.get(), 1);
        },
        directives_from_lists(&["fx_Plain"], &[], None),
        None,
        Some(make_string_finder(vec![
            "impl Drop for output :: fx_Plain".to_string()
        ])),
        None,
    );
}

/// A `std::vector<int>` reached by reference and read element by element.
/// `int` is not one of the widths cxx knows natively, so this only works
/// because the `autocxx` crate declares the `std::vector` glue for the
/// `autocxx::c_*` newtypes on every bridge's behalf. See google/autocxx#422.
#[test]
fn test_c_int_vector_by_reference() {
    let hdr = indoc! {"
        #include <vector>
        class fx_Holder {
        public:
            fx_Holder() : v{1, 2, 3} {}
            const std::vector<int>& ints() const { return v; }
        private:
            std::vector<int> v;
        };
    "};
    let rs = quote! {
        let h = ffi::fx_Holder::new().within_unique_ptr();
        let v = h.ints();
        assert_eq!(v.len(), 3);
        let total: i32 = v.iter().map(|i| i.0).sum();
        assert_eq!(total, 6);
    };
    run_test("", hdr, rs, &["fx_Holder"], &[]);
}

/// The same for the other variable-width C integers, which reach cxx through
/// the same mechanism.
#[test]
fn test_c_long_and_c_ushort_vectors() {
    let hdr = indoc! {"
        #include <vector>
        inline std::vector<long> fx_give_longs() { return std::vector<long> {1, 2}; }
        inline std::vector<unsigned short> fx_give_ushorts() {
            return std::vector<unsigned short> {3, 4};
        }
    "};
    let rs = quote! {
        assert_eq!(
            ffi::fx_give_longs().as_ref().unwrap().as_slice(),
            &[autocxx::c_long(1), autocxx::c_long(2)]
        );
        assert_eq!(
            ffi::fx_give_ushorts().as_ref().unwrap().as_slice(),
            &[autocxx::c_ushort(3), autocxx::c_ushort(4)]
        );
    };
    run_test("", hdr, rs, &["fx_give_longs", "fx_give_ushorts"], &[]);
}

/// The C++ used by the two `extern_cpp_type!`-with-a-nested-type tests below.
const NESTED_EXTERN_TYPE_HDR: &str = indoc! {"
    #include <cstdint>
    namespace fx_ns {
        struct fx_outer {
            enum fx_inner { A, B };
        };
        inline uint32_t fx_take(fx_outer::fx_inner i) {
            return i == fx_outer::B ? 7 : 1;
        }
    }
"};

/// `extern_cpp_type!` naming a nested type the way C++ spells it. bindgen
/// flattens the nesting to `fx_outer_fx_inner`, and nobody writing the
/// directive would know that, so the C++ spelling has to work.
/// See google/autocxx#1422.
#[test]
fn test_extern_cpp_type_nested() {
    let hexathorpe = Token![#](Span::call_site());
    let rs = quote! {
        pub mod base {
            autocxx::include_cpp! {
                #hexathorpe include "input.h"
                name!(ffi_base)
                safety!(unsafe_ffi)
                generate!("fx_ns::fx_outer")
                generate!("fx_ns::fx_outer::fx_inner")
            }
            pub use ffi_base::*;
        }
        pub mod dependent {
            autocxx::include_cpp! {
                #hexathorpe include "input.h"
                name!(ffi_dep)
                safety!(unsafe_ffi)
                generate!("fx_ns::fx_take")
                extern_cpp_type!("fx_ns::fx_outer::fx_inner", crate::base::fx_ns::fx_outer_fx_inner)
                pod!("fx_ns::fx_outer::fx_inner")
            }
            pub use ffi_dep::*;
        }
        fn main() {
            assert_eq!(
                crate::dependent::fx_ns::fx_take(crate::base::fx_ns::fx_outer_fx_inner::B),
                7
            );
        }
    };
    do_run_test_manual("", NESTED_EXTERN_TYPE_HDR, rs, None, None).unwrap();
}

/// The same, written with bindgen's flattened spelling. That names the same
/// type, so it must work too - and must still generate C++ which says
/// `fx_ns::fx_outer::fx_inner`, the only spelling C++ will accept.
#[test]
fn test_extern_cpp_type_nested_flattened_spelling() {
    let hexathorpe = Token![#](Span::call_site());
    let rs = quote! {
        pub mod base {
            autocxx::include_cpp! {
                #hexathorpe include "input.h"
                name!(ffi_base)
                safety!(unsafe_ffi)
                generate!("fx_ns::fx_outer")
                generate!("fx_ns::fx_outer::fx_inner")
            }
            pub use ffi_base::*;
        }
        pub mod dependent {
            autocxx::include_cpp! {
                #hexathorpe include "input.h"
                name!(ffi_dep)
                safety!(unsafe_ffi)
                generate!("fx_ns::fx_take")
                extern_cpp_type!("fx_ns::fx_outer_fx_inner", crate::base::fx_ns::fx_outer_fx_inner)
                pod!("fx_ns::fx_outer_fx_inner")
            }
            pub use ffi_dep::*;
        }
        fn main() {
            assert_eq!(
                crate::dependent::fx_ns::fx_take(crate::base::fx_ns::fx_outer_fx_inner::B),
                7
            );
        }
    };
    do_run_test_manual("", NESTED_EXTERN_TYPE_HDR, rs, None, None).unwrap();
}

/// `generate!` naming a nested type the way C++ spells it, rather than by the
/// `Outer_Inner` bindgen flattened it to. See google/autocxx#1422.
#[test]
fn test_generate_nested_type_by_cpp_name() {
    run_test_ex(
        "",
        NESTED_EXTERN_TYPE_HDR,
        quote! {},
        quote! {
            generate!("fx_ns::fx_outer")
            generate!("fx_ns::fx_outer::fx_inner")
        },
        None,
        None,
        None,
    );
}

/// The flattened spelling names the same type, so it has to keep working.
#[test]
fn test_generate_nested_type_by_flattened_name() {
    run_test_ex(
        "",
        NESTED_EXTERN_TYPE_HDR,
        quote! {},
        quote! {
            generate!("fx_ns::fx_outer")
            generate!("fx_ns::fx_outer_fx_inner")
        },
        None,
        None,
        None,
    );
}

/// A generated C++ wrapper hands a POD parameter over with the move-or-copy
/// helper rather than bare, because the Rust side owns that value and destroys
/// it after the call. A type which opts into relocatability by declaring its
/// own move constructor has no copy constructor left, so passing it bare did
/// not compile at all once wrapper generation was forced.
/// See google/autocxx#1252.
#[test]
fn test_wrapper_moves_pod_argument() {
    let cxx = indoc! {"
        uint32_t fx_take_bob(fx_Bob a) {
            return a.a;
        }
    "};
    let hdr = indoc! {"
        #include <cstdint>
        #include <type_traits>
        struct fx_Bob {
            uint32_t a;
            uint32_t b;
            inline fx_Bob() {}
            inline ~fx_Bob() {}
            inline fx_Bob(fx_Bob&& other) { a = other.a; b = other.b; }
            using IsRelocatable = std::true_type;
        };
        uint32_t fx_take_bob(fx_Bob a);
    "};
    let rs = quote! {
        let a = ffi::fx_Bob { a: 12, b: 13 };
        assert_eq!(ffi::fx_take_bob(a), 12);
    };
    run_test_ex(
        cxx,
        hdr,
        rs,
        directives_from_lists(&["fx_take_bob"], &["fx_Bob"], None),
        Some(Box::new(ForceWrapperGeneration)),
        Some(Box::new(CppMatcher::new(
            &["::autocxx_move_or_copy(arg0)"],
            &["fx_take_bob(arg0)"],
        ))),
        None,
    );
}

/// A virtual method taking a `std::vector` of a forward-declared type is
/// skipped, with the reason recorded where the user will see it, and the rest
/// of the class stays usable.
///
/// cxx would otherwise instantiate `std::vector<T>::size()` for an incomplete
/// `T`, which is a C++ error deep inside the standard library rather than
/// anything the user could act on. See google/autocxx#692.
#[test]
fn test_vector_of_forward_declaration_in_virtual_method() {
    let hdr = indoc! {"
        #include <vector>
        #include <cstdint>
        struct fx_Fwd;
        class fx_Obs {
        public:
            virtual void notify(const std::vector<fx_Fwd>& details) { (void)details; }
            virtual uint32_t ok() const { return 42; }
            virtual ~fx_Obs() {}
        };
    "};
    let rs = quote! {
        let o = ffi::fx_Obs::new().within_unique_ptr();
        assert_eq!(o.ok(), 42);
    };
    run_test_ex(
        "",
        hdr,
        rs,
        directives_from_lists(&["fx_Obs"], &[], None),
        None,
        // Both halves matter: that the method is replaced by a stub, and that
        // the reason recorded against it names the type which caused it.
        Some(make_string_finder(vec![
            "fn notify (_uhoh : autocxx :: BindingGenerationFailure)".to_string(),
            "forward declaration (fx_Fwd)".to_string(),
        ])),
        None,
    );
}

/// A function returning a reference to a `concrete!` template instantiation.
/// The lifetime of the returned reference is elided from the single reference
/// parameter, exactly as it is for any other type; google/autocxx#1370 reports
/// that this fails to compile with "missing lifetime specifier".
///
/// Generating and building is the whole test: a `concrete!` type is opaque, so
/// there is nothing to read off the returned reference at run time.
#[test]
fn test_concrete_template_reference_return() {
    let hdr = indoc! {"
        #include <cstdint>
        template <typename T> class fx_Inner {
        public:
            T held;
            uint32_t v = 4;
        };
        class fx_Held { public: uint32_t a = 1; };
        class fx_Outer { public: fx_Inner<fx_Held> data; };
        inline fx_Inner<fx_Held>& fx_get_inner(fx_Outer& outer) { return outer.data; }
    "};
    run_test_ex(
        "",
        hdr,
        quote! {},
        quote! {
            generate!("fx_Outer")
            generate!("fx_Held")
            concrete!("fx_Inner<fx_Held>", fx_Inner_fx_Held)
            generate!("fx_get_inner")
        },
        None,
        None,
        None,
    );
}

/// The mirror of [`test_concrete_template_reference_return`]: a `concrete!`
/// template instantiation as the reference *parameter*, with a reference to a
/// built-in type coming back. That is the shape cxx once wanted an explicit
/// lifetime for - a reference to an extern type in, a reference to something
/// else out - which `add_explicit_lifetime_if_necessary` calls the cxx#1024
/// case and decides by asking which types are non-POD.
///
/// Whether a `concrete!` type counts as non-POD flips that decision here and
/// in the test above, in opposite directions. Both spellings build, so this
/// pair pins that the answer does not matter: a function may return a
/// reference only if it takes exactly one, so Rust elides the same lifetime
/// the workaround writes out.
#[test]
fn test_concrete_template_reference_parameter() {
    let hdr = indoc! {"
        #include <cstdint>
        template <typename T> class fx_Cell {
        public:
            T held;
            uint32_t v = 4;
        };
        class fx_Payload { public: uint32_t a = 1; };
        inline const uint32_t& fx_peek(const fx_Cell<fx_Payload>& c) { return c.v; }
    "};
    run_test_ex(
        "",
        hdr,
        quote! {},
        quote! {
            generate!("fx_Payload")
            concrete!("fx_Cell<fx_Payload>", fx_Cell_fx_Payload)
            generate!("fx_peek")
        },
        None,
        None,
        None,
    );
}

/// C++ `[[deprecated]]` declarations, bound and never named from Rust.
///
/// Both halves of the generated C++ used to name each function - autocxx's own
/// wrapper in `autocxxgen_ffi.h` and cxx's shim in `gen0.cxx` - so both drew
/// `-Wdeprecated-declarations`, which this harness compiles with `-Werror`.
/// The warning fired whether or not any Rust code called the function, because
/// the wrapper is emitted for everything `generate!` names, so a project
/// building with `-Werror` could not bind a deprecated function at all.
///
/// bindgen now reports the marker, which buys two things. The function is
/// routed through an autocxx wrapper, so cxx's shim names only that wrapper;
/// and the wrapper is bracketed by a pragma silencing the warning for its own
/// body alone. `#![deny(deprecated)]` pins the other side of the same claim:
/// the marker moves to Rust as `#[deprecated]`, and nothing autocxx generates
/// names the marked binding, so a caller who never asks for the function hears
/// nothing from either language.
///
/// Addresses the bug reported upstream as google/autocxx#1403.
#[test]
fn test_deprecated_cpp_function() {
    let hdr = indoc! {"
        #include <cstdint>
        class fx_Dep {
        public:
            [[deprecated(\"use bar instead\")]] virtual uint32_t foo() { return 1; }
            virtual ~fx_Dep() {}
        };
        [[deprecated(\"gone soon\")]] inline uint32_t fx_old_fn() { return 2; }
        [[deprecated]] inline uint32_t fx_old_bare_fn() { return 3; }
    "};
    do_run_test(
        "",
        hdr,
        quote! {},
        directives_from_lists(&["fx_Dep", "fx_old_fn", "fx_old_bare_fn"], &[], None),
        None,
        None,
        None,
        "unsafe_ffi",
        Some(quote! {
            #![deny(deprecated)]
        }),
    )
    .unwrap()
}

/// The message a C++ `[[deprecated]]` was written with has to reach the Rust
/// caller, because that caller is the only person who can act on it: the
/// generated C++ is nobody's to edit. `[[deprecated]]` with no message has to
/// arrive as a bare `#[deprecated]` rather than as an empty note.
///
/// Addresses the bug reported upstream as google/autocxx#1403.
#[test]
fn test_deprecated_cpp_function_warns_its_rust_caller() {
    let hdr = indoc! {"
        #include <cstdint>
        [[deprecated(\"gone soon\")]] inline uint32_t fx_old_fn() { return 2; }
        [[deprecated]] inline uint32_t fx_old_bare_fn() { return 3; }
    "};
    let rs = quote! {
        #[deny(deprecated)]
        fn calls_them() {
            assert_eq!(ffi::fx_old_fn(), 2);
            assert_eq!(ffi::fx_old_bare_fn(), 3);
        }
        calls_them();
    };
    run_test_expect_fail_with_errors(
        "",
        hdr,
        rs,
        &["fx_old_fn", "fx_old_bare_fn"],
        &[],
        &[
            "use of deprecated function `ffi::fx_old_fn`: gone soon",
            "use of deprecated function `ffi::fx_old_bare_fn`",
        ],
    );
}

/// The same for a method, which reaches Rust as an inherent impl item rather
/// than as a free function and so takes its `#[deprecated]` from a different
/// generator.
///
/// Addresses the bug reported upstream as google/autocxx#1403.
#[test]
fn test_deprecated_cpp_method_warns_its_rust_caller() {
    let hdr = indoc! {"
        #include <cstdint>
        class fx_Dep {
        public:
            fx_Dep() {}
            [[deprecated(\"use bar instead\")]] uint32_t foo() const { return 1; }
        };
    "};
    let rs = quote! {
        #[deny(deprecated)]
        fn calls_it() {
            let d = ffi::fx_Dep::new().within_unique_ptr();
            assert_eq!(d.foo(), 1);
        }
        calls_it();
    };
    run_test_expect_fail_with_error(
        "",
        hdr,
        rs,
        &["fx_Dep"],
        &[],
        "use of deprecated method `ffi::fx_Dep::foo`: use bar instead",
    );
}

/// `generate!` naming a nested *class* the way C++ spells it, where that class
/// has a constructor and a method. The methods are what the enum-only test
/// above cannot cover: they are allowlisted through a different code path.
#[test]
fn test_generate_nested_class_with_methods_by_cpp_name() {
    let hdr = indoc! {"
        #include <cstdint>
        namespace fx_ns {
            struct fx_outer {
                class fx_inner {
                public:
                    fx_inner(uint32_t a) : a_(a) {}
                    uint32_t get() const { return a_; }
                private:
                    uint32_t a_;
                };
            };
        }
    "};
    let rs = quote! {
        let i = ffi::fx_ns::fx_outer_fx_inner::new(3).within_unique_ptr();
        assert_eq!(i.get(), 3);
    };
    run_test_ex(
        "",
        hdr,
        rs,
        quote! {
            generate!("fx_ns::fx_outer")
            generate!("fx_ns::fx_outer::fx_inner")
        },
        None,
        None,
        None,
    );
}

/// The same nested class by its flattened spelling, which names the same type
/// and so must keep working.
#[test]
fn test_generate_nested_class_with_methods_by_flattened_name() {
    let hdr = indoc! {"
        #include <cstdint>
        namespace fx_ns {
            struct fx_outer {
                class fx_inner {
                public:
                    fx_inner(uint32_t a) : a_(a) {}
                    uint32_t get() const { return a_; }
                private:
                    uint32_t a_;
                };
            };
        }
    "};
    let rs = quote! {
        let i = ffi::fx_ns::fx_outer_fx_inner::new(3).within_unique_ptr();
        assert_eq!(i.get(), 3);
    };
    run_test_ex(
        "",
        hdr,
        rs,
        quote! {
            generate!("fx_ns::fx_outer")
            generate!("fx_ns::fx_outer_fx_inner")
        },
        None,
        None,
        None,
    );
}

/// A reference return whose lifetime can't be elided from any parameter is
/// declined with a diagnostic, rather than emitted for rustc to reject with
/// "missing lifetime specifier". This is the guard which keeps
/// google/autocxx#1370 from arising: with no reference parameter there is
/// nothing for the returned reference to borrow from.
#[test]
fn test_reference_return_with_no_reference_parameter_declined() {
    let hdr = indoc! {"
        template <typename T> class fx_Inner1 { public: T held; };
        class fx_Held1 { public: int a = 1; };
        inline fx_Inner1<fx_Held1>& fx_get_global1() {
            static fx_Inner1<fx_Held1> b;
            return b;
        }
    "};
    run_test_expect_fail_with_error_ex(
        "",
        hdr,
        quote! {},
        quote! {
            generate!("fx_Held1")
            concrete!("fx_Inner1<fx_Held1>", fx_Inner1_fx_Held1)
            generate!("fx_get_global1")
        },
        "NoMutableInputReference",
    );
}

/// The same when there is more than one candidate: which one the returned
/// reference borrows from is ambiguous, so we decline that too.
#[test]
fn test_reference_return_with_several_reference_parameters_declined() {
    let hdr = indoc! {"
        template <typename T> class fx_Inner2 { public: T held; };
        class fx_Held2 { public: int a = 1; };
        class fx_Outer2 { public: fx_Inner2<fx_Held2> data; };
        class fx_Other2 { public: int b = 2; };
        inline fx_Inner2<fx_Held2>& fx_get_inner2(fx_Outer2& outer, fx_Other2& other) {
            (void)other;
            return outer.data;
        }
    "};
    run_test_expect_fail_with_error_ex(
        "",
        hdr,
        quote! {},
        quote! {
            generate!("fx_Outer2")
            generate!("fx_Held2")
            generate!("fx_Other2")
            concrete!("fx_Inner2<fx_Held2>", fx_Inner2_fx_Held2)
            generate!("fx_get_inner2")
        },
        "MultipleMutableInputReferences",
    );
}

/// A struct holding a C function pointer is trivially copyable, so it can be
/// held by value in Rust. bindgen renders the field as
/// `Option<unsafe extern "C" fn()>`. See google/autocxx#1494.
#[test]
fn test_pod_with_function_pointer_field() {
    let hdr = indoc! {"
        #include <cstdint>
        struct fx_callbacks {
            uint32_t (*fx_get)(uint32_t);
        };
        inline uint32_t fx_double(uint32_t a) { return a * 2; }
        inline fx_callbacks fx_make_callbacks() { return fx_callbacks { fx_double }; }
    "};
    let rs = quote! {
        let cb = ffi::fx_make_callbacks();
        assert_eq!(unsafe { cb.fx_get.unwrap()(21) }, 42);
    };
    run_test("", hdr, rs, &["fx_make_callbacks"], &["fx_callbacks"]);
}

/// The same, where the function pointer type reaches the field through a
/// typedef. See google/autocxx#1494.
#[test]
fn test_pod_with_typedefed_function_pointer_field() {
    let hdr = indoc! {"
        #include <cstdint>
        typedef uint32_t (*fx_get_t)(uint32_t);
        struct fx_callbacks2 {
            fx_get_t fx_get;
        };
        inline uint32_t fx_treble(uint32_t a) { return a * 3; }
        inline fx_callbacks2 fx_make_callbacks2() { return fx_callbacks2 { fx_treble }; }
    "};
    let rs = quote! {
        let cb = ffi::fx_make_callbacks2();
        assert_eq!(unsafe { cb.fx_get.unwrap()(14) }, 42);
    };
    run_test("", hdr, rs, &["fx_make_callbacks2"], &["fx_callbacks2"]);
}

/// A null function pointer, which is the whole reason bindgen wraps the field
/// in an `Option`, has to survive the crossing in both directions: C++ writing
/// `nullptr` must reach Rust as `None`, and Rust writing `None` must reach C++
/// as a null pointer. Nothing converts the field - the struct is copied whole -
/// so this is the layout guarantee that `Option<fn>` is the pointer itself,
/// with `None` as its null, being taken at its word. See google/autocxx#1494.
#[test]
fn test_pod_with_null_function_pointer_field() {
    let hdr = indoc! {"
        #include <cstdint>
        struct fx_callbacks3 {
            uint32_t (*fx_get)(uint32_t);
        };
        inline fx_callbacks3 fx_make_null_callbacks() { return fx_callbacks3 { nullptr }; }
        inline bool fx_callbacks_are_null(fx_callbacks3 cb) { return cb.fx_get == nullptr; }
    "};
    let rs = quote! {
        assert!(ffi::fx_make_null_callbacks().fx_get.is_none());
        assert!(ffi::fx_callbacks_are_null(ffi::fx_callbacks3 { fx_get: None }));
    };
    run_test(
        "",
        hdr,
        rs,
        &["fx_make_null_callbacks", "fx_callbacks_are_null"],
        &["fx_callbacks3"],
    );
}

/// The other direction for a pointer which is not null: Rust puts one of its
/// own functions in the field and C++ calls it. That is the end-to-end proof
/// that the field really is the C function pointer it claims to be, rather
/// than something which merely happens to read back the same in Rust.
/// See google/autocxx#1494.
#[test]
fn test_pod_function_pointer_field_written_from_rust() {
    let hdr = indoc! {"
        #include <cstdint>
        struct fx_callbacks4 {
            uint32_t (*fx_get)(uint32_t);
        };
        inline uint32_t fx_call_callbacks(fx_callbacks4 cb, uint32_t arg) {
            return cb.fx_get ? cb.fx_get(arg) : 0;
        }
    "};
    let rs = quote! {
        unsafe extern "C" fn fx_written_in_rust(a: u32) -> u32 {
            a * 7
        }
        let cb = ffi::fx_callbacks4 { fx_get: Some(fx_written_in_rust) };
        assert_eq!(ffi::fx_call_callbacks(cb, 6), 42);
        // And the null case again from this side, since C++ is the one
        // dereferencing it here.
        assert_eq!(ffi::fx_call_callbacks(ffi::fx_callbacks4 { fx_get: None }, 6), 0);
    };
    run_test("", hdr, rs, &["fx_call_callbacks"], &["fx_callbacks4"]);
}

/// A function pointer in a *signature* is a different matter: that type has to
/// go into the `cxx::bridge`, and cxx has no function pointer type. So it stays
/// refused - and the complaint says "function pointer" and points at the
/// documented way to have C++ call into Rust, rather than naming
/// `std::option::Option`, which is bindgen's Rust spelling of it and appears
/// nowhere in the user's C++. See google/autocxx#1494.
#[test]
fn test_function_pointer_parameter_still_refused() {
    let hdr = indoc! {"
        #include <cstdint>
        inline uint32_t fx_call_it(uint32_t (*fx_f)(uint32_t)) { return fx_f(1); }
    "};
    run_test_expect_fail_with_errors(
        "",
        hdr,
        quote! {},
        &["fx_call_it"],
        &[],
        &[
            "FunctionPointerInSignature",
            "A function pointer appears in this signature",
            "rust_calls.html",
        ],
    );
}

/// A function pointer *returned*, which reaches the type converter by a
/// different route from a parameter, and gets the same explanation.
#[test]
fn test_function_pointer_return_refused() {
    let hdr = indoc! {"
        #include <cstdint>
        typedef uint32_t (*fx_getter)(uint32_t);
        inline fx_getter fx_which_one(bool) { return nullptr; }
    "};
    run_test_expect_fail_with_errors(
        "",
        hdr,
        quote! {},
        &["fx_which_one"],
        &[],
        &[
            "FunctionPointerInSignature",
            "A function pointer appears in this signature",
        ],
    );
}

/// The same through a typedef, which is how C++ usually spells a callback
/// parameter. The typedef itself is kept (a struct field may hold one), so the
/// refusal has to happen where it is used rather than where it is declared.
#[test]
fn test_function_pointer_typedef_parameter_refused() {
    let hdr = indoc! {"
        #include <cstdint>
        typedef uint32_t (*fx_cb)(uint32_t);
        inline uint32_t fx_call_cb(fx_cb f) { return f(1); }
    "};
    run_test_expect_fail_with_errors(
        "",
        hdr,
        quote! {},
        &["fx_call_cb"],
        &[],
        &[
            "FunctionPointerInSignature",
            "A function pointer appears in this signature",
        ],
    );
}

/// The shape google/autocxx#1192 was reported in: a *namespaced* type autocxx
/// cannot make sense of (there, `Eigen::Vector2d`), replaced by a Rust type of
/// the user's own, declared POD, and held by value inside a struct the user
/// asks to be POD. `test_issue_1192` covers the same thing without a
/// namespace; the namespace is what makes the `pod!` name and the
/// `extern_cpp_type!` name have to agree about a type nobody generated.
#[test]
fn test_extern_cpp_type_pod_in_namespace() {
    let hdr = indoc! {"
        #include <cstdint>
        namespace fx_eigen {
            template <typename T, int N> struct fx_Matrix { T data[N]; };
            typedef fx_Matrix<double, 2> fx_Vector2d;
        }
        struct fx_MyStruct {
            fx_eigen::fx_Vector2d vec;
        };
    "};
    run_test_ex(
        "",
        hdr,
        quote! {},
        quote! {
            extern_cpp_type!("fx_eigen::fx_Vector2d", crate::FxVector2d)
            pod!("fx_eigen::fx_Vector2d")
            generate_pod!("fx_MyStruct")
        },
        None,
        None,
        Some(quote! {
            #[repr(transparent)]
            pub struct FxVector2d(pub [f64; 2]);

            unsafe impl cxx::ExternType for FxVector2d {
                type Id = cxx::type_id!("fx_eigen::fx_Vector2d");
                type Kind = cxx::kind::Trivial;
            }
        }),
    );
}

/// The shape of google/autocxx#1363: OpenCV spells `cv::OutputArray` as a
/// typedef whose target is a reference - `typedef const cv::_OutputArray&
/// OutputArray;` - and passes it by value as a parameter. autocxx generated a
/// C++ shim taking `const cv::_OutputArray*` and handed that straight to a
/// function wanting the reference.
#[test]
fn test_typedef_to_const_reference_parameter() {
    let hdr = indoc! {"
        #include <cstdint>
        struct fx_Array { uint32_t a; };
        typedef const fx_Array& fx_ArrayRef;
        inline uint32_t fx_read(fx_ArrayRef arr) { return arr.a; }
    "};
    let rs = quote! {
        let arr = ffi::fx_Array { a: 42 };
        assert_eq!(ffi::fx_read(&arr), 42);
    };
    run_test("", hdr, rs, &["fx_read"], &["fx_Array"]);
}

/// The same as a method taking the typedef, which is how `cv::VideoCapture`
/// reached it - autocxx writes a wrapper for a method, so the wrapper's
/// parameter is the one that has to be spelled right.
#[test]
fn test_typedef_to_const_reference_method_parameter() {
    let hdr = indoc! {"
        #include <cstdint>
        struct fx_Out { uint32_t a; };
        typedef const fx_Out& fx_OutRef;
        class fx_Capture {
        public:
            bool fx_retrieve(fx_OutRef out, int flag) {
                total = out.a + flag;
                return true;
            }
            uint32_t fx_total() const { return total; }
        private:
            uint32_t total = 0;
        };
    "};
    let rs = quote! {
        let out = ffi::fx_Out { a: 40 };
        let mut cap = ffi::fx_Capture::new().within_unique_ptr();
        assert!(cap.pin_mut().fx_retrieve(&out, autocxx::c_int(2)));
        assert_eq!(cap.fx_total(), 42);
    };
    run_test("", hdr, rs, &["fx_Capture"], &["fx_Out"]);
}

/// A reference returned by a function whose only reference input arrives
/// through a typedef. The lifetime elision autocxx does needs to see that the
/// parameter is a reference; through a typedef it did not.
/// See google/autocxx#1302.
#[test]
fn test_typedef_to_const_reference_borrowed_return() {
    let hdr = indoc! {"
        class fx_Bytes {
        public:
            typedef const char& fx_reference;
            fx_reference fx_front() const { return d_ptr[0]; }
        private:
            const char* d_ptr = \"hi\";
        };
    "};
    let rs = quote! {
        let b = ffi::fx_Bytes::new().within_unique_ptr();
        assert_eq!(*b.fx_front(), 'h' as std::os::raw::c_char);
    };
    run_test("", hdr, rs, &["fx_Bytes"], &[]);
}

/// A typedef to a *mutable* reference used as a parameter.
#[test]
fn test_typedef_to_mutable_reference_parameter() {
    let hdr = indoc! {"
        #include <cstdint>
        struct fx_Sink { uint32_t a; };
        typedef fx_Sink& fx_SinkRef;
        inline void fx_fill(fx_SinkRef sink) { sink.a = 42; }
    "};
    let rs = quote! {
        let mut sink = ffi::fx_Sink { a: 0 };
        ffi::fx_fill(std::pin::Pin::new(&mut sink));
        assert_eq!(sink.a, 42);
    };
    run_test("", hdr, rs, &["fx_fill"], &["fx_Sink"]);
}

/// A reference returned by a free function, borrowing from a reference
/// parameter, where both are spelled with a typedef. The lifetime autocxx
/// elides has to come from the parameter, and that means knowing the parameter
/// is a reference even though the type it is written with is a name.
/// See google/autocxx#1363.
#[test]
fn test_typedef_to_const_reference_borrowed_from_parameter() {
    let hdr = indoc! {"
        #include <cstdint>
        struct fx_Cell { uint32_t a; };
        typedef const fx_Cell& fx_CellRef;
        inline fx_CellRef fx_same(fx_CellRef cell) { return cell; }
    "};
    let rs = quote! {
        let cell = ffi::fx_Cell { a: 42 };
        assert_eq!(ffi::fx_same(&cell).a, 42);
    };
    run_test("", hdr, rs, &["fx_same"], &["fx_Cell"]);
}

/// A reference return written out, borrowing from a reference parameter which
/// is spelled with a typedef. autocxx elides the returned reference's lifetime
/// from a reference parameter, and it has to see the parameter for one through
/// the typedef; otherwise there is nothing for the return to borrow from and
/// the function is declined. See google/autocxx#1363.
#[test]
fn test_reference_return_borrowing_from_a_typedefed_reference_parameter() {
    let hdr = indoc! {"
        #include <cstdint>
        struct fx_Cell2 { uint32_t a; };
        typedef const fx_Cell2& fx_Cell2Ref;
        inline const fx_Cell2& fx_same2(fx_Cell2Ref cell) { return cell; }
    "};
    let rs = quote! {
        let cell = ffi::fx_Cell2 { a: 42 };
        assert_eq!(ffi::fx_same2(&cell).a, 42);
    };
    run_test("", hdr, rs, &["fx_same2"], &["fx_Cell2"]);
}

/// `derive!` puts extra traits on the Rust type autocxx generates for a POD
/// C++ one. See google/autocxx#668.
#[test]
fn test_derive_on_pod() {
    let hdr = indoc! {"
        #include <cstdint>
        struct fx_Point { uint32_t x; uint32_t y; };
    "};
    let rs = quote! {
        let a = ffi::fx_Point { x: 1, y: 2 };
        let b = ffi::fx_Point { x: 1, y: 2 };
        assert_eq!(a, b);
        assert_eq!(format!("{:?}", a), "fx_Point { x: 1, y: 2 }");
        let c = a.clone();
        assert_eq!(c.y, 2);
    };
    run_test_ex(
        "",
        hdr,
        rs,
        quote! {
            generate_pod!("fx_Point")
            derive!("fx_Point", "Debug", "PartialEq")
            derive!("fx_Point", "Clone")
        },
        None,
        None,
        None,
    );
}

/// A derive whose fields have to support it: `Clone` on a POD holding another
/// POD works only because the inner one is `Clone` too.
#[test]
fn test_derive_clone_through_a_field() {
    let hdr = indoc! {"
        #include <cstdint>
        struct fx_Inner3 { uint32_t a; };
        struct fx_Outer3 { fx_Inner3 inner; uint32_t b; };
    "};
    let rs = quote! {
        let outer = ffi::fx_Outer3 { inner: ffi::fx_Inner3 { a: 1 }, b: 2 };
        let copy = outer.clone();
        assert_eq!(copy.inner.a, 1);
        assert_eq!(copy.b, 2);
    };
    run_test_ex(
        "",
        hdr,
        rs,
        quote! {
            generate_pod!("fx_Outer3")
            generate_pod!("fx_Inner3")
            derive!("fx_Inner3", "Clone")
            derive!("fx_Outer3", "Clone")
        },
        None,
        None,
        None,
    );
}

/// The same for an enum, where bindgen has already written a derive list of
/// its own. Asking for one of the traits it put there must not produce a
/// second, conflicting implementation.
#[test]
fn test_derive_on_enum() {
    let hdr = indoc! {"
        enum class fx_Colour { Red, Green };
    "};
    let rs = quote! {
        assert_eq!(format!("{:?}", ffi::fx_Colour::Green), "Green");
        assert_eq!(ffi::fx_Colour::Red.clone(), ffi::fx_Colour::Red);
    };
    run_test_ex(
        "",
        hdr,
        rs,
        quote! {
            generate!("fx_Colour")
            derive!("fx_Colour", "Debug", "Clone")
        },
        None,
        None,
        None,
    );
}

/// `derive!` names a type the way every other directive does, so the C++
/// spelling of a nested type has to work as well as the flattened one bindgen
/// gives it.
#[test]
fn test_derive_on_nested_type_by_cpp_name() {
    let hdr = indoc! {"
        #include <cstdint>
        namespace fx_ns4 {
            struct fx_outer4 {
                struct fx_inner4 { uint32_t a; };
            };
        }
    "};
    let rs = quote! {
        let i = ffi::fx_ns4::fx_outer4_fx_inner4 { a: 3 };
        assert_eq!(format!("{:?}", i), "fx_outer4_fx_inner4 { a: 3 }");
    };
    run_test_ex(
        "",
        hdr,
        rs,
        quote! {
            generate_pod!("fx_ns4::fx_outer4::fx_inner4")
            derive!("fx_ns4::fx_outer4::fx_inner4", "Debug")
        },
        None,
        None,
        None,
    );
}

/// A `derive!` for something autocxx never generated is a mistake worth
/// reporting, exactly as an unused `generate!` is.
#[test]
fn test_derive_matching_nothing_refused() {
    let hdr = indoc! {"
        #include <cstdint>
        struct fx_Present { uint32_t a; };
    "};
    run_test_expect_fail_with_error_ex(
        "",
        hdr,
        quote! {},
        quote! {
            generate_pod!("fx_Present")
            derive!("fx_Absent", "Debug")
        },
        "DeriveDirectiveMatchedNothing",
    );
}

/// A non-POD type is re-emitted as an opaque wrapper with no fields, so a
/// derive on the bindgen definition would never reach the user. Say so.
#[test]
fn test_derive_on_non_pod_refused() {
    let hdr = indoc! {"
        #include <string>
        struct fx_Stringy { std::string s; };
    "};
    run_test_expect_fail_with_error_ex(
        "",
        hdr,
        quote! {},
        quote! {
            generate!("fx_Stringy")
            derive!("fx_Stringy", "Debug")
        },
        "DeriveOnTypeWithNoRustDefinition",
    );
}

/// `Default` on an enum is refused rather than emitted: nothing makes one
/// enumerator of a C++ enum the default, which is why bindgen's own `Default`
/// is stripped from every enum, and a derived one would not compile.
#[test]
fn test_derive_default_on_enum_refused() {
    let hdr = indoc! {"
        enum class fx_Shade { Light, Dark };
    "};
    run_test_expect_fail_with_error_ex(
        "",
        hdr,
        quote! {},
        quote! {
            generate!("fx_Shade")
            derive!("fx_Shade", "Default")
        },
        "DeriveDefaultOnEnum",
    );
}

/// A typedef to an rvalue reference, used as a parameter. Both a C++ pointer
/// and a C++ rvalue reference come out of the type converter as a Rust
/// pointer, so the alias looked exactly like `typedef fx_Movable* P` - and
/// autocxx wrote a C++ shim taking `fx_Movable*` and handed it to a function
/// wanting `fx_Movable&&`, which does not compile. See google/autocxx#1363.
#[test]
fn test_typedef_to_rvalue_reference_parameter() {
    let hdr = indoc! {"
        #include <string>
        struct fx_Movable { std::string a; };
        typedef fx_Movable&& fx_MovableRef;
        inline void fx_take(fx_MovableRef) {}
    "};
    let rs = quote! {
        let a = ffi::fx_Movable::new().within_unique_ptr();
        ffi::fx_take(a);

        moveit! { let a2 = ffi::fx_Movable::new() };
        ffi::fx_take(a2);
    };
    run_test("", hdr, rs, &["fx_Movable", "fx_take"], &[]);
}

/// The same through a chain of typedefs, which is the case that decides where
/// the fact has to be kept: the second alias is analysed by resolving the
/// first, so an answer worked out afresh at each point of use would have to be
/// right at every link.
#[test]
fn test_typedef_chain_to_rvalue_reference_parameter() {
    let hdr = indoc! {"
        #include <string>
        struct fx_Movable2 { std::string a; };
        typedef fx_Movable2&& fx_Movable2Ref;
        typedef fx_Movable2Ref fx_Movable2RefAgain;
        inline void fx_take2(fx_Movable2RefAgain) {}
    "};
    let rs = quote! {
        let a = ffi::fx_Movable2::new().within_unique_ptr();
        ffi::fx_take2(a);
    };
    run_test("", hdr, rs, &["fx_Movable2", "fx_take2"], &[]);
}

/// A typedef to an rvalue reference in *return* position, which the refusal
/// of `T&&` returns has to catch as surely as it catches one written out.
/// Written out, the return reaches analysis as one of bindgen's markers and
/// is turned down on sight; behind a typedef it arrives as an ordinary path,
/// and only the type converter - having resolved the alias - knows what it
/// is. Before, that difference got as far as codegen, which emitted a shim
/// whose function pointer had the wrong type and would not compile.
#[test]
fn test_typedef_to_rvalue_reference_return_is_refused() {
    let hdr = indoc! {"
        #include <cstdint>
        struct fx_Handoff { uint32_t a; };
        typedef fx_Handoff&& fx_HandoffRef;
        inline fx_HandoffRef fx_hand_over(fx_Handoff& h) {
            return static_cast<fx_HandoffRef>(h);
        }
    "};
    run_test_expect_fail_with_error(
        "",
        hdr,
        quote! {},
        &["fx_Handoff", "fx_hand_over"],
        &[],
        "returns an rvalue reference",
    );
}

/// And the same typedef on a virtual method, where a subclass peer still has
/// to override it and so still has to spell the `&&` - the refusal above only
/// stops autocxx generating a way for Rust to *call* the superclass method,
/// which was never what made the override possible.
#[test]
fn test_subclass_virtual_returning_typedef_to_rvalue_reference() {
    let hdr = indoc! {"
    #include <cstdint>

    struct fx_Parcel { uint32_t a; };
    typedef fx_Parcel&& fx_ParcelRef;

    class fx_Depot {
    public:
        fx_Depot() {}
        virtual fx_ParcelRef fx_collect() = 0;
        virtual ~fx_Depot() {}
    };

    inline uint32_t fx_fetch(fx_Depot* d) { return d->fx_collect().a; }
    "};
    run_test_ex(
        "",
        hdr,
        quote! {
            let mut parcel = ffi::fx_Parcel { a: 42 };
            let depot = MyDepot::new_rust_owned(MyDepot {
                parcel: &mut parcel,
                cpp_peer: Default::default(),
            });
            let sup: *mut ffi::fx_Depot =
                unsafe { depot.borrow_mut().pin_mut().get_unchecked_mut() };
            assert_eq!(unsafe { ffi::fx_fetch(sup) }, 42);
        },
        quote! {
            generate!("fx_fetch")
            generate_pod!("fx_Parcel")
            subclass!("fx_Depot",MyDepot)
        },
        None,
        None,
        Some(quote! {
            use autocxx::subclass::CppSubclass;
            use ffi::fx_Depot_methods;
            #[autocxx::subclass::subclass]
            pub struct MyDepot {
                parcel: *mut ffi::fx_Parcel,
            }
            impl fx_Depot_methods for MyDepot {
                fn fx_collect(&mut self) -> *mut ffi::fx_Parcel {
                    self.parcel
                }
            }
        }),
    );
}

/// A typedef to a pointer must stay a pointer: the two are told apart by what
/// the typedef's own analysis recorded, and nothing else, so the case which
/// keeps that honest belongs next to the one which needed it.
/// See google/autocxx#1368.
#[test]
fn test_typedef_to_pointer_parameter_is_still_a_pointer() {
    let hdr = indoc! {"
        #include <cstdint>
        struct fx_Held { uint32_t a; };
        typedef fx_Held* fx_HeldPtr;
        inline uint32_t fx_read_ptr(fx_HeldPtr h) { return h->a; }
    "};
    let rs = quote! {
        let mut held = ffi::fx_Held { a: 42 };
        assert_eq!(unsafe { ffi::fx_read_ptr(&mut held) }, 42);
    };
    run_test("", hdr, rs, &["fx_read_ptr"], &["fx_Held"]);
}

/// A method on a class bindgen could not name. bindgen tracks a class
/// template's *type* parameters and not its non-type ones, so for
/// `template <int N> struct S` it has no name to write and substitutes an
/// opaque blob of the right size - while still generating the class's methods,
/// whose receiver is then that blob. There is no receiver to be had from a
/// blob: the Rust type it is spelled with (`u8` here) names no C++ type, so
/// the method has to be refused, and refused saying what went wrong.
#[test]
fn test_method_on_a_type_bindgen_could_not_name_is_refused() {
    let hdr = indoc! {"
        template <int N> struct fx_Sized {
            int x[N];
            int fx_first() const { return x[0]; }
        };
    "};
    run_test_ex(
        "",
        hdr,
        quote! {},
        quote! {
            generate_all!()
        },
        None,
        Some(make_string_finder(vec![
            "fx_first".to_string(),
            "replaced it with an opaque blob of bytes".to_string(),
        ])),
        None,
    );
}

/// The C++ half of the throwing-constructor tests: a class whose constructor
/// throws for one particular argument, with a member whose construction and
/// destruction are counted so that a test can see what C++ did on the way out.
const THROWING_CTOR_CXX: &str = indoc! {"
    static uint32_t member_ctors = 0;
    static uint32_t member_dtors = 0;
    static uint32_t outer_dtors = 0;
    uint32_t fx_member_ctors() { return member_ctors; }
    uint32_t fx_member_dtors() { return member_dtors; }
    uint32_t fx_outer_dtors() { return outer_dtors; }
    void fx_reset_counts() { member_ctors = 0; member_dtors = 0; outer_dtors = 0; }
    fx_Member::fx_Member() { member_ctors++; }
    fx_Member::~fx_Member() { member_dtors++; }
    fx_Risky::fx_Risky(uint32_t x) {
        if (x == 0) throw std::runtime_error(\"fx no zeroes here\");
        a = x;
    }
    fx_Risky::~fx_Risky() { outer_dtors++; }
"};

/// The header for [`THROWING_CTOR_CXX`]. `fx_Risky` is non-POD: it has a
/// user-provided destructor, so autocxx will not treat it as trivial.
const THROWING_CTOR_HDR: &str = indoc! {"
    #include <stdexcept>
    #include <cstdint>
    uint32_t fx_member_ctors();
    uint32_t fx_member_dtors();
    uint32_t fx_outer_dtors();
    void fx_reset_counts();
    struct fx_Member {
        fx_Member();
        ~fx_Member();
    };
    class fx_Risky {
    public:
        fx_Risky(uint32_t x);
        ~fx_Risky();
        uint32_t get() const { return a; }
    private:
        fx_Member m;
        uint32_t a = 0;
    };
"};

/// The directives every throwing-constructor test needs. `fx_Risky::fx_Risky`
/// is how a constructor is named in C++, and how `throws!` wants to hear about
/// one.
fn throwing_ctor_directives() -> TokenStream {
    quote! {
        generate!("fx_Risky")
        generate!("fx_member_ctors")
        generate!("fx_member_dtors")
        generate!("fx_outer_dtors")
        generate!("fx_reset_counts")
        throws!("fx_Risky::fx_Risky")
    }
}

/// The heap path: a constructor which does throw reports the exception rather
/// than terminating the process, and the message survives the crossing.
#[test]
fn test_throwing_ctor_within_unique_ptr_reports_the_exception() {
    let rs = quote! {
        ffi::fx_reset_counts();
        let err = ffi::fx_Risky::new(0)
            .try_within_unique_ptr()
            .err()
            .expect("this constructor throws for 0");
        assert_eq!(err.what(), "fx no zeroes here");
    };
    run_test_ex(
        THROWING_CTOR_CXX,
        THROWING_CTOR_HDR,
        rs,
        throwing_ctor_directives(),
        None,
        None,
        None,
    );
}

/// The same constructor, given an argument it likes, still builds an object.
/// Designating a constructor as throwing does not stop it working.
#[test]
fn test_throwing_ctor_within_unique_ptr_still_constructs() {
    let rs = quote! {
        let obj = ffi::fx_Risky::new(7)
            .try_within_unique_ptr()
            .ok()
            .expect("7 is fine");
        assert_eq!(obj.get(), 7);
    };
    run_test_ex(
        THROWING_CTOR_CXX,
        THROWING_CTOR_HDR,
        rs,
        throwing_ctor_directives(),
        None,
        None,
        None,
    );
}

/// What C++ did on the way out of a failed construction, and what we did not
/// do afterwards. The member had been constructed by the time the exception
/// was thrown, so C++ destroyed it during unwinding; the object itself was
/// never constructed, so its destructor must not run - a second destruction of
/// `fx_Member` would show up here as a count of two.
#[test]
fn test_throwing_ctor_destroys_members_once_and_the_object_never() {
    let rs = quote! {
        ffi::fx_reset_counts();
        assert!(ffi::fx_Risky::new(0).try_within_unique_ptr().is_err());
        assert_eq!(ffi::fx_member_ctors(), 1, "the member was constructed");
        assert_eq!(ffi::fx_member_dtors(), 1, "and destroyed by C++ unwinding, once");
        assert_eq!(ffi::fx_outer_dtors(), 0, "the object never existed, so was never destroyed");

        // And for comparison, the successful path destroys everything exactly
        // once when the UniquePtr goes away.
        ffi::fx_reset_counts();
        let obj = ffi::fx_Risky::new(3).try_within_unique_ptr().ok().unwrap();
        assert_eq!(ffi::fx_member_ctors(), 1);
        assert_eq!(ffi::fx_member_dtors(), 0);
        drop(obj);
        assert_eq!(ffi::fx_member_dtors(), 1);
        assert_eq!(ffi::fx_outer_dtors(), 1);
    };
    run_test_ex(
        THROWING_CTOR_CXX,
        THROWING_CTOR_HDR,
        rs,
        throwing_ctor_directives(),
        None,
        None,
        None,
    );
}

/// The `Box` path, both outcomes. A failed construction frees the box without
/// destroying anything.
#[test]
fn test_throwing_ctor_within_box() {
    let rs = quote! {
        ffi::fx_reset_counts();
        assert!(ffi::fx_Risky::new(0).try_within_box().is_err());
        assert_eq!(ffi::fx_member_dtors(), 1);
        assert_eq!(ffi::fx_outer_dtors(), 0);

        ffi::fx_reset_counts();
        let obj = ffi::fx_Risky::new(11).try_within_box().ok().expect("11 is fine");
        assert_eq!(obj.get(), 11);
        drop(obj);
        assert_eq!(ffi::fx_outer_dtors(), 1);
    };
    run_test_ex(
        THROWING_CTOR_CXX,
        THROWING_CTOR_HDR,
        rs,
        throwing_ctor_directives(),
        None,
        None,
        None,
    );
}

/// The `CppPin` path, both outcomes.
#[test]
fn test_throwing_ctor_within_cpp_pin() {
    let rs = quote! {
        ffi::fx_reset_counts();
        assert!(ffi::fx_Risky::new(0).try_within_cpp_pin().is_err());
        assert_eq!(ffi::fx_outer_dtors(), 0);

        let obj = ffi::fx_Risky::new(5).try_within_cpp_pin().ok().expect("5 is fine");
        // `CppRef`'s own method calls need `cpp_semantics!`, so read the object
        // through the pin's raw pointer instead - all this test needs to know
        // is that the object arrived intact.
        assert_eq!(unsafe { (*obj.as_ptr()).get() }, 5);
    };
    run_test_ex(
        THROWING_CTOR_CXX,
        THROWING_CTOR_HDR,
        rs,
        throwing_ctor_directives(),
        None,
        None,
        None,
    );
}

/// The stack path. `moveit!` cannot express a construction which fails, so a
/// `stack_slot!` reserves the storage and `try_emplace` fills it - or doesn't.
#[test]
fn test_throwing_ctor_on_the_stack() {
    let rs = quote! {
        ffi::fx_reset_counts();
        {
            // Unqualified, to pin that the prelude exports the macro.
            stack_slot!(storage);
            let outcome = storage.try_emplace(ffi::fx_Risky::new(0));
            assert!(outcome.is_err());
        }
        assert_eq!(ffi::fx_member_ctors(), 1);
        assert_eq!(ffi::fx_member_dtors(), 1);
        assert_eq!(ffi::fx_outer_dtors(), 0, "nothing was constructed to destroy");

        ffi::fx_reset_counts();
        {
            autocxx::stack_slot!(storage);
            let obj = storage.try_emplace(ffi::fx_Risky::new(9)).expect("9 is fine");
            assert_eq!(obj.get(), 9);
            assert_eq!(ffi::fx_outer_dtors(), 0, "still alive within its scope");
        }
        assert_eq!(ffi::fx_outer_dtors(), 1, "and destroyed when the scope ended");
    };
    run_test_ex(
        THROWING_CTOR_CXX,
        THROWING_CTOR_HDR,
        rs,
        throwing_ctor_directives(),
        None,
        None,
        None,
    );
}

/// A constructor which is designated as throwing but never does. The Rust
/// surface is fallible whether or not the exception ever happens, which is the
/// point: `throws!` describes what C++ may do, not what it did.
#[test]
fn test_designated_ctor_which_never_throws() {
    let hdr = indoc! {"
        #include <stdexcept>
        #include <cstdint>
        class fx_Calm {
        public:
            fx_Calm(uint32_t x) : a(x) {}
            uint32_t get() const { return a; }
        private:
            uint32_t a;
        };
    "};
    let rs = quote! {
        let obj = ffi::fx_Calm::new(4).try_within_unique_ptr().ok().unwrap();
        assert_eq!(obj.get(), 4);
    };
    run_test_ex(
        "",
        hdr,
        rs,
        quote! {
            generate!("fx_Calm")
            throws!("fx_Calm::fx_Calm")
        },
        None,
        None,
        None,
    );
}

/// A constructor nobody designated keeps the infallible shape it always had.
///
/// The whole generated function is pinned here, not just its return type: the
/// `#[must_use]` message, the signature, and every statement of the body up to
/// the call itself, whose name carries a per-mod hash and so cannot be written
/// down. Nothing about the throwing support reaches an ordinary constructor -
/// no `TryNew`, no `try_by_raw`, no `Result` - and it still runs.
#[test]
fn test_undesignated_ctor_is_unchanged() {
    let hdr = indoc! {"
        #include <cstdint>
        class fx_Ordinary {
        public:
            fx_Ordinary(uint32_t x) : a(x) {}
            uint32_t get() const { return a; }
        private:
            uint32_t a;
        };
    "};
    let rs = quote! {
        let obj = ffi::fx_Ordinary::new(2).within_unique_ptr();
        assert_eq!(obj.get(), 2);
        moveit! { let on_stack = ffi::fx_Ordinary::new(3); }
        assert_eq!(on_stack.get(), 3);
    };
    run_test_ex(
        "",
        hdr,
        rs,
        directives_from_lists(&["fx_Ordinary"], &[], None),
        None,
        Some(make_checks(vec![
            make_string_finder(vec![concat!(
                "# [must_use = \"this is a recipe for constructing a C++ object, and ",
                "constructs nothing until it is stored somewhere: finish it with ",
                ".within_unique_ptr(), .within_box(), or the moveit! macro\"] ",
                "pub fn new (x : u32) -> impl autocxx :: moveit :: new :: New < Output = Self > ",
                "{ unsafe { autocxx :: moveit :: new :: by_raw (move | this | ",
                "{ let this = this . get_unchecked_mut () . as_mut_ptr () ; cxxbridge ::",
            )
            .to_string()]),
            make_string_absence_finder(vec!["TryNew".to_string(), "try_by_raw".to_string()]),
        ])),
        None,
    );
}

/// The shape a designated constructor gets, pinned directly: an `impl TryNew`
/// rather than an `impl New`, and no `Result` wrapped around it. A
/// `Result<impl New, _>` would have to decide whether construction failed
/// before running the constructor, which is not something a C++ exception
/// allows.
#[test]
fn test_designated_ctor_generates_a_try_new() {
    let hdr = indoc! {"
        #include <cstdint>
        class fx_Shape {
        public:
            fx_Shape(uint32_t x) : a(x) {}
        private:
            uint32_t a;
        };
    "};
    run_test_ex(
        "",
        hdr,
        quote! {},
        quote! {
            generate!("fx_Shape")
            throws!("fx_Shape::fx_Shape")
        },
        None,
        Some(make_checks_without_building(vec![
            make_string_finder(vec![
                "impl autocxx :: moveit :: new :: TryNew < Output = Self , Error = cxx :: Exception >"
                    .to_string(),
                "autocxx :: moveit :: new :: try_by_raw".to_string(),
            ]),
            make_string_absence_finder(vec![
                "Result < impl autocxx :: moveit :: new :: New".to_string(),
            ]),
        ])),
        None,
    );
}

/// A namespaced class's constructor, named the way C++ names it.
#[test]
fn test_throwing_ctor_in_a_namespace() {
    let cxx = indoc! {"
        namespace fx_ns {
            fx_Risky::fx_Risky(uint32_t x) {
                if (x == 0) throw std::runtime_error(\"fx namespaced\");
                a = x;
            }
        }
    "};
    let hdr = indoc! {"
        #include <stdexcept>
        #include <cstdint>
        namespace fx_ns {
            class fx_Risky {
            public:
                fx_Risky(uint32_t x);
                uint32_t get() const { return a; }
            private:
                uint32_t a = 0;
            };
        }
    "};
    let rs = quote! {
        let err = ffi::fx_ns::fx_Risky::new(0)
            .try_within_unique_ptr()
            .err()
            .expect("this constructor throws for 0");
        assert_eq!(err.what(), "fx namespaced");
        let obj = ffi::fx_ns::fx_Risky::new(6).try_within_unique_ptr().ok().unwrap();
        assert_eq!(obj.get(), 6);
    };
    run_test_ex(
        cxx,
        hdr,
        rs,
        quote! {
            generate!("fx_ns::fx_Risky")
            throws!("fx_ns::fx_Risky::fx_Risky")
        },
        None,
        None,
        None,
    );
}

/// A POD type's constructor can throw too. `generate_pod!` types get the same
/// placement-constructing `new` as any other, so they get the same treatment.
#[test]
fn test_throwing_ctor_of_a_pod_type() {
    let hdr = indoc! {"
        #include <stdexcept>
        #include <cstdint>
        struct fx_RiskyPod {
            fx_RiskyPod(uint32_t x) {
                if (x == 0) throw std::runtime_error(\"fx pod refuses\");
                a = x;
            }
            uint32_t a;
        };
    "};
    let rs = quote! {
        let err = ffi::fx_RiskyPod::new(0)
            .try_within_unique_ptr()
            .err()
            .expect("this constructor throws for 0");
        assert_eq!(err.what(), "fx pod refuses");
        let obj = ffi::fx_RiskyPod::new(8).try_within_unique_ptr().ok().unwrap();
        assert_eq!(obj.a, 8);
        autocxx::stack_slot!(storage);
        let on_stack = storage.try_emplace(ffi::fx_RiskyPod::new(12)).unwrap();
        assert_eq!(on_stack.a, 12);
    };
    run_test_ex(
        "",
        hdr,
        rs,
        directives_from_lists(
            &[],
            &["fx_RiskyPod"],
            Some(quote! { throws!("fx_RiskyPod::fx_RiskyPod") }),
        ),
        None,
        None,
        None,
    );
}

/// Nested construction: the outer object's own constructor body never runs,
/// because a member's constructor threw first.
///
/// C++ destroys the members which had been constructed by then, and no others,
/// and never destroys the outer object which was never constructed. Both
/// orderings matter, so both are here: `fx_Outer` builds a quiet member before
/// the throwing one, and `fx_OuterThrowsFirst` puts the throwing one first, so
/// that the sibling never exists at all. Every constructor and destructor
/// involved is counted, because "the right one ran" and "nothing else did" are
/// different claims.
#[test]
fn test_member_constructor_throwing_during_an_outer_construction() {
    let cxx = indoc! {"
        static uint32_t first_ctors = 0;
        static uint32_t first_dtors = 0;
        static uint32_t second_entries = 0;
        static uint32_t second_ctors = 0;
        static uint32_t second_dtors = 0;
        static uint32_t outer_dtors = 0;
        uint32_t fx_first_ctors() { return first_ctors; }
        uint32_t fx_first_dtors() { return first_dtors; }
        uint32_t fx_second_entries() { return second_entries; }
        uint32_t fx_second_ctors() { return second_ctors; }
        uint32_t fx_second_dtors() { return second_dtors; }
        uint32_t fx_outer_dtors() { return outer_dtors; }
        void fx_reset_counts() {
            first_ctors = 0; first_dtors = 0;
            second_entries = 0; second_ctors = 0; second_dtors = 0;
            outer_dtors = 0;
        }
        fx_First::fx_First() { first_ctors++; }
        fx_First::~fx_First() { first_dtors++; }
        fx_Second::fx_Second(uint32_t x) {
            second_entries++;
            if (x == 0) throw std::runtime_error(\"fx member objected\");
            second_ctors++;
        }
        fx_Second::~fx_Second() { second_dtors++; }
        fx_Outer::fx_Outer(uint32_t x) : first(), second(x) {}
        fx_Outer::~fx_Outer() { outer_dtors++; }
        fx_OuterThrowsFirst::fx_OuterThrowsFirst(uint32_t x) : second(x), first() {}
        fx_OuterThrowsFirst::~fx_OuterThrowsFirst() { outer_dtors++; }
    "};
    let hdr = indoc! {"
        #include <stdexcept>
        #include <cstdint>
        uint32_t fx_first_ctors();
        uint32_t fx_first_dtors();
        uint32_t fx_second_entries();
        uint32_t fx_second_ctors();
        uint32_t fx_second_dtors();
        uint32_t fx_outer_dtors();
        void fx_reset_counts();
        struct fx_First { fx_First(); ~fx_First(); };
        struct fx_Second { fx_Second(uint32_t x); ~fx_Second(); };
        class fx_Outer {
        public:
            fx_Outer(uint32_t x);
            ~fx_Outer();
        private:
            fx_First first;
            fx_Second second;
        };
        class fx_OuterThrowsFirst {
        public:
            fx_OuterThrowsFirst(uint32_t x);
            ~fx_OuterThrowsFirst();
        private:
            fx_Second second;
            fx_First first;
        };
    "};
    let rs = quote! {
        // The throwing member is constructed second, so its sibling is alive
        // when the exception is thrown and has to be destroyed on the way out.
        ffi::fx_reset_counts();
        let err = ffi::fx_Outer::new(0)
            .try_within_unique_ptr()
            .err()
            .expect("the member constructor throws for 0");
        assert_eq!(err.what(), "fx member objected");
        assert_eq!(ffi::fx_first_ctors(), 1, "the quiet member was constructed");
        assert_eq!(ffi::fx_first_dtors(), 1, "and destroyed by unwinding, once");
        assert_eq!(ffi::fx_second_entries(), 1, "the throwing member was entered");
        assert_eq!(ffi::fx_second_ctors(), 0, "but never completed");
        assert_eq!(
            ffi::fx_second_dtors(),
            0,
            "so it was not destroyed either - destroying a member whose \
             constructor threw would be a double destruction"
        );
        assert_eq!(
            ffi::fx_outer_dtors(),
            0,
            "and the outer object, which never existed, was never destroyed"
        );

        // The throwing member is constructed first, so nothing else was ever
        // built and nothing at all should be destroyed.
        ffi::fx_reset_counts();
        let err = ffi::fx_OuterThrowsFirst::new(0)
            .try_within_unique_ptr()
            .err()
            .expect("the first member constructor throws for 0");
        assert_eq!(err.what(), "fx member objected");
        assert_eq!(ffi::fx_second_entries(), 1);
        assert_eq!(ffi::fx_second_ctors(), 0);
        assert_eq!(ffi::fx_second_dtors(), 0);
        assert_eq!(ffi::fx_first_ctors(), 0, "the sibling was never reached");
        assert_eq!(ffi::fx_first_dtors(), 0);
        assert_eq!(ffi::fx_outer_dtors(), 0);

        // And when nothing throws, everything is constructed once and
        // destroyed once.
        ffi::fx_reset_counts();
        {
            let obj = ffi::fx_Outer::new(2).try_within_unique_ptr().ok().unwrap();
            assert_eq!(ffi::fx_first_ctors(), 1);
            assert_eq!(ffi::fx_second_ctors(), 1);
            assert_eq!(ffi::fx_outer_dtors(), 0);
            drop(obj);
        }
        assert_eq!(ffi::fx_outer_dtors(), 1);
        assert_eq!(ffi::fx_first_dtors(), 1);
        assert_eq!(ffi::fx_second_dtors(), 1);
    };
    run_test_ex(
        cxx,
        hdr,
        rs,
        quote! {
            generate!("fx_Outer")
            generate!("fx_OuterThrowsFirst")
            generate!("fx_first_ctors")
            generate!("fx_first_dtors")
            generate!("fx_second_entries")
            generate!("fx_second_ctors")
            generate!("fx_second_dtors")
            generate!("fx_outer_dtors")
            generate!("fx_reset_counts")
            throws!("fx_Outer::fx_Outer")
            throws!("fx_OuterThrowsFirst::fx_OuterThrowsFirst")
        },
        None,
        None,
        None,
    );
}

/// A `throws!` function which returns a non-POD type by value. This is the
/// same machinery as a constructor - the C++ builds the result into a place
/// the caller supplies - and until this change it generated Rust which did not
/// compile, because the `?` for the exception landed inside a closure returning
/// `()`.
#[test]
fn test_throwing_function_returning_a_non_pod_by_value() {
    let cxx = indoc! {"
        fx_Made fx_make(uint32_t x) {
            if (x == 0) throw std::runtime_error(\"fx will not make one\");
            fx_Made m;
            m.a = x;
            return m;
        }
    "};
    let hdr = indoc! {"
        #include <stdexcept>
        #include <cstdint>
        struct fx_Made {
            ~fx_Made() {}
            uint32_t a = 0;
            uint32_t get() const { return a; }
        };
        fx_Made fx_make(uint32_t x);
    "};
    let rs = quote! {
        let err = ffi::fx_make(0)
            .try_within_unique_ptr()
            .err()
            .expect("0 is refused");
        assert_eq!(err.what(), "fx will not make one");
        let made = ffi::fx_make(5).try_within_unique_ptr().ok().unwrap();
        assert_eq!(made.get(), 5);
        autocxx::stack_slot!(storage);
        assert_eq!(storage.try_emplace(ffi::fx_make(6)).unwrap().get(), 6);
    };
    run_test_ex(
        cxx,
        hdr,
        rs,
        quote! {
            generate!("fx_Made")
            generate!("fx_make")
            throws!("fx_make")
        },
        None,
        None,
        None,
    );
}

/// Naming a class rather than its constructor also designates the constructor,
/// because `throws!` matches a trailing qualified name and a constructor's
/// final name component is the class's own. `fx_Risky::fx_Risky` says the same
/// thing less ambiguously, and is what the book recommends.
#[test]
fn test_throws_matches_a_ctor_by_bare_class_name() {
    let hdr = indoc! {"
        #include <stdexcept>
        #include <cstdint>
        struct fx_Bare {
            fx_Bare(uint32_t x) {
                if (x == 0) throw std::runtime_error(\"fx bare\");
                a = x;
            }
            uint32_t a;
        };
    "};
    let rs = quote! {
        assert!(ffi::fx_Bare::new(0).try_within_unique_ptr().is_err());
    };
    run_test_ex(
        "",
        hdr,
        rs,
        quote! {
            generate!("fx_Bare")
            throws!("fx_Bare")
        },
        None,
        None,
        None,
    );
}

/// A nested class's throwing constructor, designated the way C++ spells the
/// class. bindgen flattens the nesting into `fx_NestOuter_fx_NestInner`, a
/// name nobody wrote and nobody has to know: `generate!` accepts either
/// spelling and so does `throws!`.
#[test]
fn test_throwing_ctor_of_nested_class() {
    let hdr = indoc! {"
        #include <stdexcept>
        #include <cstdint>
        struct fx_NestOuter {
            struct fx_NestInner {
                fx_NestInner(uint32_t x) {
                    if (x == 0) throw std::runtime_error(\"fx nested refuses\");
                    a = x;
                }
                uint32_t get() const { return a; }
            private:
                uint32_t a = 0;
            };
        };
    "};
    let rs = quote! {
        let err = ffi::fx_NestOuter_fx_NestInner::new(0)
            .try_within_unique_ptr()
            .err()
            .expect("this constructor throws for 0");
        assert_eq!(err.what(), "fx nested refuses");
        let obj = ffi::fx_NestOuter_fx_NestInner::new(5)
            .try_within_unique_ptr()
            .ok()
            .unwrap();
        assert_eq!(obj.get(), 5);
    };
    run_test_ex(
        "",
        hdr,
        rs,
        quote! {
            generate!("fx_NestOuter::fx_NestInner")
            throws!("fx_NestOuter::fx_NestInner::fx_NestInner")
        },
        None,
        None,
        None,
    );
}

/// One designation covers every overload of a constructor, because all of them
/// share the C++ name `fx_Many::fx_Many`. There is no spelling which picks out
/// a single overload; if only one of them throws, the others become fallible
/// too and their `Result`s are always `Ok`.
#[test]
fn test_throws_covers_every_constructor_overload() {
    let hdr = indoc! {"
        #include <stdexcept>
        #include <cstdint>
        struct fx_Many {
            fx_Many() : a(1) {}
            fx_Many(uint32_t x) {
                if (x == 0) throw std::runtime_error(\"fx many\");
                a = x;
            }
            uint32_t get() const { return a; }
            uint32_t a;
        };
    "};
    let rs = quote! {
        let default_made = ffi::fx_Many::new().try_within_unique_ptr().ok().unwrap();
        assert_eq!(default_made.get(), 1);
        let four = ffi::fx_Many::new1(4).try_within_unique_ptr().ok().unwrap();
        assert_eq!(four.get(), 4);
        assert!(ffi::fx_Many::new1(0).try_within_unique_ptr().is_err());
    };
    run_test_ex(
        "",
        hdr,
        rs,
        quote! {
            generate!("fx_Many")
            throws!("fx_Many::fx_Many")
        },
        None,
        None,
        None,
    );
}

/// A throwing constructor alongside a throwing method on the same class: the
/// two designations are independent and neither shape disturbs the other.
#[test]
fn test_throwing_ctor_and_throwing_method_together() {
    let cxx = indoc! {"
        fx_Both::fx_Both(uint32_t x) {
            if (x == 0) throw std::runtime_error(\"fx ctor\");
            a = x;
        }
        uint32_t fx_Both::risky() const {
            if (a == 1) throw std::runtime_error(\"fx method\");
            return a;
        }
    "};
    let hdr = indoc! {"
        #include <stdexcept>
        #include <cstdint>
        class fx_Both {
        public:
            fx_Both(uint32_t x);
            uint32_t risky() const;
        private:
            uint32_t a = 0;
        };
    "};
    let rs = quote! {
        let ctor_err = ffi::fx_Both::new(0).try_within_unique_ptr().err().unwrap();
        assert_eq!(ctor_err.what(), "fx ctor");
        let one = ffi::fx_Both::new(1).try_within_unique_ptr().ok().unwrap();
        assert_eq!(one.risky().unwrap_err().what(), "fx method");
        let two = ffi::fx_Both::new(2).try_within_unique_ptr().ok().unwrap();
        assert_eq!(two.risky().unwrap(), 2);
    };
    run_test_ex(
        cxx,
        hdr,
        rs,
        quote! {
            generate!("fx_Both")
            throws!("fx_Both::fx_Both")
            throws!("fx_Both::risky")
        },
        None,
        None,
        None,
    );
}

/// A subclass whose C++ superclass constructor can throw, across all three
/// ownership models and both outcomes.
///
/// Two things have to be true when the peer's constructor throws, and neither
/// is visible from the `Result` alone. The C++ peer must never come into
/// existence - the superclass constructor was entered but never completed, so
/// no destructor may run for it either - and the Rust half must be dropped
/// rather than stranded: the peer holder handed to C++ carries a strong or weak
/// reference to it, and that reference is only released by the `rust::Box`
/// destructor running as the exception unwinds. An implementation which leaked
/// the Rust side on failure would still report the exception correctly and
/// still pass a test which only looked at the `Result`, so this counts drops on
/// both sides.
#[test]
fn test_subclass_with_a_throwing_superclass_constructor() {
    let cxx = indoc! {"
        static uint32_t super_entries = 0;
        static uint32_t super_completions = 0;
        static uint32_t super_dtors = 0;
        uint32_t fx_super_entries() { return super_entries; }
        uint32_t fx_super_completions() { return super_completions; }
        uint32_t fx_super_dtors() { return super_dtors; }
        void fx_reset_super_counts() {
            super_entries = 0; super_completions = 0; super_dtors = 0;
        }
        fx_SuperRisky::fx_SuperRisky(uint32_t x) {
            super_entries++;
            if (x == 0) throw std::runtime_error(\"fx superclass objected\");
            a = x;
            super_completions++;
        }
        fx_SuperRisky::~fx_SuperRisky() { super_dtors++; }
    "};
    let hdr = indoc! {"
        #include <cstdint>
        #include <stdexcept>
        uint32_t fx_super_entries();
        uint32_t fx_super_completions();
        uint32_t fx_super_dtors();
        void fx_reset_super_counts();
        class fx_SuperRisky {
        public:
            fx_SuperRisky(uint32_t x);
            virtual uint32_t foo() const = 0;
            virtual ~fx_SuperRisky();
            uint32_t get() const { return a; }
        private:
            uint32_t a = 0;
        };
    "};
    run_test_ex(
        cxx,
        hdr,
        quote! {
            // Each ownership model, given an argument the superclass refuses.
            // `Sentinel` counts drops of the Rust half; the C++ counters say
            // whether a peer was ever built.
            for construct in [
                |sub| MySub::try_new_rust_owned(sub).map(|_| ()),
                |sub| MySub::try_new_cpp_owned(sub).map(|_| ()),
                |sub| MySub::try_new_self_owned(sub).map(|_| ()),
            ] {
                ffi::fx_reset_super_counts();
                let drops_before = sentinel_drops();
                let err = construct(MySub {
                    arg: 0,
                    sentinel: Sentinel,
                    cpp_peer: Default::default(),
                })
                .err()
                .expect("the superclass constructor throws for 0");
                assert_eq!(err.what(), "fx superclass objected");
                assert_eq!(ffi::fx_super_entries(), 1, "the superclass constructor ran");
                assert_eq!(
                    ffi::fx_super_completions(),
                    0,
                    "but never finished, so no peer exists"
                );
                assert_eq!(
                    ffi::fx_super_dtors(),
                    0,
                    "and nothing was destroyed which was never constructed"
                );
                assert_eq!(
                    sentinel_drops(),
                    drops_before + 1,
                    "the Rust subclass was dropped exactly once, not stranded in the \
                     peer holder C++ was given"
                );
            }

            // And the same three, given an argument it accepts.
            ffi::fx_reset_super_counts();
            let drops_before = sentinel_drops();
            {
                let rust_owned = MySub::try_new_rust_owned(MySub {
                    arg: 5,
                    sentinel: Sentinel,
                    cpp_peer: Default::default(),
                })
                .ok()
                .expect("5 is fine");
                let borrowed = rust_owned.borrow();
                let superclass: &ffi::fx_SuperRisky = borrowed.as_ref();
                assert_eq!(superclass.get(), 5);
                assert_eq!(ffi::fx_super_completions(), 1);
                assert_eq!(sentinel_drops(), drops_before, "still alive");
            }
            assert_eq!(
                sentinel_drops(),
                drops_before + 1,
                "and dropped once when its owner went away"
            );

            let cpp_owned = MySub::try_new_cpp_owned(MySub {
                arg: 6,
                sentinel: Sentinel,
                cpp_peer: Default::default(),
            })
            .ok()
            .expect("6 is fine");
            assert_eq!(cpp_owned.As_fx_SuperRisky().get(), 6);
            drop(cpp_owned);

            let self_owned = MySub::try_new_self_owned(MySub {
                arg: 7,
                sentinel: Sentinel,
                cpp_peer: Default::default(),
            })
            .ok()
            .expect("7 is fine");
            {
                let borrowed = self_owned.borrow();
                let superclass: &ffi::fx_SuperRisky = borrowed.as_ref();
                assert_eq!(superclass.get(), 7);
            }
            // A self-owned subclass stays alive until it says otherwise, which
            // is what distinguishes it from the other two.
            let drops_before = sentinel_drops();
            self_owned.borrow().delete_self();
            drop(self_owned);
            assert_eq!(sentinel_drops(), drops_before + 1);
        },
        quote! {
            subclass!("fx_SuperRisky",MySub)
            generate!("fx_super_entries")
            generate!("fx_super_completions")
            generate!("fx_super_dtors")
            generate!("fx_reset_super_counts")
            throws!("MySubCpp::MySubCpp")
        },
        None,
        None,
        Some(quote! {
            use autocxx::subclass::{
                CppPeerConstructor, CppSubclass, CppSubclassRustPeerHolder, CppSubclassSelfOwned,
            };
            use ffi::fx_SuperRisky_methods;
            use std::cell::Cell;

            thread_local! {
                static SENTINEL_DROPS: Cell<u32> = const { Cell::new(0) };
            }

            fn sentinel_drops() -> u32 {
                SENTINEL_DROPS.with(|c| c.get())
            }

            /// A field of the Rust subclass whose destruction is observable, so
            /// that a failed construction which stranded the subclass rather
            /// than dropping it would be visible.
            pub struct Sentinel;

            impl Drop for Sentinel {
                fn drop(&mut self) {
                    SENTINEL_DROPS.with(|c| c.set(c.get() + 1));
                }
            }

            #[autocxx::subclass::subclass(self_owned)]
            pub struct MySub {
                arg: u32,
                sentinel: Sentinel,
            }

            impl fx_SuperRisky_methods for MySub {
                fn foo(&self) -> u32 {
                    self.arg
                }
            }

            impl CppPeerConstructor<ffi::MySubCpp> for MySub {
                fn make_peer(
                    &mut self,
                    peer_holder: CppSubclassRustPeerHolder<Self>,
                ) -> cxx::UniquePtr<ffi::MySubCpp> {
                    self.try_make_peer(peer_holder)
                        .expect("the superclass constructor threw")
                }

                fn try_make_peer(
                    &mut self,
                    peer_holder: CppSubclassRustPeerHolder<Self>,
                ) -> Result<cxx::UniquePtr<ffi::MySubCpp>, cxx::Exception> {
                    ffi::MySubCpp::new(peer_holder, self.arg)
                }
            }
        }),
    );
}

/// The same, for a superclass whose single constructor takes no arguments -
/// the shape autocxx writes the `CppPeerConstructor` impl for itself.
///
/// A `throws!`-designated peer constructor hands back a `Result` where
/// `make_peer` promises a `UniquePtr`, so the impl autocxx would write cannot
/// compile; and because it is written anyway, nor can the author's own, which
/// collides with it. Declining to write it is what leaves this test anything
/// to say.
#[test]
fn test_subclass_with_a_throwing_no_argument_superclass_constructor() {
    let cxx = indoc! {"
        static bool fx_na_armed = false;
        void fx_na_arm() { fx_na_armed = true; }
        void fx_na_disarm() { fx_na_armed = false; }
        fx_NoArgRisky::fx_NoArgRisky() {
            if (fx_na_armed) throw std::runtime_error(\"fx no-arg superclass objected\");
        }
    "};
    let hdr = indoc! {"
        #include <cstdint>
        #include <stdexcept>
        void fx_na_arm();
        void fx_na_disarm();
        class fx_NoArgRisky {
        public:
            fx_NoArgRisky();
            virtual uint32_t foo() const = 0;
            virtual ~fx_NoArgRisky() {}
        };
    "};
    run_test_ex(
        cxx,
        hdr,
        quote! {
            ffi::fx_na_disarm();
            let rust_owned = MySub::try_new_rust_owned(MySub { cpp_peer: Default::default() })
                .ok()
                .expect("the superclass constructor was disarmed");
            assert_eq!(rust_owned.borrow().foo(), 7);
            ffi::fx_na_arm();
            let err = MySub::try_new_rust_owned(MySub { cpp_peer: Default::default() })
                .err()
                .expect("the superclass constructor threw");
            assert_eq!(err.what(), "fx no-arg superclass objected");
            ffi::fx_na_disarm();
        },
        quote! {
            subclass!("fx_NoArgRisky",MySub)
            generate!("fx_na_arm")
            generate!("fx_na_disarm")
            throws!("MySubCpp::MySubCpp")
        },
        None,
        None,
        Some(quote! {
            use autocxx::subclass::prelude::*;
            use ffi::fx_NoArgRisky_methods;

            #[subclass]
            #[derive(Default)]
            pub struct MySub;

            impl fx_NoArgRisky_methods for MySub {
                fn foo(&self) -> u32 { 7 }
            }

            impl CppPeerConstructor<ffi::MySubCpp> for MySub {
                fn make_peer(
                    &mut self,
                    peer_holder: CppSubclassRustPeerHolder<Self>,
                ) -> cxx::UniquePtr<ffi::MySubCpp> {
                    self.try_make_peer(peer_holder)
                        .expect("the superclass constructor threw")
                }

                fn try_make_peer(
                    &mut self,
                    peer_holder: CppSubclassRustPeerHolder<Self>,
                ) -> Result<cxx::UniquePtr<ffi::MySubCpp>, cxx::Exception> {
                    ffi::MySubCpp::new(peer_holder)
                }
            }
        }),
    );
}

/// A class with constructors it declares for itself which `moveit` turns into
/// trait impls - a copy constructor and a move constructor - can still have a
/// throwing value constructor. `throws!("fx_Copyable::fx_Copyable")` names all
/// three, because they share one C++ name, but only the value constructor can
/// carry a `Result`: `moveit::CopyNew` and `moveit::MoveNew` return nothing,
/// so a copy or move constructor which throws still terminates the process.
/// See the `designation_can_be_honoured` comment in `analyse_foreign_fn`.
#[test]
fn test_throwing_ctor_of_a_class_with_its_own_copy_and_move_ctors() {
    let hdr = indoc! {"
        #include <stdexcept>
        #include <cstdint>
        class fx_Copyable {
        public:
            fx_Copyable(uint32_t x) {
                if (x == 0) throw std::runtime_error(\"fx copyable\");
                a = x;
            }
            fx_Copyable(const fx_Copyable& other) { a = other.a; }
            fx_Copyable(fx_Copyable&& other) { a = other.a; }
            ~fx_Copyable() {}
            uint32_t get() const { return a; }
        private:
            uint32_t a = 0;
        };
    "};
    let rs = quote! {
        let err = ffi::fx_Copyable::new(0)
            .try_within_unique_ptr()
            .err()
            .expect("this constructor throws for 0");
        assert_eq!(err.what(), "fx copyable");
        let obj = ffi::fx_Copyable::new(4).try_within_unique_ptr().ok().unwrap();
        assert_eq!(obj.get(), 4);
        // The copy constructor is still the infallible `CopyNew` it always
        // was, and needs no `try_`.
        let copy = autocxx::moveit::new::copy(obj.as_ref().unwrap()).within_unique_ptr();
        assert_eq!(copy.get(), 4);
    };
    run_test_ex(
        "",
        hdr,
        rs,
        quote! {
            generate!("fx_Copyable")
            throws!("fx_Copyable::fx_Copyable")
        },
        None,
        None,
        None,
    );
}

/// A copy constructor which throws kills the process, which is what the book
/// says and what nothing else here proves.
///
/// `throws!("fx_Suicidal::fx_Suicidal")` names every constructor of the class,
/// but a copy constructor becomes `moveit::CopyNew`, whose `copy_new` returns
/// nothing - so the designation cannot be honoured for it and the exception has
/// nowhere to go but `std::terminate`. The value constructor in the same class
/// is fallible, which is the point of testing them together.
///
/// This is a death test, hosted by the harness's existing child process: it
/// builds the generated Rust and *runs* it, so a run which dies is a `TestError`
/// carrying the child's own output. The C++ installs a `std::terminate` handler
/// which prints a marker and calls `std::_Exit`, for two reasons. It lets the
/// assertion tell "reached `std::terminate`" apart from any other way a process
/// can die - the wording each standard library prints on its way out differs
/// between libc++, libstdc++ and the UCRT, so there is no portable string to
/// match on otherwise - and it means the child leaves without an `abort()`, so
/// no leg of CI has to cope with a core dump or a crash reporter.
///
/// What this pins, then, is that the exception is not caught and the program
/// does not carry on. What the *default* terminate handler would have done next
/// is `abort()`, by the standard, and is not this test's business.
#[test]
fn test_throwing_copy_constructor_terminates_the_process() {
    let cxx = indoc! {"
        void fx_install_terminate_marker() {
            std::set_terminate([]() {
                std::fputs(\"FX-TERMINATE-REACHED\\n\", stderr);
                std::fflush(stderr);
                std::_Exit(42);
            });
        }
        fx_Suicidal::fx_Suicidal(uint32_t x) {
            if (x == 0) throw std::runtime_error(\"fx value ctor objected\");
            a = x;
        }
        fx_Suicidal::fx_Suicidal(const fx_Suicidal&) {
            throw std::runtime_error(\"fx copy ctor objected\");
        }
        fx_Suicidal::~fx_Suicidal() {}
    "};
    let hdr = indoc! {"
        #include <stdexcept>
        #include <exception>
        #include <cstdint>
        #include <cstdio>
        #include <cstdlib>
        void fx_install_terminate_marker();
        class fx_Suicidal {
        public:
            fx_Suicidal(uint32_t x);
            fx_Suicidal(const fx_Suicidal& other);
            ~fx_Suicidal();
            uint32_t get() const { return a; }
        private:
            uint32_t a = 0;
        };
    "};
    let rs = quote! {
        ffi::fx_install_terminate_marker();
        // The value constructor is fallible, and reports rather than dying.
        let err = ffi::fx_Suicidal::new(0)
            .try_within_unique_ptr()
            .err()
            .expect("the value constructor throws for 0");
        assert_eq!(err.what(), "fx value ctor objected");
        let obj = ffi::fx_Suicidal::new(1).try_within_unique_ptr().ok().unwrap();
        assert_eq!(obj.get(), 1);
        // The copy constructor is not, and this line does not return.
        let copy = autocxx::moveit::new::copy(obj.as_ref().unwrap()).within_unique_ptr();
        // Unreachable. If it were reached, the test would fail by succeeding.
        assert_eq!(copy.get(), 1);
    };
    run_test_expect_fail_with_errors_ex(
        cxx,
        hdr,
        rs,
        quote! {
            generate!("fx_Suicidal")
            generate!("fx_install_terminate_marker")
            throws!("fx_Suicidal::fx_Suicidal")
        },
        None,
        &[
            // Only printed once trybuild has built the code and gone on to run
            // it, so this also says the generated Rust compiled.
            "Test case failed at runtime",
            "FX-TERMINATE-REACHED",
        ],
    );
}

/// `as_new` takes a `New`, so a throwing constructor cannot be handed straight
/// to a C++ function which takes its argument by value. The book tells people
/// to construct the object first and pass that; this is that advice, compiled.
#[test]
fn test_throwing_ctor_result_passed_by_value_after_construction() {
    let hdr = indoc! {"
        #include <stdexcept>
        #include <cstdint>
        struct fx_Cargo {
            fx_Cargo(uint32_t x) {
                if (x == 0) throw std::runtime_error(\"fx no empty cargo\");
                a = x;
            }
            fx_Cargo(fx_Cargo&& other) : a(other.a) {}
            ~fx_Cargo() {}
            uint32_t a;
        };
        inline uint32_t fx_weigh(fx_Cargo c) { return c.a; }
    "};
    let rs = quote! {
        let cargo = ffi::fx_Cargo::new(3).try_within_unique_ptr().ok().unwrap();
        assert_eq!(ffi::fx_weigh(as_mov(cargo)), 3);
    };
    run_test_ex(
        "",
        hdr,
        rs,
        quote! {
            generate!("fx_Cargo")
            generate!("fx_weigh")
            throws!("fx_Cargo::fx_Cargo")
        },
        None,
        None,
        None,
    );
}

/// A `throws!` function taking a by-value POD which has its own move
/// constructor.
///
/// These two features only meet after the fact. A parameter like this is
/// handed to C++ with `autocxx_move_or_copy`, which is deliberately *not* a
/// reason to generate a C++ wrapper - it only says how a wrapper which exists
/// anyway should spell the hand-over (see google/autocxx#1252). A `throws!`
/// designation is a new reason for such a wrapper to exist, and in plain
/// codegen it is the only one here, so this is the shape where the two decide
/// the same wrapper together. `fx_Bob` declares a move constructor and so has
/// no implicit copy constructor, which is what makes the hand-over observable:
/// a wrapper which tried to copy the parameter would not compile.
#[test]
fn test_throwing_function_taking_a_relocatable_pod_by_value() {
    let cxx = indoc! {"
        uint32_t fx_take_bob(fx_Bob a) {
            if (a.a == 0) throw std::runtime_error(\"fx bob objected\");
            return a.a;
        }
    "};
    let hdr = indoc! {"
        #include <cstdint>
        #include <stdexcept>
        #include <type_traits>
        struct fx_Bob {
            uint32_t a;
            uint32_t b;
            inline fx_Bob() {}
            inline ~fx_Bob() {}
            inline fx_Bob(fx_Bob&& other) { a = other.a; b = other.b; }
            using IsRelocatable = std::true_type;
        };
        uint32_t fx_take_bob(fx_Bob a);
    "};
    let rs = quote! {
        let good = ffi::fx_Bob { a: 12, b: 13 };
        assert_eq!(ffi::fx_take_bob(good).unwrap(), 12);
        let bad = ffi::fx_Bob { a: 0, b: 13 };
        let err = ffi::fx_take_bob(bad).unwrap_err();
        assert_eq!(err.what(), "fx bob objected");
    };
    run_test_ex(
        cxx,
        hdr,
        rs,
        quote! {
            generate!("fx_take_bob")
            pod!("fx_Bob")
            throws!("fx_take_bob")
        },
        None,
        None,
        None,
    );
}

/// A POD struct holding an array of another struct. Holding four of something
/// by value needs that something to be POD exactly as holding one of it would,
/// so `pod!` on the outer struct has to reach the element type through the
/// array - the user should not have to name it separately.
#[test]
fn test_pod_struct_holding_array_of_pod_structs() {
    let hdr = indoc! {"
        #include <cstdint>
        struct fx_ArrInner { uint32_t x; };
        struct fx_ArrOuter { fx_ArrInner arr[4]; uint32_t y; };
    "};
    let rs = quote! {
        let o = ffi::fx_ArrOuter { arr: [
            ffi::fx_ArrInner { x: 1 },
            ffi::fx_ArrInner { x: 2 },
            ffi::fx_ArrInner { x: 3 },
            ffi::fx_ArrInner { x: 4 },
        ], y: 5 };
        assert_eq!(o.arr[2].x, 3);
        assert_eq!(o.y, 5);
    };
    run_test("", hdr, rs, &[], &["fx_ArrOuter"]);
}

/// The element type of an array is needed in full - its own constructors
/// decide which of the holder's are implicitly available - so it has to be
/// registered as a definition dependency, or the constructor analysis may run
/// before the element type has been analysed and give up on the holder. That
/// order goes wrong for a nested class, which bindgen hoists out of its
/// enclosing class and emits afterwards.
#[test]
fn test_pod_struct_holding_array_of_nested_class() {
    let hdr = indoc! {"
        #include <cstdint>
        struct fx_Holder {
            struct Element { uint32_t x; };
            Element arr[3];
            uint32_t y;
        };
    "};
    let rs = quote! {
        let h = ffi::fx_Holder {
            arr: [
                ffi::fx_Holder_Element { x: 7 },
                ffi::fx_Holder_Element { x: 8 },
                ffi::fx_Holder_Element { x: 9 },
            ],
            y: 10,
        };
        assert_eq!(h.arr[1].x, 8);
        assert_eq!(h.y, 10);
    };
    run_test_ex(
        "",
        hdr,
        rs,
        quote! { generate_pod!("fx_Holder") },
        None,
        // The holder used to be handed to the constructor analysis before the
        // element type, which then blamed the element type for constructors it
        // could not work out - and told the user to `generate!` a type it had
        // generated already.
        Some(make_string_absence_finder(vec![
            "does not understand".to_string()
        ])),
        None,
    );
}

/// An array field whose element type can't be held by value in Rust makes the
/// struct holding it just as unsafe as a plain field of that type would, so
/// `pod!` on it has to be refused with the reason - not accepted and left for
/// the C++ compiler to complain about.
#[test]
fn test_pod_struct_holding_array_of_non_pod_is_rejected() {
    let hdr = indoc! {"
        #include <cstdint>
        #include <string>
        struct fx_HasStr { std::string s; };
        struct fx_HoldsStrArray { fx_HasStr arr[4]; uint32_t y; };
    "};
    run_test_expect_fail_with_errors(
        "",
        hdr,
        quote! {},
        &[],
        &["fx_HoldsStrArray"],
        &["could not be POD", "fx_HasStr"],
    );
}

/// The element type of an array can itself be an array, so the walk has to
/// peel off however many dimensions there are rather than just the one.
#[test]
fn test_pod_struct_holding_array_of_arrays_of_non_pod_is_rejected() {
    let hdr = indoc! {"
        #include <cstdint>
        #include <string>
        struct fx_HasStr2 { std::string s; };
        struct fx_HoldsStrMatrix { fx_HasStr2 arr[2][3]; uint32_t y; };
    "};
    run_test_expect_fail_with_errors(
        "",
        hdr,
        quote! {},
        &[],
        &["fx_HoldsStrMatrix"],
        &["could not be POD", "fx_HasStr2"],
    );
}

/// And the element type may be unsafe only because of what it holds by value
/// in turn, which is the ordinary struct-to-struct walk reached through an
/// array.
#[test]
fn test_pod_struct_holding_array_of_struct_containing_non_pod_is_rejected() {
    let hdr = indoc! {"
        #include <cstdint>
        #include <string>
        struct fx_DeepStr { std::string s; };
        struct fx_DeepHolder { fx_DeepStr d; uint32_t z; };
        struct fx_HoldsDeepArray { fx_DeepHolder arr[2]; uint32_t y; };
    "};
    run_test_expect_fail_with_errors(
        "",
        hdr,
        quote! {},
        &[],
        &["fx_HoldsDeepArray"],
        &["could not be POD", "fx_DeepHolder"],
    );
}

/// A virtual method which returns an *rvalue* reference. The peer's override
/// has to repeat the superclass's `fx_Baton&&`; it used to say `fx_Baton*`,
/// which overrides nothing and does not even compile once `override` is on
/// the declaration.
///
/// C++ has no way to get its hands on the returned object here except by
/// moving out of the reference, since the copy constructor is deleted - so if
/// either half of the signature drifted back to a pointer, or to a plain
/// lvalue reference, this would fail to build rather than quietly copy. The
/// moved-from object is checked afterwards, which is how the test knows the
/// move really happened through the override rather than somewhere else.
#[test]
fn test_subclass_virtual_returning_rvalue_reference() {
    let hdr = indoc! {"
    #include <cstdint>

    struct fx_Baton {
        uint32_t a;
        explicit fx_Baton(uint32_t a) : a(a) {}
        fx_Baton(fx_Baton&& other) : a(other.a) { other.a = 0; }
        fx_Baton(const fx_Baton&) = delete;
        uint32_t fx_get() const { return a; }
    };

    class fx_Relay {
    public:
        fx_Relay() {}
        virtual fx_Baton&& fx_pass() = 0;
        virtual ~fx_Relay() {}
    };

    inline uint32_t fx_run(fx_Relay* r) {
        fx_Baton taken(r->fx_pass());
        return taken.fx_get();
    }
    "};
    run_test_ex(
        "",
        hdr,
        quote! {
            let baton = ffi::fx_Baton::new(42).within_unique_ptr();
            let relay = MyRelay::new_rust_owned(MyRelay {
                baton: baton.as_mut_ptr(),
                cpp_peer: Default::default(),
            });
            // Via a pointer rather than a `Pin<&mut>`, so that the `RefCell`
            // borrow is over before C++ calls back into the override.
            let sup: *mut ffi::fx_Relay =
                unsafe { relay.borrow_mut().pin_mut().get_unchecked_mut() };
            assert_eq!(unsafe { ffi::fx_run(sup) }, 42);
            assert_eq!(baton.as_ref().unwrap().fx_get(), 0);
        },
        quote! {
            generate!("fx_run")
            generate!("fx_Baton")
            subclass!("fx_Relay",MyRelay)
        },
        None,
        None,
        Some(quote! {
            use autocxx::subclass::CppSubclass;
            use ffi::fx_Relay_methods;
            #[autocxx::subclass::subclass]
            pub struct MyRelay {
                baton: *mut ffi::fx_Baton,
            }
            impl fx_Relay_methods for MyRelay {
                fn fx_pass(&mut self) -> *mut ffi::fx_Baton {
                    self.baton
                }
            }
        }),
    );
}

/// A *public* non-pure virtual returning an rvalue reference, which a Rust
/// subclass cannot override: such a method gets a `_super` helper so that an
/// override can call the superclass's own implementation, that helper is a
/// call *to* a method returning `T&&`, autocxx generates no binding for one
/// of those, and the method drops out of the `_methods` trait along with it.
/// The superclass's implementation runs instead, which is what this checks.
///
/// So the deciding fact is the `_super` helper, not purity: a *private*
/// non-pure virtual gets no helper - the peer may override it but not call
/// it - and is overridable exactly as a pure virtual is. That is
/// `test_subclass_private_non_pure_virtual_returning_rvalue_reference`
/// below.
///
/// None of this is new here, and none of it is what this change is about; it
/// is pinned because the neighbouring cases now work and the line between
/// them is otherwise invisible.
/// `test_subclass_ref_qualified_virtual_method` is the same shape for a
/// non-pure `&&`-*qualified* method.
#[test]
fn test_subclass_non_pure_virtual_returning_rvalue_reference() {
    let hdr = indoc! {"
    #include <cstdint>

    struct fx_Crate { uint32_t a; };

    class fx_Store {
    public:
        fx_Store() : held{7} {}
        virtual fx_Crate&& fx_open() { return static_cast<fx_Crate&&>(held); }
        virtual ~fx_Store() {}
    private:
        fx_Crate held;
    };

    inline uint32_t fx_open_of(fx_Store* s) { return s->fx_open().a; }
    "};
    run_test_ex(
        "",
        hdr,
        quote! {
            let store = MyStore::new_rust_owned(MyStore { cpp_peer: Default::default() });
            let sup: *mut ffi::fx_Store =
                unsafe { store.borrow_mut().pin_mut().get_unchecked_mut() };
            assert_eq!(unsafe { ffi::fx_open_of(sup) }, 7);
        },
        quote! {
            generate!("fx_open_of")
            generate_pod!("fx_Crate")
            subclass!("fx_Store",MyStore)
        },
        None,
        None,
        Some(quote! {
            use autocxx::subclass::CppSubclass;
            use ffi::fx_Store_methods;
            #[autocxx::subclass::subclass]
            pub struct MyStore {}
            impl fx_Store_methods for MyStore {}
        }),
    );
}

/// The other side of the line drawn in
/// [`test_subclass_non_pure_virtual_returning_rvalue_reference`]: a *private*
/// non-pure virtual returning `T&&`. A peer may override a private virtual
/// but may not call it, so autocxx generates no `_super` helper, so there is
/// no binding to a `T&&`-returning method to go missing, so the method stays
/// in the `_methods` trait and the override is generated - the pure-virtual
/// path in all but name. The C++ here calls the private virtual through a
/// public method of its own, which is what a private virtual is for.
#[test]
fn test_subclass_private_non_pure_virtual_returning_rvalue_reference() {
    let hdr = indoc! {"
    #include <cstdint>

    struct fx_Ticket { uint32_t a; };

    class fx_Gate {
    public:
        fx_Gate() : held{7} {}
        virtual ~fx_Gate() {}
        uint32_t fx_admit() { return fx_check().a; }
    private:
        virtual fx_Ticket&& fx_check() { return static_cast<fx_Ticket&&>(held); }
        fx_Ticket held;
    };

    inline uint32_t fx_admit_of(fx_Gate* g) { return g->fx_admit(); }
    "};
    run_test_ex(
        "",
        hdr,
        quote! {
            let mut ticket = ffi::fx_Ticket { a: 42 };
            let gate = MyGate::new_rust_owned(MyGate {
                ticket: &mut ticket,
                cpp_peer: Default::default(),
            });
            let sup: *mut ffi::fx_Gate =
                unsafe { gate.borrow_mut().pin_mut().get_unchecked_mut() };
            assert_eq!(unsafe { ffi::fx_admit_of(sup) }, 42);
        },
        quote! {
            generate!("fx_admit_of")
            generate_pod!("fx_Ticket")
            subclass!("fx_Gate",MyGate)
        },
        None,
        None,
        Some(quote! {
            use autocxx::subclass::CppSubclass;
            use ffi::fx_Gate_methods;
            #[autocxx::subclass::subclass]
            pub struct MyGate {
                ticket: *mut ffi::fx_Ticket,
            }
            impl fx_Gate_methods for MyGate {
                fn fx_check(&mut self) -> *mut ffi::fx_Ticket {
                    self.ticket
                }
            }
        }),
    );
}

/// The `const` twin of [`test_subclass_virtual_returning_rvalue_reference`].
/// `const fx_Token&&` is still an rvalue reference, and still nothing a
/// pointer can stand in for in the override's signature - but the pointer it
/// crosses the bridge as is a `*const` one, and the peer has to say `const`
/// in both places or it overrides nothing.
#[test]
fn test_subclass_virtual_returning_const_rvalue_reference() {
    let hdr = indoc! {"
    #include <cstdint>

    struct fx_Token { uint32_t a; };

    class fx_Vault {
    public:
        fx_Vault() {}
        virtual const fx_Token&& fx_yield() const = 0;
        virtual ~fx_Vault() {}
    };

    inline uint32_t fx_peek(const fx_Vault& v) { return v.fx_yield().a; }
    "};
    run_test_ex(
        "",
        hdr,
        quote! {
            let token = ffi::fx_Token { a: 42 };
            let vault = MyVault::new_rust_owned(MyVault {
                token: &token as *const ffi::fx_Token,
                cpp_peer: Default::default(),
            });
            assert_eq!(ffi::fx_peek(vault.borrow().as_ref()), 42);
        },
        quote! {
            generate!("fx_peek")
            generate_pod!("fx_Token")
            subclass!("fx_Vault",MyVault)
        },
        None,
        None,
        Some(quote! {
            use autocxx::subclass::CppSubclass;
            use ffi::fx_Vault_methods;
            #[autocxx::subclass::subclass]
            pub struct MyVault {
                token: *const ffi::fx_Token,
            }
            impl fx_Vault_methods for MyVault {
                fn fx_yield(&self) -> *const ffi::fx_Token {
                    self.token
                }
            }
        }),
    );
}

#[test]
fn test_subclass_virtual_method_taking_move_only_type_by_value() {
    // A virtual method taking, by value, a type with no copy constructor -
    // `std::unique_ptr` is one - reaches the peer class's override, which has
    // to hand the value on to Rust with the `std::move` C++ demands. The peer
    // is built by inverting each conversion the ordinary Rust-to-C++ wrapper
    // performs, and the conversion for such a parameter is the one which says
    // "move it"; asking for its opposite used to be a panic, so this shape
    // brought the whole build down.
    let hdr = indoc! {"
    #include <cstdint>
    #include <memory>

    class fy_Widget {
    public:
        fy_Widget(uint32_t v) : v(v) {}
        uint32_t v;
    };

    class fy_Sink {
    public:
        fy_Sink() {}
        virtual void fy_accept(std::unique_ptr<fy_Widget> w) = 0;
        virtual ~fy_Sink() {}
    };

    extern fy_Sink* fy_the_sink;
    inline void fy_register(fy_Sink& s) { fy_the_sink = &s; }
    inline void fy_send(uint32_t v) {
        fy_the_sink->fy_accept(std::make_unique<fy_Widget>(v));
    }
    "};
    run_test_ex(
        "fy_Sink* fy_the_sink;",
        hdr,
        quote! {
            let sink = MySink::new_rust_owned(MySink { seen: 0, cpp_peer: Default::default() });
            ffi::fy_register(sink.as_ref().borrow_mut().pin_mut());
            ffi::fy_send(42);
            assert_eq!(sink.borrow().seen, 42);
        },
        quote! {
            generate!("fy_register")
            generate!("fy_send")
            generate_pod!("fy_Widget")
            subclass!("fy_Sink",MySink)
        },
        None,
        None,
        Some(quote! {
            use autocxx::subclass::CppSubclass;
            use ffi::fy_Sink_methods;
            #[autocxx::subclass::subclass]
            pub struct MySink {
                seen: u32,
            }
            impl fy_Sink_methods for MySink {
                fn fy_accept(&mut self, w: cxx::UniquePtr<ffi::fy_Widget>) {
                    self.seen = w.as_ref().unwrap().v;
                }
            }
        }),
    );
}

#[test]
fn test_generated_method_names_its_receiver_the_same_in_cpp_and_rust() {
    // A method needing a C++ wrapper - here because it returns a non-POD by
    // value - is written twice: once as the C++ function autocxx generates,
    // and once as the `cxx::bridge` declaration of that same function. Both
    // name the receiver from `RECEIVER_ARG_NAME`, which is what stops the two
    // drifting apart into separate literals again. The spelling below is that
    // constant's value, so change them together.
    let hdr = indoc! {"
        #include <cstdint>
        class Bob {
        public:
            Bob() : a(0) {}
            Bob(const Bob&) = default;
            Bob plus(uint32_t b) const { Bob r; r.a = a + b; return r; }
            uint32_t get() const { return a; }
            uint32_t a;
        };
    "};
    let rs = quote! {
        let b = ffi::Bob::new().within_unique_ptr();
        assert_eq!(b.plus(3).within_unique_ptr().get(), 3);
    };
    run_test_ex(
        "",
        hdr,
        rs,
        directives_from_lists(&["Bob"], &[], None),
        None,
        Some(make_checks(vec![
            Box::new(CppMatcher::new(&["autocxx_gen_this"], &[])),
            make_string_finder(vec!["autocxx_gen_this :".to_string()]),
        ])),
        None,
    );
}

/// A method whose name is the class's name followed by digits reads exactly
/// like one of that class's constructors, which is how autocxx used to
/// classify it. See google/autocxx#995.
#[test]
fn test_method_named_like_a_constructor_overload() {
    let hdr = indoc! {"
        #include <cstdint>
        class Widget {
        public:
            Widget() : a(3) {}
            Widget(uint32_t a) : a(a) {}
            uint32_t Widget3() const { return a; }
            static uint32_t Widget1() { return 1; }
            uint32_t a;
        };
    "};
    let rs = quote! {
        let w = ffi::Widget::new().within_unique_ptr();
        assert_eq!(w.Widget3(), 3);
        // A constructor which is not a special member, so it is classified
        // by the kind bindgen reported rather than by being one.
        let w = ffi::Widget::new1(7).within_unique_ptr();
        assert_eq!(w.Widget3(), 7);
        assert_eq!(ffi::Widget::Widget1(), 1);
    };
    run_test("", hdr, rs, &["Widget"], &[]);
}

// The layout tests below all ask the same question in the same way: what Rust
// computes for the generated type against what the C++ compiler computes for
// the original. Which bytes a class occupies is the ABI's business rather than
// the language's - the Itanium ABI lends a base class's tail padding to the
// members laid out after it and the MSVC ABI does not, and the two disagree
// about how wide a class deriving from two empty ones is - so a number written
// down here would be right on one CI leg and wrong on another. The compiler
// under the test is the oracle instead.
//
// For a type autocxx makes POD the Rust struct is bindgen's, so its fields'
// offsets are checkable too. For a non-POD type Rust holds a
// `#[repr(transparent)]` wrapper around that struct and has no field access,
// so the size and the alignment are the whole of what Rust claims - and the
// whole of what has to be right for autocxx to allocate storage for one.

/// An empty class is not always one byte wide. Two subobjects of the same type
/// need distinct addresses, so a class deriving from two classes which each
/// derive from the same empty class holds two copies of it and the Itanium ABI
/// makes it two bytes. bindgen wrote such a class out as its one `_address`
/// byte whatever the target said, which is smaller than the object C++ hands
/// over - see the patch series' `16-empty-class-size.patch`.
#[test]
fn test_empty_diamond_is_as_wide_as_cpp_makes_it() {
    let hdr = indoc! {"
        #include <cstddef>
        struct fx_LayEmpty {};
        struct fx_LayLeft : public fx_LayEmpty {};
        struct fx_LayRight : public fx_LayEmpty {};
        struct fx_LayMiddle : public fx_LayEmpty {};
        struct fx_LayDiamond : public fx_LayLeft, public fx_LayRight {};
        struct fx_LayDeeper : public fx_LayDiamond {};
        struct fx_LayThree : public fx_LayLeft, public fx_LayRight, public fx_LayMiddle {};
        inline size_t fx_lay_sizeof_diamond() { return sizeof(fx_LayDiamond); }
        inline size_t fx_lay_alignof_diamond() { return alignof(fx_LayDiamond); }
        inline size_t fx_lay_sizeof_deeper() { return sizeof(fx_LayDeeper); }
        inline size_t fx_lay_sizeof_three() { return sizeof(fx_LayThree); }
    "};
    let rs = quote! {
        assert_eq!(
            std::mem::size_of::<ffi::fx_LayDiamond>(),
            ffi::fx_lay_sizeof_diamond()
        );
        assert_eq!(
            std::mem::align_of::<ffi::fx_LayDiamond>(),
            ffi::fx_lay_alignof_diamond()
        );
        assert_eq!(
            std::mem::size_of::<ffi::fx_LayDeeper>(),
            ffi::fx_lay_sizeof_deeper()
        );
        assert_eq!(
            std::mem::size_of::<ffi::fx_LayThree>(),
            ffi::fx_lay_sizeof_three()
        );
    };
    run_test(
        "",
        hdr,
        rs,
        &[
            "fx_lay_sizeof_diamond",
            "fx_lay_alignof_diamond",
            "fx_lay_sizeof_deeper",
            "fx_lay_sizeof_three",
        ],
        &["fx_LayDiamond", "fx_LayDeeper", "fx_LayThree"],
    );
}

/// The other direction, so that the fix is not just "make empty classes
/// bigger": a chain of empty bases collapses onto one byte on every ABI, and a
/// class deriving from a single empty class is that class's size.
#[test]
fn test_chain_of_empty_bases_is_as_wide_as_cpp_makes_it() {
    let hdr = indoc! {"
        #include <cstddef>
        struct fx_ChainEmpty {};
        struct fx_ChainOne : public fx_ChainEmpty {};
        struct fx_ChainTwo : public fx_ChainOne {};
        struct fx_ChainThree : public fx_ChainTwo {};
        inline size_t fx_chain_sizeof() { return sizeof(fx_ChainThree); }
        inline size_t fx_chain_alignof() { return alignof(fx_ChainThree); }
    "};
    let rs = quote! {
        assert_eq!(
            std::mem::size_of::<ffi::fx_ChainThree>(),
            ffi::fx_chain_sizeof()
        );
        assert_eq!(
            std::mem::align_of::<ffi::fx_ChainThree>(),
            ffi::fx_chain_alignof()
        );
    };
    run_test(
        "",
        hdr,
        rs,
        &["fx_chain_sizeof", "fx_chain_alignof"],
        &["fx_ChainThree"],
    );
}

/// An empty class can also be wider than a byte because it was asked to be:
/// `alignas` applies to a class with nothing in it, and so does the size that
/// alignment forces.
///
/// MSVC warns C4324, "structure was padded due to alignment specifier", and the
/// harness builds fixtures with `/WX`. That warning is this test's subject
/// rather than something wrong with it: the padding it announces is the size
/// the class is being asked to keep, so a fixture which did not provoke it
/// would not be testing anything. It is turned off for the two declarations
/// which earn it and nowhere else, and only for the compiler which issues it.
#[test]
fn test_over_aligned_empty_class_keeps_the_alignment_cpp_gives_it() {
    let hdr = indoc! {"
        #include <cstddef>
        #ifdef _MSC_VER
        #pragma warning(push)
        #pragma warning(disable : 4324)
        #endif
        struct alignas(8) fx_AlignedEmpty {};
        struct fx_OverAligned : public fx_AlignedEmpty {};
        #ifdef _MSC_VER
        #pragma warning(pop)
        #endif
        inline size_t fx_aligned_sizeof() { return sizeof(fx_OverAligned); }
        inline size_t fx_aligned_alignof() { return alignof(fx_OverAligned); }
    "};
    let rs = quote! {
        assert_eq!(
            std::mem::size_of::<ffi::fx_OverAligned>(),
            ffi::fx_aligned_sizeof()
        );
        assert_eq!(
            std::mem::align_of::<ffi::fx_OverAligned>(),
            ffi::fx_aligned_alignof()
        );
    };
    run_test(
        "",
        hdr,
        rs,
        &["fx_aligned_sizeof", "fx_aligned_alignof"],
        &["fx_OverAligned"],
    );
}

/// A class deriving from an empty diamond, and a class holding one as a
/// member: the first gets the empty base optimisation and the second does not,
/// so the member's offset differs between them and both have to agree with
/// C++. Written against POD types so that the offsets are Rust's own.
#[test]
fn test_empty_diamond_as_base_and_as_member_matches_cpp() {
    let hdr = indoc! {"
        #include <cstddef>
        struct fx_DmEmpty {};
        struct fx_DmLeft : public fx_DmEmpty {};
        struct fx_DmRight : public fx_DmEmpty {};
        struct fx_DmDiamond : public fx_DmLeft, public fx_DmRight {};
        struct fx_DmOverBase : public fx_DmDiamond { int x; };
        struct fx_DmHolder { fx_DmDiamond d; int x; };
        struct fx_DmArray { fx_DmDiamond a[3]; int x; };
        inline size_t fx_dm_offset_over_base() {
            fx_DmOverBase v{};
            return reinterpret_cast<const char*>(&v.x) - reinterpret_cast<const char*>(&v);
        }
        inline size_t fx_dm_offset_holder() {
            fx_DmHolder v{};
            return reinterpret_cast<const char*>(&v.x) - reinterpret_cast<const char*>(&v);
        }
        inline size_t fx_dm_offset_array() {
            fx_DmArray v{};
            return reinterpret_cast<const char*>(&v.x) - reinterpret_cast<const char*>(&v);
        }
        inline size_t fx_dm_sizeof_array() { return sizeof(fx_DmArray); }
    "};
    let rs = quote! {
        assert_eq!(
            std::mem::offset_of!(ffi::fx_DmOverBase, x),
            ffi::fx_dm_offset_over_base()
        );
        assert_eq!(
            std::mem::offset_of!(ffi::fx_DmHolder, x),
            ffi::fx_dm_offset_holder()
        );
        assert_eq!(
            std::mem::offset_of!(ffi::fx_DmArray, x),
            ffi::fx_dm_offset_array()
        );
        assert_eq!(
            std::mem::size_of::<ffi::fx_DmArray>(),
            ffi::fx_dm_sizeof_array()
        );
    };
    run_test(
        "",
        hdr,
        rs,
        &[
            "fx_dm_offset_over_base",
            "fx_dm_offset_holder",
            "fx_dm_offset_array",
            "fx_dm_sizeof_array",
        ],
        &["fx_DmOverBase", "fx_DmHolder", "fx_DmArray"],
    );
}

/// A class which is not a POD for the purpose of layout lends its tail padding
/// to whatever the derived class puts after it, on the ABIs which do that.
/// bindgen stored the base in a field of the base's own type, which is
/// `sizeof(base)` bytes wide whatever the target chose, so the derived class
/// came out too wide and every member after the base was at the wrong offset.
/// This addresses the bug reported upstream as
/// rust-lang/rust-bindgen#380.
#[test]
fn test_base_tail_padding_holds_the_derived_class_members() {
    let hdr = indoc! {"
        #include <cstddef>
        struct fx_TailBase { fx_TailBase(); int i; char c; };
        struct fx_TailOne : public fx_TailBase { char d; };
        struct fx_TailTwo : public fx_TailBase { char d; char e; };
        struct fx_TailWide { fx_TailWide(); long long l; char c; };
        struct fx_TailWideDer : public fx_TailWide { char d; };
        inline size_t fx_tail_sizeof_one() { return sizeof(fx_TailOne); }
        inline size_t fx_tail_alignof_one() { return alignof(fx_TailOne); }
        inline size_t fx_tail_sizeof_two() { return sizeof(fx_TailTwo); }
        inline size_t fx_tail_sizeof_wide() { return sizeof(fx_TailWideDer); }
        inline size_t fx_tail_alignof_wide() { return alignof(fx_TailWideDer); }
    "};
    let cxx = indoc! {"
        fx_TailBase::fx_TailBase() : i(0), c(0) {}
        fx_TailWide::fx_TailWide() : l(0), c(0) {}
    "};
    let rs = quote! {
        assert_eq!(
            std::mem::size_of::<ffi::fx_TailOne>(),
            ffi::fx_tail_sizeof_one()
        );
        assert_eq!(
            std::mem::align_of::<ffi::fx_TailOne>(),
            ffi::fx_tail_alignof_one()
        );
        assert_eq!(
            std::mem::size_of::<ffi::fx_TailTwo>(),
            ffi::fx_tail_sizeof_two()
        );
        assert_eq!(
            std::mem::size_of::<ffi::fx_TailWideDer>(),
            ffi::fx_tail_sizeof_wide()
        );
        assert_eq!(
            std::mem::align_of::<ffi::fx_TailWideDer>(),
            ffi::fx_tail_alignof_wide()
        );
    };
    run_test(
        cxx,
        hdr,
        rs,
        &[
            "fx_tail_sizeof_one",
            "fx_tail_alignof_one",
            "fx_tail_sizeof_two",
            "fx_tail_sizeof_wide",
            "fx_tail_alignof_wide",
            "fx_TailOne",
            "fx_TailTwo",
            "fx_TailWideDer",
        ],
        &[],
    );
}

/// The same thing between one base and the next, where there is no member of
/// the derived class to notice it with, and again where there is one.
#[test]
fn test_base_tail_padding_between_two_bases_matches_cpp() {
    let hdr = indoc! {"
        #include <cstddef>
        struct fx_TwoFirst { fx_TwoFirst(); int i; char c; };
        struct fx_TwoSecond { fx_TwoSecond(); char x; };
        struct fx_TwoBases : public fx_TwoFirst, public fx_TwoSecond {};
        struct fx_TwoBasesField : public fx_TwoFirst, public fx_TwoSecond { char f; };
        inline size_t fx_two_sizeof() { return sizeof(fx_TwoBases); }
        inline size_t fx_two_alignof() { return alignof(fx_TwoBases); }
        inline size_t fx_two_sizeof_field() { return sizeof(fx_TwoBasesField); }
    "};
    let cxx = indoc! {"
        fx_TwoFirst::fx_TwoFirst() : i(0), c(0) {}
        fx_TwoSecond::fx_TwoSecond() : x(0) {}
    "};
    let rs = quote! {
        assert_eq!(
            std::mem::size_of::<ffi::fx_TwoBases>(),
            ffi::fx_two_sizeof()
        );
        assert_eq!(
            std::mem::align_of::<ffi::fx_TwoBases>(),
            ffi::fx_two_alignof()
        );
        assert_eq!(
            std::mem::size_of::<ffi::fx_TwoBasesField>(),
            ffi::fx_two_sizeof_field()
        );
    };
    run_test(
        cxx,
        hdr,
        rs,
        &[
            "fx_two_sizeof",
            "fx_two_alignof",
            "fx_two_sizeof_field",
            "fx_TwoBases",
            "fx_TwoBasesField",
        ],
        &[],
    );
}

/// The overshoot guard. A base which *is* a POD for the purpose of layout
/// keeps its tail padding on every ABI, so the derived class's own member
/// comes after the whole of it and the base stays a field of its own type -
/// which is what makes the derived class usable as a POD at all.
#[test]
fn test_pod_base_keeps_its_tail_padding() {
    let hdr = indoc! {"
        #include <cstddef>
        struct fx_PodTailBase { int i; char c; };
        struct fx_PodTailDer : public fx_PodTailBase { char d; };
        inline size_t fx_pod_tail_offset() {
            fx_PodTailDer v{};
            return reinterpret_cast<const char*>(&v.d) - reinterpret_cast<const char*>(&v);
        }
        inline size_t fx_pod_tail_sizeof() { return sizeof(fx_PodTailDer); }
    "};
    let rs = quote! {
        assert_eq!(
            std::mem::offset_of!(ffi::fx_PodTailDer, d),
            ffi::fx_pod_tail_offset()
        );
        assert_eq!(
            std::mem::size_of::<ffi::fx_PodTailDer>(),
            ffi::fx_pod_tail_sizeof()
        );
        let mut v = ffi::fx_PodTailDer::default();
        v.d = 7;
        assert_eq!(v.d, 7);
    };
    run_test(
        "",
        hdr,
        rs,
        &["fx_pod_tail_offset", "fx_pod_tail_sizeof"],
        &["fx_PodTailDer"],
    );
}

/// A packed base has no tail padding to lend, so the derived class's member
/// follows its last byte on every ABI and the base stays a field of its own
/// type. The packing has to survive the fix.
///
/// The second pair is the other way round: bases which are not packed, packed
/// into a class which is. `fx_PackTight` gives its second base a byte the base
/// class's own alignment would not have allowed, which is a class bindgen does
/// not call packed and so cannot lay out as fields of the bases' types at all.
///
/// `#pragma pack` rather than `__attribute__((packed))` because the Windows leg
/// builds these headers with cl.exe, which has no GNU attributes. The derived
/// class's member is an `int` so that bindgen calls that class packed too:
/// autocxx asks for `derive_copy(false)` and `derive_default(true)`, and
/// bindgen writes no derives at all on a packed struct which cannot derive
/// `Copy`, so a class it does not call packed which holds one it does gets a
/// `#[derive(Default)]` its field cannot satisfy and the bindings do not
/// compile. That is nothing to do with layout - it reproduces on this branch's
/// parent - and is recorded as its own item.
#[test]
fn test_packed_base_layout_matches_cpp() {
    let hdr = indoc! {"
        #include <cstddef>
        #pragma pack(push, 1)
        struct fx_PackBase { fx_PackBase(); int i; char c; };
        struct fx_PackDer : public fx_PackBase { int d; };
        #pragma pack(pop)
        struct fx_PackLoose1 { char a; };
        struct fx_PackLoose2 { int b; };
        #pragma pack(push, 1)
        struct fx_PackTight : public fx_PackLoose1, public fx_PackLoose2 { char d; };
        #pragma pack(pop)
        inline size_t fx_pack_sizeof() { return sizeof(fx_PackDer); }
        inline size_t fx_pack_alignof() { return alignof(fx_PackDer); }
        inline size_t fx_pack_offset() {
            fx_PackDer v;
            return reinterpret_cast<const char*>(&v.d) - reinterpret_cast<const char*>(&v);
        }
        inline size_t fx_pack_sizeof_tight() { return sizeof(fx_PackTight); }
        inline size_t fx_pack_alignof_tight() { return alignof(fx_PackTight); }
    "};
    let cxx = indoc! {"
        fx_PackBase::fx_PackBase() : i(0), c(0) {}
    "};
    let rs = quote! {
        assert_eq!(
            std::mem::size_of::<ffi::fx_PackDer>(),
            ffi::fx_pack_sizeof()
        );
        assert_eq!(
            std::mem::align_of::<ffi::fx_PackDer>(),
            ffi::fx_pack_alignof()
        );
        // Reading `d` at all is the check that the base is still a field of
        // its own type: a class whose bases were collapsed cannot be a `pod!`.
        assert_eq!(
            std::mem::offset_of!(ffi::fx_PackDer, d),
            ffi::fx_pack_offset()
        );
        assert_eq!(
            std::mem::size_of::<ffi::fx_PackTight>(),
            ffi::fx_pack_sizeof_tight()
        );
        assert_eq!(
            std::mem::align_of::<ffi::fx_PackTight>(),
            ffi::fx_pack_alignof_tight()
        );
    };
    run_test(
        cxx,
        hdr,
        rs,
        &[
            "fx_pack_sizeof",
            "fx_pack_alignof",
            "fx_pack_offset",
            "fx_pack_sizeof_tight",
            "fx_pack_alignof_tight",
            "fx_PackTight",
        ],
        &["fx_PackDer"],
    );
}

/// A base which introduces a vtable, and a base which holds a virtual base of
/// its own: in both the derived class's member goes inside the room the base's
/// own type claims, for the same reason and with the same consequence.
#[test]
fn test_virtual_bases_leave_members_where_cpp_puts_them() {
    let hdr = indoc! {"
        #include <cstddef>
        struct fx_VtBase { virtual ~fx_VtBase(); int i; char c; };
        struct fx_VtDer : public fx_VtBase { char d; };
        struct fx_VirtEmpty { fx_VirtEmpty(); int i; char c; };
        struct fx_VirtHolder : public virtual fx_VirtEmpty {};
        struct fx_VirtDer : public fx_VirtHolder { char d; };
        inline size_t fx_vt_sizeof() { return sizeof(fx_VtDer); }
        inline size_t fx_vt_alignof() { return alignof(fx_VtDer); }
        inline size_t fx_virt_sizeof() { return sizeof(fx_VirtDer); }
        inline size_t fx_virt_alignof() { return alignof(fx_VirtDer); }
    "};
    let cxx = indoc! {"
        fx_VtBase::~fx_VtBase() {}
        fx_VirtEmpty::fx_VirtEmpty() : i(0), c(0) {}
    "};
    let rs = quote! {
        assert_eq!(std::mem::size_of::<ffi::fx_VtDer>(), ffi::fx_vt_sizeof());
        assert_eq!(std::mem::align_of::<ffi::fx_VtDer>(), ffi::fx_vt_alignof());
        assert_eq!(std::mem::size_of::<ffi::fx_VirtDer>(), ffi::fx_virt_sizeof());
        assert_eq!(
            std::mem::align_of::<ffi::fx_VirtDer>(),
            ffi::fx_virt_alignof()
        );
    };
    run_test(
        cxx,
        hdr,
        rs,
        &[
            "fx_vt_sizeof",
            "fx_vt_alignof",
            "fx_virt_sizeof",
            "fx_virt_alignof",
            "fx_VtDer",
            "fx_VirtDer",
        ],
        &[],
    );
}

/// Bitfields on both sides of the base. The padding the derived class's member
/// goes into is the rest of the base's bitfield allocation unit, and where the
/// derived class's own first member is a bitfield it is a unit which has to be
/// measured against the bases in its own right - bindgen tracks those
/// separately from ordinary fields.
#[test]
fn test_bitfield_base_tail_padding_matches_cpp() {
    let hdr = indoc! {"
        #include <cstddef>
        struct fx_BitBase { fx_BitBase(); int a : 3; char c; };
        struct fx_BitDer : public fx_BitBase { char z; };
        struct fx_BitDerBits : public fx_BitBase { unsigned z : 3; };
        inline size_t fx_bit_sizeof() { return sizeof(fx_BitDer); }
        inline size_t fx_bit_alignof() { return alignof(fx_BitDer); }
        inline size_t fx_bit_sizeof_bits() { return sizeof(fx_BitDerBits); }
        inline size_t fx_bit_alignof_bits() { return alignof(fx_BitDerBits); }
    "};
    let cxx = indoc! {"
        fx_BitBase::fx_BitBase() : a(0), c(0) {}
    "};
    let rs = quote! {
        assert_eq!(std::mem::size_of::<ffi::fx_BitDer>(), ffi::fx_bit_sizeof());
        assert_eq!(
            std::mem::align_of::<ffi::fx_BitDer>(),
            ffi::fx_bit_alignof()
        );
        assert_eq!(
            std::mem::size_of::<ffi::fx_BitDerBits>(),
            ffi::fx_bit_sizeof_bits()
        );
        assert_eq!(
            std::mem::align_of::<ffi::fx_BitDerBits>(),
            ffi::fx_bit_alignof_bits()
        );
    };
    run_test(
        cxx,
        hdr,
        rs,
        &[
            "fx_bit_sizeof",
            "fx_bit_alignof",
            "fx_bit_sizeof_bits",
            "fx_bit_alignof_bits",
            "fx_BitDer",
            "fx_BitDerBits",
        ],
        &[],
    );
}

/// What a class whose bases were left less room than their own types costs.
/// The bases have no Rust type - they are the bytes the target gave them - so
/// no field of the class can be read from Rust and `pod!` has to be refused.
/// It used to be accepted, with every field after the base at an offset C++
/// does not use, which is the unsoundness this trades away.
///
/// Which classes those are is the ABI's answer, not autocxx's: the Itanium ABI
/// lends `fx_NoPodBase`'s tail padding to `d` and the MSVC ABI does not, so
/// under MSVC the base is a field of its own type and `pod!` is right to be
/// granted. The test asks for whichever of the two the compiler running it
/// produces.
#[test]
fn test_class_whose_bases_hold_its_members_is_refused_as_pod() {
    let hdr = indoc! {"
        #include <cstddef>
        struct fx_NoPodBase { fx_NoPodBase(); int i; char c; };
        struct fx_NoPodDer : public fx_NoPodBase { char d; };
        inline size_t fx_nopod_offset() {
            fx_NoPodDer v;
            return reinterpret_cast<const char*>(&v.d) - reinterpret_cast<const char*>(&v);
        }
    "};
    let cxx = indoc! {"
        fx_NoPodBase::fx_NoPodBase() : i(0), c(0) {}
    "};
    if cfg!(target_env = "msvc") {
        run_test(
            cxx,
            hdr,
            quote! {
                assert_eq!(
                    std::mem::offset_of!(ffi::fx_NoPodDer, d),
                    ffi::fx_nopod_offset()
                );
            },
            &["fx_nopod_offset"],
            &["fx_NoPodDer"],
        );
    } else {
        run_test_expect_fail_with_error(
            cxx,
            hdr,
            quote! {},
            &["fx_nopod_offset"],
            &["fx_NoPodDer"],
            "leaves its base classes less room",
        );
    }
}

/// `using Base::foo;` in a class re-exports a base class member through the
/// derived class. Where the base is private that is the *only* way to reach
/// the member: there is no upcast to reach it by.
///
/// bindgen generates nothing for such a declaration - there is nothing to
/// generate, the member already exists on the base - so before it reported
/// them the method was reachable in C++ and absent from the Rust bindings,
/// with `no method named `inherited`` the only sign of it.
#[test]
fn test_using_declaration_reexports_a_private_base_method() {
    let hdr = indoc! {"
        #include <cstdint>
        class fx_Base {
        public:
            uint32_t inherited(uint32_t x) const { return x + 1; }
        };
        class fx_Derived : private fx_Base {
        public:
            using fx_Base::inherited;
        };
    "};
    let rs = quote! {
        let d = ffi::fx_Derived::new().within_unique_ptr();
        assert_eq!(d.inherited(1), 2);
    };
    run_test("", hdr, rs, &["fx_Derived"], &[]);
}

/// A using-declaration is also how C++ widens the access of a `protected`
/// member, which is a second way for the member to be reachable through the
/// derived class and through no upcast.
#[test]
fn test_using_declaration_widens_access_to_a_protected_method() {
    let hdr = indoc! {"
        #include <cstdint>
        namespace fx_ns {
        class fx_Base {
        protected:
            uint32_t prot() const { return 7; }
        };
        }
        class fx_Derived : public fx_ns::fx_Base {
        public:
            using fx_ns::fx_Base::prot;
        };
    "};
    let rs = quote! {
        let d = ffi::fx_Derived::new().within_unique_ptr();
        assert_eq!(d.prot(), 7);
    };
    run_test("", hdr, rs, &["fx_Derived"], &[]);
}

/// The base a using-declaration names need not be the first one, and then its
/// subobject does not sit at offset zero. The generated call has to be made in
/// C++, where the compiler adjusts `this`; a Rust-side call through the
/// derived class's own pointer would read the wrong object and say nothing
/// about it.
#[test]
fn test_using_declaration_from_a_base_at_a_nonzero_offset() {
    let hdr = indoc! {"
        #include <cstdint>
        class fx_First {
        public:
            uint64_t padding = 12;
        };
        class fx_Second {
        public:
            uint32_t held = 42;
            uint32_t held_value() const { return held; }
        };
        class fx_Derived : private fx_First, private fx_Second {
        public:
            using fx_Second::held_value;
        };
    "};
    let rs = quote! {
        let d = ffi::fx_Derived::new().within_unique_ptr();
        assert_eq!(d.held_value(), 42);
    };
    run_test("", hdr, rs, &["fx_Derived"], &[]);
}

/// A name the base overloads is not imported. Which member `d.foo(args)`
/// selects is C++'s overload resolution to decide, and neither the parameter
/// types nor their number settle it: a longer overload may have default
/// arguments which make it callable with fewer, as here, and two of the same
/// length may differ only in ways which make the call ambiguous. bindgen
/// reports neither the default arguments nor enough of the types to tell.
#[test]
fn test_using_declaration_declines_a_name_the_base_overloads() {
    let hdr = indoc! {"
        #include <cstdint>
        class fx_B {
        public:
            uint32_t foo(uint32_t) const { return 1; }
            uint32_t foo(uint32_t, uint32_t = 0) const { return 2; }
        };
        class fx_D : private fx_B {
        public:
            using fx_B::foo;
        };
    "};
    run_test_ex(
        "",
        hdr,
        quote! {
            let _d = ffi::fx_D::new().within_unique_ptr();
        },
        directives_from_lists(&["fx_D"], &[], None),
        None,
        Some(Box::new(NoMethodNamed {
            ty: "fx_D",
            method: "foo",
        })),
        None,
    );
}

/// A virtual member imports like any other, and still dispatches virtually:
/// the generated call is written in C++ against the derived class, so which
/// override runs is the C++ compiler's decision and not a symbol autocxx
/// picked. `fx_make_most` hands back an `fx_Derived` whose dynamic type
/// overrides the member, so a call which dispatched statically would return
/// the base's answer instead.
#[test]
fn test_using_declaration_reexports_a_virtual_method() {
    let hdr = indoc! {"
        #include <cstdint>
        #include <memory>
        class fx_Base {
        public:
            virtual uint32_t which() const { return 1; }
            virtual ~fx_Base() {}
        };
        class fx_Derived : private fx_Base {
        public:
            using fx_Base::which;
        };
        class fx_Most : public fx_Derived {
        public:
            uint32_t which() const override { return 2; }
        };
        inline std::unique_ptr<fx_Derived> fx_make_most() {
            return std::unique_ptr<fx_Derived>(new fx_Most());
        }
    "};
    let rs = quote! {
        let plain = ffi::fx_Derived::new().within_unique_ptr();
        assert_eq!(plain.which(), 1);
        let most = ffi::fx_make_most();
        assert_eq!(most.which(), 2);
    };
    run_test("", hdr, rs, &["fx_Derived", "fx_make_most"], &[]);
}

/// `using Base::Base;` inherits constructors rather than importing a member,
/// and clang names such a declaration after the *derived* class. Inheriting
/// constructors is a feature of its own and autocxx does not offer it; what
/// this pins is that the declaration is recognised and passed over rather than
/// mistaken for a member called `fx_Derived`.
#[test]
fn test_inheriting_constructor_declaration_is_passed_over() {
    let hdr = indoc! {"
        #include <cstdint>
        class fx_Base {
        public:
            fx_Base() : held(1) {}
            explicit fx_Base(uint32_t v) : held(v) {}
            uint32_t get() const { return held; }
        private:
            uint32_t held;
        };
        class fx_Derived : public fx_Base {
        public:
            using fx_Base::fx_Base;
            using fx_Base::get;
        };
    "};
    let rs = quote! {
        let d = ffi::fx_Derived::new().within_unique_ptr();
        assert_eq!(d.get(), 1);
    };
    run_test("", hdr, rs, &["fx_Derived"], &[]);
}

/// A member the *importing* class also declares, with the same parameter list,
/// hides the one the using-declaration would have brought in - C++ says so,
/// and offers no way to call the base's through the derived class once it
/// does. Binding the base's anyway produced a shim which did not compile:
/// `d.foo()` here is `void` and the copied signature says `uint32_t`.
#[test]
fn test_using_declaration_defers_to_a_member_which_hides_it() {
    let hdr = indoc! {"
        #include <cstdint>
        class fx_B {
        public:
            uint32_t foo() const { return 1; }
        };
        class fx_D : private fx_B {
        public:
            using fx_B::foo;
            void foo() const {}
        };
    "};
    let rs = quote! {
        let d = ffi::fx_D::new().within_unique_ptr();
        d.foo();
    };
    run_test("", hdr, rs, &["fx_D"], &[]);
}

/// A class may write more than one using-declaration, for different names,
/// and each is imported on its own.
#[test]
fn test_using_declaration_imports_each_name_it_writes() {
    let hdr = indoc! {"
        #include <cstdint>
        class fx_B {
        public:
            uint32_t first() const { return 1; }
            uint32_t second(uint32_t a) const { return a + 1; }
            uint32_t hidden() const { return 3; }
        };
        class fx_D : private fx_B {
        public:
            using fx_B::first;
            using fx_B::second;
        };
    "};
    run_test_ex(
        "",
        hdr,
        quote! {
            let d = ffi::fx_D::new().within_unique_ptr();
            assert_eq!(d.first(), 1);
            assert_eq!(d.second(5), 6);
        },
        directives_from_lists(&["fx_D"], &[], None),
        None,
        Some(Box::new(NoMethodNamed {
            ty: "fx_D",
            method: "hidden",
        })),
        None,
    );
}

/// A `using Base::foo;` in a class which also declares a `foo` of its own is
/// the C++ idiom for merging the base's overloads into the derived class's
/// own set, and autocxx does not attempt it: nothing is imported, and the
/// class's own members are bound exactly as they were.
///
/// Which of the base's members is still callable through the derived class
/// then depends on hiding, on ref-qualifiers and on default arguments, of
/// which bindgen reports only the second - and answering from the name and
/// the parameter types produced C++ which did not compile in all three cases:
/// a return type which did not match the hidden member's, a call the derived
/// class's own private member refused, and a call made ambiguous by a default
/// argument.
#[test]
fn test_using_declaration_defers_to_a_member_of_the_same_name() {
    struct NothingImported;
    impl CodeCheckerFns for NothingImported {
        fn check_rust(&self, rs: syn::File) -> Result<(), TestError> {
            if quote::quote!(#rs).to_string().contains("foo1") {
                return Err(TestError::RsCodeExaminationFail(
                    "a second `foo` was bound on fx_D, so the base's was imported after all"
                        .to_string(),
                ));
            }
            Ok(())
        }
    }
    let hdr = indoc! {"
        #include <cstdint>
        class fx_B {
        public:
            uint32_t foo() const { return 1; }
        };
        class fx_D : public fx_B {
        public:
            using fx_B::foo;
            uint32_t foo(uint32_t a) const { return a + 1; }
        };
    "};
    run_test_ex(
        "",
        hdr,
        quote! {
            let d = ffi::fx_D::new().within_unique_ptr();
            assert_eq!(d.foo(5), 6);
        },
        directives_from_lists(&["fx_D"], &[], None),
        None,
        Some(Box::new(NothingImported)),
        None,
    );
}

/// A using-declaration may name any base, not only a direct one, so the class
/// it names is looked for through the whole ancestry. `fx_C` inherits `fx_A`
/// through `fx_B`, which declares nothing of its own.
#[test]
fn test_using_declaration_from_an_indirect_base() {
    let hdr = indoc! {"
        #include <cstdint>
        class fx_A {
        public:
            uint32_t reached() const { return 7; }
        };
        class fx_B : public fx_A {};
        class fx_C : private fx_B {
        public:
            using fx_A::reached;
        };
    "};
    let rs = quote! {
        let c = ffi::fx_C::new().within_unique_ptr();
        assert_eq!(c.reached(), 7);
    };
    run_test("", hdr, rs, &["fx_C"], &[]);
}

/// An imported name may not take a Rust name the importing class's own members
/// already took. Here `fx_D`'s two `foo` overloads are numbered `foo` and
/// `foo1` before anything is imported, and the base's literal `foo1` wants
/// `foo1` as its first and only occurrence.
#[test]
fn test_using_declaration_import_does_not_take_a_name_already_given() {
    let hdr = indoc! {"
        #include <cstdint>
        class fx_B {
        public:
            uint32_t foo1() const { return 99; }
        };
        class fx_D : private fx_B {
        public:
            using fx_B::foo1;
            uint32_t foo(uint32_t a) const { return a; }
            uint32_t foo(uint32_t a, uint32_t b) const { return a + b; }
        };
    "};
    let rs = quote! {
        let d = ffi::fx_D::new().within_unique_ptr();
        assert_eq!(d.foo(1), 1);
        assert_eq!(d.foo1(3, 4), 7);
        assert_eq!(d.foo11(), 99);
    };
    run_test("", hdr, rs, &["fx_D"], &[]);
}

/// A name imported from two bases at once is left alone for the same reason a
/// name the class declares itself is: which of the two the shim's
/// `d.foo(args)` selects is C++'s overload resolution to decide, and here it
/// decides the call is ambiguous.
#[test]
fn test_using_declaration_defers_to_the_same_name_from_two_bases() {
    let hdr = indoc! {"
        #include <cstdint>
        class fx_A {
        public:
            uint32_t foo(uint32_t) const { return 1; }
        };
        class fx_B {
        public:
            uint32_t foo(uint32_t, uint32_t = 0) const { return 2; }
        };
        class fx_D : private fx_A, private fx_B {
        public:
            using fx_A::foo;
            using fx_B::foo;
        };
    "};
    run_test_ex(
        "",
        hdr,
        quote! {
            let _d = ffi::fx_D::new().within_unique_ptr();
        },
        directives_from_lists(&["fx_D"], &[], None),
        None,
        Some(Box::new(NoMethodNamed {
            ty: "fx_D",
            method: "foo",
        })),
        None,
    );
}

/// A base reached by two paths is two base subobjects, and C++ rejects the
/// conversion to it at the call rather than at the declaration: the header is
/// accepted and `d.reached()` is not. So the member is not bound, rather than
/// bound to a shim which would not compile.
#[test]
fn test_using_declaration_declines_an_ambiguous_base_subobject() {
    let hdr = indoc! {"
        #include <cstdint>
        class fx_A {
        public:
            uint32_t reached() const { return 1; }
        };
        class fx_B : public fx_A {};
        class fx_C : public fx_A {};
        class fx_D : private fx_B, private fx_C {
        public:
            using fx_A::reached;
        };
    "};
    run_test_ex(
        "",
        hdr,
        quote! {
            let _d = ffi::fx_D::new().within_unique_ptr();
        },
        directives_from_lists(&["fx_D"], &[], None),
        None,
        Some(Box::new(NoMethodNamed {
            ty: "fx_D",
            method: "reached",
        })),
        None,
    );
}

/// A declaration autocxx cannot use still puts its base's members in the
/// derived class's lookup, so it has to be able to veto the others: here
/// `using fx_A::foo;` names a base reached twice and is dropped, and if that
/// left `using fx_B::foo;` looking uncontested, the shim generated for it
/// would make a call C++ finds ambiguous.
#[test]
fn test_using_declaration_dropped_for_one_base_still_vetoes_another() {
    let hdr = indoc! {"
        #include <cstdint>
        class fx_A {
        public:
            uint32_t foo(uint32_t, uint32_t = 0) const { return 1; }
        };
        class fx_L : public fx_A {};
        class fx_R : public fx_A {};
        class fx_B {
        public:
            uint32_t foo(uint32_t) const { return 2; }
        };
        class fx_D : private fx_L, private fx_R, private fx_B {
        public:
            using fx_A::foo;
            using fx_B::foo;
        };
    "};
    run_test_ex(
        "",
        hdr,
        quote! {
            let _d = ffi::fx_D::new().within_unique_ptr();
        },
        directives_from_lists(&["fx_D"], &[], None),
        None,
        Some(Box::new(NoMethodNamed {
            ty: "fx_D",
            method: "foo",
        })),
        None,
    );
}

/// A base which merged an overload set of its own passes the merge on: `fx_B`
/// writes `using fx_A::foo;` beside a `foo` of its own, so `using fx_B::foo;`
/// in `fx_D` names both, and a shim calling one of them by name would again be
/// ambiguous. Not synthesizing an import for `fx_B` does not take `fx_A`'s
/// overload out of C++'s lookup.
#[test]
fn test_using_declaration_declines_a_base_whose_own_set_is_merged() {
    let hdr = indoc! {"
        #include <cstdint>
        class fx_A {
        public:
            uint32_t foo(uint32_t, uint32_t = 0) const { return 1; }
        };
        class fx_B : public fx_A {
        public:
            using fx_A::foo;
            uint32_t foo(uint32_t) const { return 2; }
        };
        class fx_D : private fx_B {
        public:
            using fx_B::foo;
        };
    "};
    run_test_ex(
        "",
        hdr,
        quote! {
            let _d = ffi::fx_D::new().within_unique_ptr();
        },
        directives_from_lists(&["fx_D"], &[], None),
        None,
        Some(Box::new(NoMethodNamed {
            ty: "fx_D",
            method: "foo",
        })),
        None,
    );
}

/// Asserts that no inherent `impl` block for a given type binds a method of a
/// given name, for the using-declarations autocxx declines to import: without
/// it such a test passes whether or not the import happened, since what it
/// builds is the rest of the class.
///
/// Scoped to the type's own inherent impls because bindgen writes impl blocks
/// of its own inside the mod autocxx re-emits verbatim, and those do carry the
/// base class's members under their real names.
struct NoMethodNamed {
    ty: &'static str,
    method: &'static str,
}

impl CodeCheckerFns for NoMethodNamed {
    fn check_rust(&self, rs: syn::File) -> Result<(), TestError> {
        fn walk(items: &[syn::Item], ty: &str, method: &str) -> bool {
            items.iter().any(|item| match item {
                syn::Item::Mod(m) => m
                    .content
                    .as_ref()
                    .is_some_and(|(_, items)| walk(items, ty, method)),
                syn::Item::Impl(imp) => {
                    let self_ty = &imp.self_ty;
                    imp.trait_.is_none()
                        && quote::quote!(#self_ty).to_string() == ty
                        && imp.items.iter().any(|item| match item {
                            syn::ImplItem::Method(f) => f.sig.ident == method,
                            _ => false,
                        })
                }
                _ => false,
            })
        }
        if walk(&rs.items, self.ty, self.method) {
            return Err(TestError::RsCodeExaminationFail(format!(
                "`{}::{}` was bound, so the base class member was imported after all",
                self.ty, self.method
            )));
        }
        Ok(())
    }
}

/// Resolution by name has to be confined to names which were written through a
/// using-declaration, and a deduced return type is the shape which shows why.
/// `fx_deduced` returns `fx_use::fx_A`, which is `fx_n::fx_A`, which is
/// `double`; clang prints the deduced type as the bare `fx_A` it was deduced
/// from, with no declaration and with no node naming what it stands for. The
/// global `fx_A` - an `int`, imported somewhere so that it is on record -
/// answers to that same spelling. Resolving one to the other would bind this
/// function as returning an integer.
#[test]
fn test_deduced_return_is_not_resolved_to_a_using_declared_name() {
    let hdr = indoc! {"
        using fx_A = int;
        namespace fx_shadow { using ::fx_A; }
        namespace fx_n { using fx_A = double; }
        namespace fx_use {
            using fx_n::fx_A;
            inline auto fx_deduced() { return fx_A{1.5}; }
        }
    "};
    let rs = quote! {
        let d: f64 = ffi::fx_use::fx_deduced();
        assert_eq!(d, 1.5);
    };
    run_test("", hdr, rs, &["fx_use::fx_deduced"], &[]);
}

/// A class template someone wrote themselves, holding a pointer to its
/// argument the way `scoped_refptr` and the rest of the smart pointers people
/// write do. autocxx already carries an instantiation of one across the bridge
/// as an opaque type; what it cannot do by itself is look inside one, because
/// nothing tells it what the template means. A `smart_pointer!` directive is
/// that telling, and this is what it buys: `get`, answering with a pointer to
/// the payload.
///
/// Addresses the bug reported upstream as google/autocxx#670.
#[test]
fn test_smart_pointer_get() {
    let hdr = indoc! {"
        #include <cstdint>
        struct Widget { uint32_t value; };
        template<typename T>
        class MyPtr {
        public:
            MyPtr() : p_(nullptr) {}
            explicit MyPtr(T* p) : p_(p) {}
            MyPtr(MyPtr&& other) : p_(other.p_) { other.p_ = nullptr; }
            ~MyPtr() { delete p_; }
            T* get() const { return p_; }
        private:
            T* p_;
        };
        inline MyPtr<Widget> make_widget() { return MyPtr<Widget>(new Widget{42}); }
    "};
    run_test_ex(
        "",
        hdr,
        quote! {
            let p = ffi::make_widget();
            let widget = unsafe { &*p.get() };
            assert_eq!(widget.value, 42);
        },
        quote! {
            generate!("make_widget")
            generate_pod!("Widget")
            smart_pointer!("MyPtr")
        },
        None,
        None,
        None,
    );
}

/// A smart pointer which holds nothing answers with a null pointer, which is
/// the only emptiness question this surface asks: no two smart pointers spell
/// emptiness the same way, and `get` being null is what they all agree on.
///
/// Addresses the bug reported upstream as google/autocxx#670.
#[test]
fn test_smart_pointer_get_of_empty_is_null() {
    let hdr = indoc! {"
        #include <cstdint>
        struct Widget { uint32_t value; };
        template<typename T>
        class MyPtr {
        public:
            MyPtr() : p_(nullptr) {}
            explicit MyPtr(T* p) : p_(p) {}
            MyPtr(MyPtr&& other) : p_(other.p_) { other.p_ = nullptr; }
            ~MyPtr() { delete p_; }
            T* get() const { return p_; }
        private:
            T* p_;
        };
        inline MyPtr<Widget> make_nothing() { return MyPtr<Widget>(); }
    "};
    run_test_ex(
        "",
        hdr,
        quote! {
            let p = ffi::make_nothing();
            assert!(p.get().is_null());
        },
        quote! {
            generate!("make_nothing")
            generate_pod!("Widget")
            smart_pointer!("MyPtr")
        },
        None,
        None,
        None,
    );
}

/// `MyPtr<const Widget>::get` returns a `const Widget*`, so the shim is
/// declared returning one and Rust is handed a `*const` rather than a `*mut`.
/// The two have to agree exactly: cxx typechecks the bridge declaration against
/// the real C++ signature through a function pointer, which is an exact match
/// or a compile error.
///
/// Addresses the bug reported upstream as google/autocxx#670.
#[test]
fn test_smart_pointer_const_payload() {
    let hdr = indoc! {"
        #include <cstdint>
        struct Widget { uint32_t value; };
        template<typename T>
        class MyPtr {
        public:
            MyPtr() : p_(nullptr) {}
            explicit MyPtr(T* p) : p_(p) {}
            MyPtr(MyPtr&& other) : p_(other.p_) { other.p_ = nullptr; }
            ~MyPtr() { delete p_; }
            T* get() const { return p_; }
        private:
            T* p_;
        };
        typedef MyPtr<const Widget> ConstWidgetPtr;
        inline ConstWidgetPtr make_widget() { return ConstWidgetPtr(new Widget{42}); }
    "};
    run_test_ex(
        "",
        hdr,
        quote! {
            // Pinned as a function pointer rather than by assigning the
            // result: a `*mut Widget` would coerce to a `*const Widget` and the
            // assignment would prove nothing. Coercing the method itself
            // demands the signature match exactly.
            let get: fn(&ffi::ConstWidgetPtr) -> *const ffi::Widget = ffi::ConstWidgetPtr::get;
            let p = ffi::make_widget();
            assert_eq!(unsafe { &*get(p.as_ref().unwrap()) }.value, 42);
        },
        quote! {
            generate!("make_widget")
            generate!("ConstWidgetPtr")
            generate_pod!("Widget")
            smart_pointer!("MyPtr")
        },
        None,
        None,
        None,
    );
}

/// The directive names the template, and a template usually lives in a
/// namespace. Naming it in full works.
///
/// Addresses the bug reported upstream as google/autocxx#670.
#[test]
fn test_smart_pointer_in_namespace() {
    let hdr = indoc! {"
        #include <cstdint>
        namespace fx {
            struct Widget { uint32_t value; };
            template<typename T>
            class MyPtr {
            public:
                MyPtr() : p_(nullptr) {}
                explicit MyPtr(T* p) : p_(p) {}
                MyPtr(MyPtr&& other) : p_(other.p_) { other.p_ = nullptr; }
                ~MyPtr() { delete p_; }
                T* get() const { return p_; }
            private:
                T* p_;
            };
            inline MyPtr<Widget> make_widget() { return MyPtr<Widget>(new Widget{42}); }
        }
    "};
    run_test_ex(
        "",
        hdr,
        quote! {
            let p = ffi::fx::make_widget();
            let widget = unsafe { &*p.get() };
            assert_eq!(widget.value, 42);
        },
        quote! {
            generate!("fx::make_widget")
            generate_pod!("fx::Widget")
            smart_pointer!("fx::MyPtr")
        },
        None,
        None,
        None,
    );
}

